local config = {
  ui_story_5075_50750100_1_dialog_content = "(Setelah bertahan dalam perjalanan panjang dan berbahaya Shadowind melintasi laut, kami akhirnya tiba di pantai Longzhou.)",
  ui_story_5075_50750100_2_dialog_content = "(Yuebai dan Zhong Xu memiliki pengiriman yang harus mereka lakukan atas nama guild mereka, jadi mereka harus tinggal beberapa hari lagi.)",
  ui_story_5075_50750100_3_dialog_content = "(Persekutuan Lin dengan baik hati mengundang kita untuk bepergian bersama mereka...)",
  ui_story_5075_50750100_4_dialog_content = "(Tapi sebagai utusan resmi Astra, saya memilih untuk mengikuti Dantang dan Jiu ke ibu kota Kerajaan Ji terlebih dahulu.)",
  ui_story_5075_50750100_5_dialog_content = "Gadis Naga Ole, kepada kamu aku berdoa.",
  ui_story_5075_50750100_6_dialog_content = "Tolong jangan biarkan hujan turun. Fajar esok hari, tahu kering akan menjadi persembahanku untuk dikirim—",
  ui_story_5075_50750100_7_dialog_content = "<color=#e8d9bb>Byur.</color>",
  ui_story_5075_50750100_8_dialog_content = "Argh!",
  ui_story_5075_50750100_9_dialog_content = "Awas, PlayerName!",
  ui_story_5075_50750100_10_dialog_content = "Saya tahu Anda tertarik dengan pemandangan Kerajaan Ji, tetapi perahu sungai ini bukan Shadowind.",
  ui_story_5075_50750100_11_dialog_content = "Tolong coba untuk tidak terpesona sampai-sampai jatuh ke dalam air.",
  ui_story_5075_50750100_12_dialog_content = "Tidak mudah bagi saya untuk mendapatkan utusan yang dihargai seperti kalian semua dari Astra.",
  ui_story_5075_50750100_13_dialog_content = "Kamu telah menyeberangi samudra dan selamat dari serangan Eclipsite dan bajak laut tanpa cedera.",
  ui_story_5075_50750100_14_dialog_content = "Aku tidak bisa menanggung rasa bersalah dan kesalahan jika kamu tenggelam hanya beberapa langkah dari istana.",
  ui_story_5075_50750100_15_dialog_content = "Haha... Maaf telah membuatmu khawatir seperti itu.",
  ui_story_5075_50750100_16_dialog_content = "Saya begitu asyik mendengarkan lagu nelayan itu sampai-sampai saya lupa bahwa saya sendiri sedang berada di perahu.",
  ui_story_5075_50750100_17_dialog_content = "Saya telah mendengar lagu-lagu seperti itu sejak di pelabuhan.",
  ui_story_5075_50750100_18_dialog_content = "Nada-nada begitu ringan dan cepat, dan sepertinya liriknya dalam bahasa lokal. Apa yang mereka nyanyikan?",
  ui_story_5075_50750100_19_dialog_content = "Itu adalah lagu mendayung.",
  ui_story_5075_50750100_20_dialog_content = "Ji dipenuhi dengan danau dan sungai yang memberikan kehidupan bagi penduduknya. Alhasil, banyak penduduk yang menjadi nelayan dan pengemudi perahu.",
  ui_story_5075_50750100_21_dialog_content = "Seiring waktu, mereka mengembangkan lagu-lagu untuk memancing dan berlayar.",
  ui_story_5075_50750100_22_dialog_content = "Gunung yang subur, air yang jernih. Bunga-bunga yang mekar, pohon willow yang anggun. Itulah yang mereka nyanyikan.",
  ui_story_5075_50750100_23_dialog_content = "Dan melodi yang baru saja Anda dengar adalah yang mencari berkat dari para dewa.",
  ui_story_5075_50750100_24_dialog_content = "\"Dragon Maiden, tolong pastikan hari yang cerah dan pelayaran yang lancar.\"",
  ui_story_5075_50750100_25_dialog_content = "\"Aku akan memberimu tahu kering yang lezat setelah aku sampai di rumah dengan selamat.\"",
  ui_story_5075_50750100_26_dialog_content = "Itulah intinya.",
  ui_story_5075_50750100_27_dialog_content = "Oh, Gadis Naga!",
  ui_story_5075_50750100_28_dialog_content = "Bukankah <color=#FFB400>Dragon Maiden Over Turbulent Seas</color> adalah nama tarian yang kamu ajarkan kepada Vice di Twin Pavilions Bay?",
  ui_story_5075_50750100_29_dialog_content = "Saya ingat kamu mengatakan bahwa orang-orang pesisir Longzhou sangat menghormati Sang Maiden Naga.",
  ui_story_5075_50750100_30_dialog_content = "... Tapi apakah dewa benar-benar menyukai tahu kering sebanyak itu?",
  ui_story_5075_50750100_31_dialog_content = "Yah, tidak begitu. Penawaran dalam lagu rakyat sebenarnya bervariasi.",
  ui_story_5075_50750100_32_dialog_content = "Dragon Maiden tidak meminta persembahan, tetapi orang-orang tetap menambahkannya ke dalam lagu untuk menunjukkan rasa terima kasih mereka.",
  ui_story_5075_50750100_33_dialog_content = "Pria itu mungkin menyanyikan tentang tahu kering karena itu yang kebetulan dia miliki di rumah.",
  ui_story_5075_50750100_34_dialog_content = "Dan dia baik-baik saja dengan itu? Sungguh dewa yang aneh.",
  ui_story_5075_50750100_35_dialog_content = "Saya pikir saya telah belajar banyak tentang Longzhou saat berada di Twin Pavilions Bay...",
  ui_story_5075_50750100_36_dialog_content = "Tapi sekarang setelah saya berada di sini, rasanya seperti saya belajar sesuatu yang baru setiap langkah yang saya ambil.",
  ui_story_5075_50750100_37_dialog_content = "Saya hanya berharap Vice dan Carleen juga ada di sini untuk melihatnya.",
  ui_story_5075_50750100_38_dialog_content = "Itu mungkin terjadi lebih cepat dari yang Anda pikirkan.",
  ui_story_5075_50750100_39_dialog_content = "Benar! Bagaimanapun, misi kita adalah untuk memperkuat hubungan antara kedua negeri kita.",
  ui_story_5075_50750100_40_dialog_content = "Jika semuanya berjalan lancar, mungkin teman-teman saya dari Astra akan bisa mengunjungi Longzhou dan melihat semuanya dengan mata mereka sendiri!",
  ui_story_5075_50750100_41_dialog_content = "Selain bertukar strategi dan teknologi untuk melawan Eclipsite.",
  ui_story_5075_50750100_42_dialog_content = "Komunikasi dan kerjasama hanya dapat memfasilitasi perdamaian bagi kedua orang.",
  ui_story_5075_50750100_43_dialog_content = "Saya rasa kami harus mengandalkanmu sebagai utusan untuk mewujudkan visi tersebut.",
  ui_story_5075_50750100_44_dialog_content = "<color=#e8d9bb>Gedebuk.</color>",
  ui_story_5075_50750100_45_dialog_content = "Kita sudah mendarat, dan tujuan ada di depan, Yang Mulia dan PlayerName.",
  ui_story_5075_50750100_46_dialog_content = "Kita harus turun di sini untuk masuk ke kota.",
  ui_story_5075_50750100_47_dialog_content = "Mohon tunggu sebentar, PlayerName.",
  ui_story_5075_50750100_48_dialog_content = "<color=#e8d9bb>Dantang turun dari kapal, tersenyum dan membungkuk sedikit.</color>",
  ui_story_5075_50750100_49_dialog_content = "Saya adalah Putri Zhuohua, ditugaskan oleh Raja Ji untuk menjadi duta besar ke Astra.",
  ui_story_5075_50750100_50_dialog_content = "Yang Mulia telah menerima undangan saya dan melakukan perjalanan jauh ke Longzhou.",
  ui_story_5075_50750100_51_dialog_content = "Untuk itu, izinkan saya sekali lagi mengungkapkan rasa terima kasih dan penghargaan saya.",
  ui_story_5075_50750100_52_dialog_content = "Selamat datang di <color=#FFB400>ibu kota Kerajaan Ji</color>—",
  ui_story_5075_50750100_53_dialog_content = "<color=#FFB400>Haojin</color>.",
  ui_story_5075_50750100_54_dialog_content = "Jangan sebutkan itu, dan terima kasih telah mengundangku!",
  ui_story_5075_50750100_55_dialog_content = "Sekarang saatnya bagi saya untuk menepati janji saya sebagai utusan Astra.",
  ui_story_5075_50750100_56_dialog_content = "Yang Mulia, para pelayan kerajaan telah datang. Kita harus kembali ke istana dan raja.",
  ui_story_5075_50750100_57_dialog_content = "Nah, PlayerName...",
  ui_story_5075_50750100_58_dialog_content = "Salam, Yang Mulia, utusan yang terhormat.",
  ui_story_5075_50750100_59_dialog_content = "Saya adalah pengurus Rumah Tamu Kerajaan, dan merupakan suatu kehormatan besar memiliki Anda sebagai tamu kami, utusan terhormat.",
  ui_story_5075_50750100_60_dialog_content = "Penginapan akan menangani semua kegiatan sehari-hari dan pengaturan keamanan untuk Anda selama Anda berada di Kerajaan Ji.",
  ui_story_5075_50750100_61_dialog_content = "Sepertinya kita harus berpisah untuk sekarang.",
  ui_story_5075_50750100_62_dialog_content = "Setelah saya selesai dengan urusan resmi dan Yuebai kembali dalam dua hari, kita akan berkumpul kembali. Saya akan mengajak Anda berkeliling Haojin.",
  ui_story_5075_50750100_63_dialog_content = "Festival Musim Semi akan segera tiba. Ini adalah waktu paling dirayakan di Longzhou.",
  ui_story_5075_50750100_64_dialog_content = "Jalanan akan dipenuhi dengan lentera berwarna-warni, naga-naga yang menari, serta pameran yang menampilkan berbagai penjual camilan.",
  ui_story_5075_50750100_65_dialog_content = "Ini pasti akan meninggalkan kesan abadi pada dirimu.",
  ui_story_5075_50750100_66_dialog_content = "Menantikannya!",
  ui_story_5075_50750100_67_dialog_content = "(Siapa sangka rencana sederhana seperti ini malah berakhir penuh dengan komplikasi...)",
  ui_story_5075_50750100_68_dialog_content = "<color=#e8d9bb>Penginapan Kerajaan</color>",
  ui_story_5075_50750100_69_dialog_content = "Yang Mulia, silakan minum teh.",
  ui_story_5075_50750100_70_dialog_content = "Ini adalah teh bambu amethyst, diseduh dengan air mata air segar yang baru saja dibawa turun dari gunung, menawarkan rasa yang murni dan manis yang tak tertandingi.",
  ui_story_5075_50750100_71_dialog_content = "Ini lezat! Terima kasih.",
  ui_story_5075_50750100_72_dialog_content = "Utusan yang terhormat, saya tidak yakin tentang preferensi Anda, jadi saya telah menyiapkan berbagai jenis camilan.",
  ui_story_5075_50750100_73_dialog_content = "Di sini ada golden cream crisp, kue tujuh lapis, dan bola embun giok... Jika Anda ingin sesuatu yang lain, cukup beri tahu kami.",
  ui_story_5075_50750100_74_dialog_content = "Itu cukup beragam jenis camilannya!",
  ui_story_5075_50750100_75_dialog_content = "Utusan yang terhormat, biarkan saya membantu Anda berganti pakaian dan mandi.",
  ui_story_5075_50750100_76_dialog_content = "Ti-Ti-Tidak, terima kasih! Saya bisa melakukannya sendiri!",
  ui_story_5075_50750100_77_dialog_content = "K-Kalian benar-benar tahu bagaimana merawat tamu...",
  ui_story_5075_50750100_78_dialog_content = "Itu membuatku merasa cukup gugup. Aku tidak ingin merusak citra Astra dengan melakukan sesuatu yang salah, kamu tahu?",
  ui_story_5075_50750100_79_dialog_content = "Kita seharusnya pergi ke istana besok untuk membahas urusan resmi, jadi saya rasa saya tidak akan berada di sini untuk waktu yang lama.",
  ui_story_5075_50750100_80_dialog_content = "<color=#e8d9bb>Hari Kedua</color>",
  ui_story_5075_50750100_81_dialog_content = "Seseorang datang! Apakah mereka di sini untuk memanggilku ke istana?",
  ui_story_5075_50750100_82_dialog_content = "Duta yang terhormat, raja kami sangat senang mengetahui bahwa Anda telah datang jauh-jauh dari luar negeri.",
  ui_story_5075_50750100_83_dialog_content = "Jadi dia mengirimku untuk memberikan hadiah sambutan untukmu, termasuk teh dan buah-buahan langka, pakaian mewah dan sutra, serta berbagai wewangian.",
  ui_story_5075_50750100_84_dialog_content = "Apakah ini benar-benar semua untukku? Tapi...",
  ui_story_5075_50750100_85_dialog_content = "Sekarang hadiah-hadiah sudah terkirim, saya akan pamit.",
  ui_story_5075_50750100_86_dialog_content = "May semoga Anda menikmati kesehatan yang baik selama tinggal di Ji untuk meredakan kecemasan Tuan Putri Zhuohua, Yang Mulia.",
  ui_story_5075_50750100_87_dialog_content = "<color=#e8d9bb>Hari Ketiga</color>",
  ui_story_5075_50750100_88_dialog_content = "... Kenapa aku belum dipanggil ke istana ya?",
  ui_story_5075_50750100_89_dialog_content = "Apakah Anda merasa bosan, Yang Mulia? Bagaimana dengan menonton opera?",
  ui_story_5075_50750100_90_dialog_content = "Jika kamu tertarik, saya bisa mendapatkan beberapa penampil kelas atas untuk mengadakan pertunjukan untukmu.",
  ui_story_5075_50750100_91_dialog_content = "Bukan itu maksudku...",
  ui_story_5075_50750100_92_dialog_content = "Bukan gayamu? Bagaimana dengan pertunjukan Pingtan atau pertunjukan jalanan?",
  ui_story_5075_50750100_93_dialog_content = "Jika tidak ada yang menarik minatmu, kamu bisa mencoba pertarungan cricket, pertarungan burung puyuh, dan banyak hiburan lainnya di Kota Haojin.",
  ui_story_5075_50750100_94_dialog_content = "Tidak, aku benar-benar tidak butuh hal-hal semacam itu sekarang...",
  ui_story_5075_50750100_95_dialog_content = "Saya hanya ingin pergi bertemu dengan penguasa Kerajaan Ji!",
  ui_story_5075_50750100_96_dialog_content = "<color=#e8d9bb>Hari Keempat</color>",
  ui_story_5075_50750100_97_dialog_content = "Ah, akhirnya bebas.",
  ui_story_5075_50750100_98_dialog_content = "Tempat apa ini? Dengan semua tanda ini, saya ragu raja tinggal di sekitar sini...",
  ui_story_5075_50750100_99_dialog_content = "Utusan yang terhormat, menanggapi pertanyaan Anda, sepertinya Anda melewatkan makan beberapa hari terakhir ini, mungkin karena bosan.",
  ui_story_5075_50750100_100_dialog_content = "Jadi, saya berbicara dengan pramugara untuk membuat jadwal yang menyenangkan untuk Anda.",
  ui_story_5075_50750100_101_dialog_content = "Untuk pertama kalinya di Haojin, Kuil Gadis Naga di Pegunungan Selatan adalah tempat yang wajib dikunjungi.",
  ui_story_5075_50750100_102_dialog_content = "Selain pemandangan megah dengan puncak-puncak menjulang dan batuan yang rumit, konon ada keajaiban yang ditunjukkan oleh Sang Maiden Naga.",
  ui_story_5075_50750100_103_dialog_content = "Silakan nikmati pemandangan atau berdoa. Semua orang lain telah diusir, jadi tidak ada yang akan mengganggumu.",
  ui_story_5075_50750100_104_dialog_content = "Hah? Kamu menyuruh orang-orang pergi hanya untukku? Tidak heran tempat ini begitu sepi...",
  ui_story_5075_50750100_105_dialog_content = "Anda benar-benar tidak perlu repot-repot seperti ini. Saya bukan orang penting atau apa pun, dan saya jelas tidak keberatan menjadi bagian dari kerumunan.",
  ui_story_5075_50750100_106_dialog_content = "Anda bercanda, utusan terhormat. Anda adalah tamu kehormatan dari Kerajaan Ji, dan kami berdedikasi untuk melayani Anda dengan upaya terbaik kami.",
  ui_story_5075_50750100_107_dialog_content = "Jangan sungkan, silakan bersenang-senang.",
  ui_story_5075_50750100_108_dialog_content = "(Baiklah... Aku sudah di sini, jadi aku mungkin juga akan melihat-lihat.)",
  ui_story_5075_50750100_109_dialog_content = "(Ada patung yang sangat mengesankan berdiri di tengah aula utama. Apakah itu Dragon Maiden?)",
  ui_story_5075_50750100_110_dialog_content = "(Ada berbagai jenis penawaran seperti yang Dantang katakan, mulai dari buah dan sayuran hingga teh dan camilan...)",
  ui_story_5075_50750100_111_dialog_content = "Hah? Ada orang lain juga di sini?",
  ui_story_5075_50750100_112_dialog_content = "<color=#e8d9bb>ding—</color>",
  ui_story_5075_50750100_113_dialog_content = "Saya penasaran dayang mana yang menjatuhkan ini... Atau ini milik orang asing yang baru saja saya lihat?",
  ui_story_5075_50750100_114_dialog_content = "Utusan terhormat—",
  ui_story_5075_50750100_115_dialog_content = "Saya sudah memeriksa tempat ini berkali-kali. Tidak ada orang lain di kuil ini selain kamu.",
  ui_story_5075_50750100_116_dialog_content = "Tapi saya yakin saya baru saja melihat seseorang di sini. Sepertinya mereka juga menjatuhkan sesuatu...",
  ui_story_5075_50750100_117_dialog_content = "Aku tidak melihat apa pun... Hah?",
  ui_story_5075_50750100_118_dialog_content = "Ke mana perginya semua persembahan?",
  ui_story_5075_50750100_119_dialog_content = "Ba-Bagaimana bisa...",
  ui_story_5075_50750100_120_dialog_content = "Mohon terima permintaan maaf kami, Yang Mulia. Itu adalah kelalaian kami membiarkan seorang pencuri lolos.",
  ui_story_5075_50750100_121_dialog_content = "Arwah jahat pasti tidak berani mendekati Kuil Gadis Naga. Pasti lagi-lagi ulah fiendlings yang licik itu...",
  ui_story_5075_50750100_122_dialog_content = "Apa masalah dengan fiendlings?",
  ui_story_5075_50750100_123_dialog_content = "Bukan masalah besar, tidak layak untuk Anda khawatirkan, utusan terhormat.",
  ui_story_5075_50750100_124_dialog_content = "Ini adalah kelalaian kami. Tolong, turunlah bersama penjaga terlebih dahulu. Saya akan melaporkan ini kepada pengurus.",
  ui_story_5075_50750100_125_dialog_content = "Penjaga! Antar utusan kembali ke rumah tamu!",
  ui_story_5075_50750100_126_dialog_content = "Benar!",
  ui_story_5075_50750100_127_dialog_content = "T-Tunggu, semua orang... Setidaknya biarkan aku mendapatkan beberapa helaan udara segar lagi—",
  ui_story_5075_50750100_128_dialog_content = "(Beberapa hari berikutnya tidak berbeda dari sebelumnya.)",
  ui_story_5075_50750100_129_dialog_content = "(Aku makan, aku tidur, dan aku menikmati diriku... Mereka merawatku dengan segala cara, dan pengawal mengawaliku kemanapun aku pergi.)",
  ui_story_5075_50750100_130_dialog_content = "(Tapi tidak ada yang memberi saya jawaban langsung setiap kali saya bertanya tentang pergi ke istana.)",
  ui_story_5075_50750100_131_dialog_content = "Tidak ada yang akan selesai dengan keadaan seperti ini. Sebaiknya saya langsung bicara dengan pramugara itu sendiri.",
  ui_story_5075_50750100_132_dialog_content = "Aku perlu mendapatkan audiensi dengan raja, atau Dantang dan aku tidak akan pernah menyelesaikan misi kita.",
  ui_story_5075_50750100_133_dialog_content = "Aku hanya berharap tidak ada pengawal yang menghalangi jalanku...",
  ui_story_5075_50750100_134_dialog_content = "... Putri Zhuohua.",
  ui_story_5075_50750100_135_dialog_content = "(Hah? Apakah seseorang baru saja membicarakan Dantang?)",
  ui_story_5075_50750100_136_dialog_content = "Apakah berita ini benar?",
  ui_story_5075_50750100_137_dialog_content = "Haha, kamu tahu, tidak ada asap tanpa api.",
  ui_story_5075_50750100_138_dialog_content = "Saya dengar pangeran mahkota kita sangat jatuh cinta pada putri itu. Dia hanya memiliki mata untuknya.",
  ui_story_5075_50750100_139_dialog_content = "Putri belum setuju. Namun, pelayan di istana mengatakan bahwa raja berniat mengatur pernikahan untuk mereka.",
  ui_story_5075_50750100_140_dialog_content = "Itu masuk akal! Tidak heran istana itu ramai, terlalu sibuk untuk peduli tentang hal lain.",
  ui_story_5075_50750100_141_dialog_content = "Oh my, bebek kecil itu benar-benar telah berubah menjadi angsa! Jika saya tidak salah ingat, bukankah dia di sini untuk melunasi hutang?",
  ui_story_5075_50750100_142_dialog_content = "?",
  ui_story_5075_50750100_143_dialog_content = "Maaf, tapi siapa yang kamu bicarakan—",
  ui_story_5075_50750100_144_dialog_content = "Ternyata kamu ada di sini, utusan yang terhormat. Aku telah mencarimu ke mana-mana.",
  ui_story_5075_50750100_145_dialog_content = "Raja telah mengeluarkan dekrit, khusus mengundang Anda untuk menghadiri perjamuan besar hari ini dan berbagi wawasan Anda tentang urusan luar negeri.",
  ui_story_5075_50750100_146_dialog_content = "Silakan pergi dan bersiap-siap sekarang, lalu saya akan membimbing Anda ke istana.",
  ui_story_5075_50750100_147_dialog_content = "Maksudmu sekarang? Kenapa tidak ada yang memberitahuku lebih awal?",
  ui_story_5075_50750201_1_dialog_content = "<color=#e8d9bb>Jade menara, gerbang emas, megah dan agung. Melodi dalam harmoni, bergema di tanah kekaisaran.</color>",
  ui_story_5075_50750201_2_dialog_content = "Utusan dari Astra, silakan masuk ke istana kerajaan!",
  ui_story_5075_50750201_3_dialog_content = "Ternyata orang-orang dari tanah barat memang terlihat berbeda dari kita.",
  ui_story_5075_50750201_4_dialog_content = "Pakaian-pakaian ini cukup baru, meskipun jahitan yang ketat mengurangi keanggunannya.",
  ui_story_5075_50750201_5_dialog_content = "Kabarnya dia seorang Caelestite, cukup langka bahkan di tanah barat.",
  ui_story_5075_50750201_6_dialog_content = "(Tampaknya mereka sedang membicarakan tentang saya.)",
  ui_story_5075_50750201_7_dialog_content = "(Dantang juga di sini, dan tampaknya tidak ada yang mengganggunya, tetapi dia tampak cukup tegang.)",
  ui_story_5075_50750201_8_dialog_content = "Kamu PlayerName, 'kan? Kabarnya kamu telah melakukan banyak hal untuk memulihkan jalur laut antara dua benua.",
  ui_story_5075_50750201_9_dialog_content = "Bertemu denganmu sekarang, saya bisa katakan bahwa kamu memang bakat muda.",
  ui_story_5075_50750201_10_dialog_content = "Kamu memujiku terlalu banyak. Shadowind hanya bisa kembali dengan selamat berkat usaha bersama semua orang...",
  ui_story_5075_50750201_11_dialog_content = "Tidak perlu merendah. Ada yang bisa, sajikan tamu kita teh.",
  ui_story_5075_50750201_12_dialog_content = "Sangat jarang bertemu dengan seorang pelancong dari seberang laut. Bagaimana kalau Anda berbagi beberapa cerita tentang negeri asing dengan kami?",
  ui_story_5075_50750201_13_dialog_content = "Dikatakan bahwa ada raksasa baja yang ahli dalam perang di benua Anda.",
  ui_story_5075_50750201_14_dialog_content = "Raksasa-raksasa itu, yang dikendalikan oleh prajurit di dalamnya hanya dengan pikiran saja, memiliki mata yang berkilau seperti petir dan kekuatan untuk menggerakkan gunung. Apakah itu benar?",
  ui_story_5075_50750201_X14_option_content = "Itu terlalu banyak...",
  ui_story_5075_50750201_15_dialog_content = "Itu... sedikit berlebihan.",
  ui_story_5075_50750201_16_dialog_content = "Teknologi Astra belum sampai di level itu.",
  ui_story_5075_50750201_17_dialog_content = "Meski benar kita memiliki Colossi, mereka bukanlah senjata luar biasa seperti yang kamu deskripsikan.",
  ui_story_5075_50750201_18_dialog_content = "Belum lagi jumlah mereka yang tersisa tidak banyak, dan hanya beberapa orang di dunia ini yang bisa mengendalikannya.",
  ui_story_5075_50750201_X18_option_content = "Mungkin di masa depan, meskipun begitu.",
  ui_story_5075_50750201_X19_dialog_content = "Meskipun kekuatan sebesar itu tidak ada sekarang...",
  ui_story_5075_50750201_X20_dialog_content = "Dengan adanya Federasi Illumina yang cakap dalam teknologi militer dan Lumopolis yang mahir dalam sihir ritual...",
  ui_story_5075_50750201_X21_dialog_content = "Mungkin suatu hari, Astra akan menciptakan raksasa yang kamu deskripsikan.",
  ui_story_5075_50750201_X22_dialog_content = "Oh, jadi kamu bilang tidak ada hal seperti itu.",
  ui_story_5075_50750201_19_dialog_content = "Lalu bagaimana prajuritmu menghadapi roh jahat dalam pertempuran?",
  ui_story_5075_50750201_20_dialog_content = "Militer kita meneliti dan memproduksi berbagai jenis senjata dan baju besi untuk melawan mereka.",
  ui_story_5075_50750201_21_dialog_content = "Dikombinasikan dengan Luminatics, mereka memungkinkan kita untuk menangkis Eclipsites... atau \"roh jahat,\" seperti yang kamu sebut.",
  ui_story_5075_50750201_22_dialog_content = "Jadi, kamu masih mengandalkan kekuatan fisik dalam pertempuran, ya?",
  ui_story_5075_50750201_23_dialog_content = "Nah, di benua luas milikmu, apakah ada teknik keabadian atau cara untuk naik tingkat?",
  ui_story_5075_50750201_24_dialog_content = "Aku, uh... Kurasa tidak.",
  ui_story_5075_50750201_25_dialog_content = "Kami memiliki beberapa orang yang hidup lama di tanah kami. Bahkan, ratu Northland terkenal dengan penampilannya yang selalu muda.",
  ui_story_5075_50750201_26_dialog_content = "Tapi sejauh ini tentang orang-orang abadi sejati... Aku takut aku belum pernah mendengar tentang mereka.",
  ui_story_5075_50750201_27_dialog_content = "Hmm, sepertinya meskipun ada laut di antaranya, benua lain itu tidak jauh berbeda dari Longzhou kita.",
  ui_story_5075_50750201_28_dialog_content = "Tidak sepenuhnya benar—",
  ui_story_5075_50750201_29_dialog_content = "Ehem.",
  ui_story_5075_50750201_30_dialog_content = "(Jangan impulsif.)",
  ui_story_5075_50750201_31_dialog_content = "...",
  ui_story_5075_50750201_32_dialog_content = "Lebih menarik lagi, saya dengar bahwa, PlayerName, kamu memiliki beberapa keterampilan yang unik.",
  ui_story_5075_50750201_33_dialog_content = "Dan mereka dapat menguatkan kekuatan Force Arts beberapa kali lipat.",
  ui_story_5075_50750201_34_dialog_content = "Bagaimana jika saya menunjuk Anda ke posisi nominal sehingga Anda bisa tinggal di Kerajaan Ji?",
  ui_story_5075_50750201_35_dialog_content = "Kamu telah melihat keindahan Kota Haojin secara langsung beberapa hari ini.",
  ui_story_5075_50750201_36_dialog_content = "Kerajaan Ji kami, yang diberkati dengan tanah dan laut yang melimpah, berkembang di semua aspek, seperti surga di bumi.",
  ui_story_5075_50750201_37_dialog_content = "Bukankah ini jauh lebih baik daripada tanah yang dikuasai oleh roh jahat?",
  ui_story_5075_50750201_38_dialog_content = "Hmm, aku menghargai sikap baikmu, tapi Astra adalah rumahku. Lebih cepat atau lambat, aku harus kembali.",
  ui_story_5075_50750201_39_dialog_content = "Bukan hanya itu, aku tidak di sini untuk kesenangan pribadi. Aku datang sebagai utusan untuk mempromosikan hubungan yang lebih baik antara negeri kita.",
  ui_story_5075_50750201_40_dialog_content = "Kembali di Astra, kami telah mengembangkan berbagai jenis tindakan pencegahan Eclipsite yang efektif. Baik itu Illumina atau Lumopolis—",
  ui_story_5075_50750201_41_dialog_content = "Yah, kamu benar. Tapi biarkan Kantor Perdagangan Maritim menangani masalah sekecil itu.",
  ui_story_5075_50750201_42_dialog_content = "Membahas hal-hal ini sekarang akan sia-sia di momen indah seperti ini.",
  ui_story_5075_50750201_43_dialog_content = "Festival Musim Semi semakin dekat, dan Ji dipenuhi dengan kemakmuran dan keajaiban. Kita harus merayakannya bersama.",
  ui_story_5075_50750201_44_dialog_content = "Semuanya, angkat gelas kalian!",
  ui_story_5075_50750201_45_dialog_content = "Tapi—",
  ui_story_5075_50750201_46_dialog_content = "Ini untuk panjang umur sang raja dan pemerintahannya yang abadi!",
  ui_story_5075_50750201_47_dialog_content = "Ini untuk melimpah dan makmur Kerajaan Ji!",
  ui_story_5075_50750201_48_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50750201_49_dialog_content = "Ini gempa bumi!",
  ui_story_5075_50750201_50_dialog_content = "Cepat, lindungi raja!",
  ui_story_5075_50750201_51_dialog_content = "<color=#e8d9bb>Meja dan kursi bergoyang, piring beradu dan jatuh, dan getaran membutuhkan waktu untuk benar-benar mereda.</color>",
  ui_story_5075_50750201_52_dialog_content = "<color=#e8d9bb>Aula besar yang semarak sejenak lalu, kini berantakan, dipenuhi suara orang-orang yang berlarian dan berteriak memberi perintah.</color>",
  ui_story_5075_50750201_53_dialog_content = "<color=#e8d9bb>Para pejabat yang baru saja penuh semangat, kini tampak cukup kusut.</color>",
  ui_story_5075_50750201_54_dialog_content = "Fyuh, nyaris saja, tapi saya baru saja mendapatkan kabar baik bahwa orang-orang aman.",
  ui_story_5075_50750201_55_dialog_content = "Bukan seperti yang aku rencanakan, tapi inilah akhir dari jamuan makan hari ini.",
  ui_story_5075_50750201_56_dialog_content = "Dantang?",
  ui_story_5075_50750201_57_dialog_content = "Ayo, PlayerName. Mari kita pergi ke tempat yang lebih sepi.",
  ui_story_5075_50750201_58_dialog_content = "Sepertinya ikat kepala ku tersangkut sesuatu...",
  ui_story_5075_50750201_59_dialog_content = "Maaf, Dantang, tapi bisakah kamu membantu saya?",
  ui_story_5075_50750201_60_dialog_content = "Bunga-bunga di pohon ini sangat cantik. Saya tidak ingin tanpa sengaja merusak sesuatu yang begitu berharga.",
  ui_story_5075_50750201_61_dialog_content = "Hee, bunga plum ini sebenarnya tidak berharga tetapi sangat umum. Mungkin saja kamu adalah orang pertama yang memperlakukan mereka dengan begitu lembut.",
  ui_story_5075_50750201_62_dialog_content = "Tolong tetap diam dan biarkan aku membebaskanmu.",
  ui_story_5075_50750201_63_dialog_content = "...",
  ui_story_5075_50750201_64_dialog_content = "Oke, sudah selesai.",
  ui_story_5075_50750201_65_dialog_content = "Apakah Anda merasa nyaman menginap di Royal Guesthouse beberapa hari ini?",
  ui_story_5075_50750201_66_dialog_content = "Ya, tapi rasanya semua orang sedikit berlebihan dalam menunjukkan keramahan mereka.",
  ui_story_5075_50750201_67_dialog_content = "Mereka bahkan tidak membiarkan saya menuangkan secangkir air untuk diri saya sendiri. Ini membuat saya merasa seperti saya sangat berharga atau semacamnya.",
  ui_story_5075_50750201_68_dialog_content = "Bukan begitu, 'kan?",
  ui_story_5075_50750201_69_dialog_content = "Tolong jangan bercanda tentang itu.",
  ui_story_5075_50750201_70_dialog_content = "Aku berusaha sebaik mungkin untuk tidak mempermalukan diriku sendiri. Itu tidak mudah bagi ku, tahu!",
  ui_story_5075_50750201_71_dialog_content = "Saya juga tidak melakukan pekerjaan yang baik sebagai utusan.",
  ui_story_5075_50750201_72_dialog_content = "Masuk ke istana tampaknya mustahil. Saya bahkan belum mendapatkan kesempatan untuk memperkenalkan Astra, apalagi bernegosiasi untuk hubungan yang lebih baik.",
  ui_story_5075_50750201_73_dialog_content = "... Permintaan maaf saya, PlayerName.",
  ui_story_5075_50750201_74_dialog_content = "Itu adalah kelalaian dari saya.",
  ui_story_5075_50750201_75_dialog_content = "Aku mengundangmu datang jauh-jauh ke sini, namun gagal menyediakan forum untukmu.",
  ui_story_5075_50750201_76_dialog_content = "Itu bukan salahmu, Dantang. Jika aku telah melakukan persiapan yang lebih baik, aku tidak akan terombang-ambing seperti ini.",
  ui_story_5075_50750201_77_dialog_content = "Tidak, ini salahku...",
  ui_story_5075_50750201_78_dialog_content = "*terkekeh*",
  ui_story_5075_50750201_79_dialog_content = "Hahaha... Semua permintaan maaf ini antar teman agak lucu, bukan?",
  ui_story_5075_50750201_80_dialog_content = "Yah, tidak ada gunanya khawatir tentang masa lalu. Aku akan kembali dan bersiap untuk perjalanan berikutnya ke istana, dan aku berjanji akan melakukan yang lebih baik saat itu.",
  ui_story_5075_50750201_81_dialog_content = "... Oh, satu hal lagi.",
  ui_story_5075_50750201_82_dialog_content = "Ya?",
  ui_story_5075_50750201_83_dialog_content = "Sebelum saya datang, saya sempat mendengar dua pelayan berbicara... Mereka mengatakan sesuatu tentang rencana pernikahan antara kamu dan pangeran dari Kerajaan Ji?",
  ui_story_5075_50750201_84_dialog_content = "Dan mereka tidak berbicara tentangmu dengan nada yang baik, mengatakan bahwa kamu di sini sebagai jaminan.",
  ui_story_5075_50750201_85_dialog_content = "Itulah sebabnya aku harus bertanya: apakah mereka memperlakukanmu dengan baik di sini?",
  ui_story_5075_50750201_86_dialog_content = "Hmm…",
  ui_story_5075_50750201_87_dialog_content = "A-Aku baik-baik saja.",
  ui_story_5075_50750201_88_dialog_content = "Sebenarnya, aku juga pernah mendengar rumor yang sama sebelumnya, tapi aku tidak menyangka kamu juga mendengarnya.",
  ui_story_5075_50750201_89_dialog_content = "Itu adalah niat raja, tetapi saya telah menjelaskan posisi saya, dan dia tidak bisa memaksaku.",
  ui_story_5075_50750201_X89_dialog_content = "Mengenai itu... Memang benar bahwa saya di sini karena pinjaman kepada Ye.",
  ui_story_5075_50750201_X90_dialog_content = "Namun, bukan urusan para pelayan untuk menilai. Saya akan menangani para penggosip itu nanti.",
  ui_story_5075_50750201_X91_dialog_content = "Dantang...",
  ui_story_5075_50750201_90_dialog_content = "Jangan khawatir. Aku sudah cukup lama di sini untuk mendapatkan dukungan yang cukup.",
  ui_story_5075_50750201_91_dialog_content = "Tak seorang pun di seluruh istana yang berani menentangku secara terbuka.",
  ui_story_5075_50750201_92_dialog_content = "Itu termasuk pangeran, kan?",
  ui_story_5075_50750201_93_dialog_content = "Tentu saja! Belum lagi pangeran mahkota itu hanya...",
  ui_story_5075_50750201_94_dialog_content = "Dantang! Apakah kamu baik-baik saja, Dantang?",
  ui_story_5075_50750201_95_dialog_content = "... Pangeran Mahkota? Anda seharusnya beristirahat di kamar Anda pada jam segini.",
  ui_story_5075_50750201_96_dialog_content = "Aku mengkhawatirkanmu.",
  ui_story_5075_50750201_97_dialog_content = "Gempa tadi cukup kuat. Kamu baik-baik saja? Ada yang terluka? Takut?",
  ui_story_5075_50750201_98_dialog_content = "*menarik nafas* Aku baik-baik saja dan tidak terluka, jangan khawatir.",
  ui_story_5075_50750201_99_dialog_content = "Tapi raja akan menghukummu lagi jika dia mengetahui bahwa kamu pergi tanpa ditemani penjaga.",
  ui_story_5075_50750201_100_dialog_content = "Aku sudah besar sekarang! A-Aku tidak takut hukuman!",
  ui_story_5075_50750201_101_dialog_content = "Lagipula, sebagai pria sejati, saya harus ada untuk tunangan saya di saat-saat krisis!",
  ui_story_5075_50750201_102_dialog_content = "Pfft—",
  ui_story_5075_50750201_103_dialog_content = "Bagaimana Anda bisa mengatakan itu—",
  ui_story_5075_50750201_104_dialog_content = "Oh? Seorang pria sejati? Sepertinya ada yang saya lewatkan.",
  ui_story_5075_50750201_105_dialog_content = "Beban belajarmu saat ini masih di level anak-anak, tapi karena kamu sudah menjadi pria sejati, jadi...",
  ui_story_5075_50750201_106_dialog_content = "Aku harus memberitahu guru bahwa PRmu terlalu ringan dan kita perlu menggandakannya mulai sekarang!",
  ui_story_5075_50750201_107_dialog_content = "Tidak... Tolong jangan! Aku mengakui... Aku belum tumbuh menjadi pria sejati!",
  ui_story_5075_50750201_108_dialog_content = "A-Aku mungkin memiliki aspirasi yang tinggi, tapi tubuh dan pikiranku belum sepenuhnya siap untuk beban seperti itu!",
  ui_story_5075_50750201_109_dialog_content = "... Cukup untuk hari ini. Aku akan kembali untuk beristirahat.",
  ui_story_5075_50750201_110_dialog_content = "Dantang, mari kita kongko lagi besok!",
  ui_story_5075_50750201_111_dialog_content = "Kami telah mempekerjakan koki baru yang ahli dalam masakan Ye. Ayah mengundang kamu untuk pesta makan malam besok.",
  ui_story_5075_50750201_112_dialog_content = "Kamu harus datang!",
  ui_story_5075_50750201_113_dialog_content = "*berdesah*",
  ui_story_5075_50750201_114_dialog_content = "Terima kasih atas bantuan Anda, Tuan, atau sang pangeran tidak akan pernah kembali.",
  ui_story_5075_50750201_115_dialog_content = "Ini adalah Penasihat Utama untuk Raja Kerajaan Ji, PlayerName.",
  ui_story_5075_50750201_116_dialog_content = "Dan mentor saya juga.",
  ui_story_5075_50750201_117_dialog_content = "Aku bisa berkembang di Ji semua berkat bantuan dan petunjuknya.",
  ui_story_5075_50750201_118_dialog_content = "(Apakah dia benar-benar sebegitu pentingnya? Tunggu, bagaimana orang biasanya menunjukkan rasa hormat mereka di Longzhou?)",
  ui_story_5075_50750201_119_dialog_content = "Senang bertemu dengan Anda, Pak!",
  ui_story_5075_50750201_120_dialog_content = "Tuan, ini adalah PlayerName dari Astra, yang saya percaya Anda telah lihat selama pesta.",
  ui_story_5075_50750201_121_dialog_content = "Hmm, saya sangat terkesan.",
  ui_story_5075_50750201_122_dialog_content = "(Ya, dia pasti guru Dantang. Tatapannya membuatku lebih gugup daripada ruangan penuh orang yang menatap...)",
  ui_story_5075_50750201_123_dialog_content = "Hah? Tanda itu pada surat yang kamu pegang...",
  ui_story_5075_50750201_124_dialog_content = "Laporan mendesak dari Kantor Inspeksi.",
  ui_story_5075_50750201_125_dialog_content = "Apakah itu dari skuad yang tergesa-gesa dikirim untuk mempertahankan teluk karena peningkatan kehadiran Eclipsite?",
  ui_story_5075_50750201_126_dialog_content = "Sekarang, lawan mereka, saya khawatir, lebih dari sekedar roh jahat.",
  ui_story_5075_50750201_127_dialog_content = "Menurut laporan mendesak, tepat setelah gempa bumi, makhluk jahat di dekat laut tiba-tiba menjadi liar dan mulai melukai orang-orang.",
  ui_story_5075_50750201_128_dialog_content = "Meskipun patroli telah mengintervensi tepat waktu dan menghentikan mereka, saya khawatir ini mungkin bukan insiden yang terisolasi.",
  ui_story_5075_50750201_129_dialog_content = "Fiendlings yang gila? Tapi bagaimana? Apakah ada lebih dari gempa bumi daripada hanya sebagai bencana alam?",
  ui_story_5075_50750202_1_dialog_content = "Itulah sebabnya saya datang ke sini, berharap Anda dapat menyelidikinya untuk kami.",
  ui_story_5075_50750202_2_dialog_content = "Tentu, besok aku akan—",
  ui_story_5075_50750202_3_dialog_content = "Bukankah kamu seharusnya mengasuh pangeran untuk raja lagi besok?",
  ui_story_5075_50750202_4_dialog_content = "Yah, umm...",
  ui_story_5075_50750202_5_dialog_content = "Adakah yang bisa aku bantu?",
  ui_story_5075_50750202_6_dialog_content = "Dantang mungkin tidak punya waktu luang, tetapi saya punya. Jika yang kamu butuhkan hanyalah seseorang untuk menyelidiki, saya bisa menanganinya dengan baik.",
  ui_story_5075_50750202_7_dialog_content = "Tidak. Sudah menjadi bantuan besar dari kamu untuk datang sebagai utusan, PlayerName.",
  ui_story_5075_50750202_8_dialog_content = "Bagaimana kami bisa membebani Anda dengan urusan Ji?",
  ui_story_5075_50750202_9_dialog_content = "Aku percaya itu bisa dilakukan.",
  ui_story_5075_50750202_10_dialog_content = "Pak?",
  ui_story_5075_50750202_11_dialog_content = "Saya telah meninjau proposal pertukaran Zhuohua.",
  ui_story_5075_50750202_12_dialog_content = "Namun, di istana kerajaan, jelas bahwa raja tidak suka dengan eksekusi segera.",
  ui_story_5075_50750202_13_dialog_content = "Sayang sekali.",
  ui_story_5075_50750202_14_dialog_content = "PlayerName, sebagai utusan, Anda pasti suka mendapatkan kesempatan lain untuk membujuk raja.",
  ui_story_5075_50750202_15_dialog_content = "Benar.",
  ui_story_5075_50750202_16_dialog_content = "Banyak orang yang membantu saya sampai di sini, dan sama banyaknya yang mengandalkan saya. Saya menolak untuk kembali dengan tangan hampa.",
  ui_story_5075_50750202_17_dialog_content = "Nah, ini adalah peluang emas.",
  ui_story_5075_50750202_18_dialog_content = "Seiring dengan Festival Musim Semi yang semakin dekat, kota ini ramai dengan orang-orang, disertai berbagai aktivitas.",
  ui_story_5075_50750202_19_dialog_content = "Jadi, segala masalah yang disebabkan oleh roh jahat dan setan bisa berujung pada konsekuensi serius dan bahaya bagi warga.",
  ui_story_5075_50750202_20_dialog_content = "Dan ketika itu terjadi, jika ada seseorang yang bisa menyelesaikannya segera, itu akan menjadi perbuatan yang berjasa.",
  ui_story_5075_50750202_21_dialog_content = "Raja pasti akan memberikan hadiah di mana mereka layak.",
  ui_story_5075_50750202_22_dialog_content = "Sebenarnya, aku tidak terlalu peduli tentang hadiah. Lagipula, aku bahkan tidak tahu harus berbuat apa dengan tumpukan hadiah yang ada di penginapan...",
  ui_story_5075_50750202_23_dialog_content = "Tapi jika memungkinkan, saya benar-benar ingin menggunakan ini sebagai kesempatan untuk berbagi rencana kami dengan raja!",
  ui_story_5075_50750202_24_dialog_content = "Jadi, tolong serahkan tugas ini padaku, Pak.",
  ui_story_5075_50750202_25_dialog_content = "Saya memiliki permintaan lain, dan jika kamu setuju, saya akan menyerahkan masalah ini di tanganmu.",
  ui_story_5075_50750202_26_dialog_content = "Ada apa?",
  ui_story_5075_50750202_27_dialog_content = "... Cobalah untuk tidak menonjolkan diri selama penyelidikanmu, dan jangan biarkan siapa pun di istana kerajaan tahu tentang ini.",
  ui_story_5075_50750202_28_dialog_content = "Tuan, PlayerName berasal dari luar negeri dan tidak familiar dengan Kerajaan Ji, apalagi menjalankan misi sendirian.",
  ui_story_5075_50750202_29_dialog_content = "Aku tidak pernah bilang PlayerName harus menanganinya sendirian.",
  ui_story_5075_50750202_30_dialog_content = "Tidak menangkap maksudku, ya? Zhuohua, kau terlalu tak sabaran.",
  ui_story_5075_50750202_31_dialog_content = "...",
  ui_story_5075_50750202_32_dialog_content = "Tidak apa-apa, Dantang.",
  ui_story_5075_50750202_33_dialog_content = "Saya telah mengambil banyak pekerjaan yang membawa saya ke tempat-tempat asing di Astra. Seberat apapun pekerjaan itu, saya mendapatkan banyak pengalaman dari hal semacam ini.",
  ui_story_5075_50750202_34_dialog_content = "Bagus.",
  ui_story_5075_50750202_35_dialog_content = "Zhuohua, antar tamu muda kita keluar dari istana.",
  ui_story_5075_50750202_36_dialog_content = "Tentu saja...",
  ui_story_5075_50750202_37_dialog_content = "PlayerName—",
  ui_story_5075_50750202_38_dialog_content = "Agar kamu tahu, saya tidak akan mendengarkan jika kamu akan meminta maaf atau mencoba membujuk saya untuk tidak melakukan ini.",
  ui_story_5075_50750202_39_dialog_content = "Tapi jika kau dibuat berlari-lari seperti ini sementara aku tinggal di istana...",
  ui_story_5075_50750202_40_dialog_content = "Tapi makanannya enak di jamuan makan.",
  ui_story_5075_50750202_41_dialog_content = "?",
  ui_story_5075_50750202_42_dialog_content = "Tidakkah kamu pikir ini jauh lebih baik daripada makanan di Twin Pavilions Bay?",
  ui_story_5075_50750202_43_dialog_content = "Ya, karena mereka disiapkan oleh koki kerajaan.",
  ui_story_5075_50750202_44_dialog_content = "Dengan kata lain, bukan kami yang membuatnya. Kami juga tidak menanam padi, bukan?",
  ui_story_5075_50750202_45_dialog_content = "Tentu saja, itu berasal dari petani lokal.",
  ui_story_5075_50750202_46_dialog_content = "Lalu, apakah kita mengirimkannya ke kota?",
  ui_story_5075_50750202_47_dialog_content = "Tidak, rumah-rumah perdagangan di seluruh negeri yang bertanggung jawab atas itu.",
  ui_story_5075_50750202_48_dialog_content = "Apakah kita membelinya sendiri?",
  ui_story_5075_50750202_49_dialog_content = "Tidak, itu adalah tugas dari bendahara kerajaan.",
  ui_story_5075_50750202_50_dialog_content = "Namun, Anda tidak khawatir akan merepotkan mereka, atau menawarkan untuk melakukan hal-hal tersebut untuk mereka.",
  ui_story_5075_50750202_51_dialog_content = "... Saya tidak begitu sombong untuk percaya bahwa saya bisa melakukan pekerjaan mereka.",
  ui_story_5075_50750202_52_dialog_content = "Tugas ini juga tidak ada bedanya.",
  ui_story_5075_50750202_53_dialog_content = "Tidak ada orang yang bisa melakukan segalanya sendiri. Jika kamu tidak punya waktu untuk melakukan sesuatu sementara aku memiliki waktu dan kemampuan, seharusnya aku yang melakukannya.",
  ui_story_5075_50750202_54_dialog_content = "Mengganggu orang lain, bergantung pada orang lain, itulah cara kerja dunia ini.",
  ui_story_5075_50750202_55_dialog_content = "Tentu saja, jika kamu pikir aku tidak mampu menangani pekerjaan ini...",
  ui_story_5075_50750202_56_dialog_content = "Aku tidak akan pernah!",
  ui_story_5075_50750202_57_dialog_content = "... Anda tahu, Anda lebih cocok menjadi pembahas daripada utusan, PlayerName.",
  ui_story_5075_50750202_58_dialog_content = "Sebanyak apapun alasan yang kamu buat, akan lebih bijaksana bagi saya untuk menyerah.",
  ui_story_5075_50750202_59_dialog_content = "Haha, kalau menurutmu begitu...",
  ui_story_5075_50750202_60_dialog_content = "Sungguh indah melihatmu tampak jauh lebih baik daripada saat kami pergi.",
  ui_story_5075_50750202_61_dialog_content = "Ahem. Apakah itu begitu jelas?",
  ui_story_5075_50750202_62_dialog_content = "Ini semua karena aku yang membuatmu terlalu stres, mengenai hubungan diplomatik, dampak setelah gempa bumi...",
  ui_story_5075_50750202_63_dialog_content = "Belum lagi khawatir tentang kemungkinan aku diperlakukan tidak adil, kamu begitu stres sampai-sampai kamu tidak seperti dirimu sendiri akhir-akhir ini.",
  ui_story_5075_50750202_64_dialog_content = "Jadi kamu pikir aku terlalu khawatir tentang banyak hal?",
  ui_story_5075_50750202_65_dialog_content = "Hampir tidak, saya lebih menganggap itu sebagai saran ramah.",
  ui_story_5075_50750202_66_dialog_content = "Demi kebaikanmu, aku harus bangkit dan menyelesaikan masalah ini secepat mungkin.",
  ui_story_5075_50750202_67_dialog_content = "Baik, mari kita lakukan yang terbaik bersama! Meskipun kita tidak benar-benar bertarung di garis depan yang sama—",
  ui_story_5075_50750202_68_dialog_content = "Kita masih bisa bekerja sama dan mencapai tujuan kita.",
  ui_story_5075_50750202_69_dialog_content = "Utusan yang terhormat, saya di sini untuk mengantar Anda kembali.",
  ui_story_5075_50750202_70_dialog_content = "Oh, halo lagi. Apakah kamu di sini hanya untuk mengantarku pulang?",
  ui_story_5075_50750202_71_dialog_content = "Tentu saja. Selama Anda berada di Kerajaan Ji, Anda adalah tamu kehormatan di Penginapan Kerajaan kami, dan kami tidak akan lalai dalam tugas kami.",
  ui_story_5075_50750202_72_dialog_content = "Sepertinya sudah saatnya aku pergi. Aku akan memberi tahu kamu perkembangannya, Dantang!",
  ui_story_5075_50750202_73_dialog_content = "Maka saya akan menunggu kabar baikmu di istana.",
  ui_story_5075_50750202_74_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian—</color>",
  ui_story_5075_50750202_75_dialog_content = "Yang Mulia? Apa yang sedang Anda lakukan berdiri di sini sendirian?",
  ui_story_5075_50750202_76_dialog_content = "Oh, kamu kembali, Jiu. Bagaimana dengan hal yang kita bicarakan itu?",
  ui_story_5075_50750202_77_dialog_content = "Saya masih bekerja keras di atasnya.",
  ui_story_5075_50750202_78_dialog_content = "Tapi, masih ada banyak agen rahasia yang aktif di Haojin.",
  ui_story_5075_50750202_79_dialog_content = "Jadi, tolong hati-hati saat aku tidak ada.",
  ui_story_5075_50750202_80_dialog_content = "Baik. Bagus, Jiu.",
  ui_story_5075_50750202_81_dialog_content = "Akan tetapi, saya akan tinggal di istana untuk waktu yang terlihat ke depan, jadi saya tidak mengharapkan ada bahaya.",
  ui_story_5075_50750202_82_dialog_content = "Oh, ingatkan saya untuk menulis surat ketika kita kembali.",
  ui_story_5075_50750202_83_dialog_content = "Bahkan Kapten Yuebai telah mengirimkan semua pengiriman dan kembali ke Haojin...",
  ui_story_5075_50750202_84_dialog_content = "Seorang Menteri tertentu, Armilla, tidak pernah berkomunikasi kecuali mengirim pesan misterius sejak mendarat...",
  ui_story_5075_50750202_85_dialog_content = "Saya lihat saya harus menegur dia sendiri.",
  ui_story_5075_50750202_86_dialog_content = "Hmm?",
  ui_story_5075_50750202_87_dialog_content = "Ada apa, Yang Mulia?",
  ui_story_5075_50750202_88_dialog_content = "Santai saja. Aku hanya sedikit terkejut.",
  ui_story_5075_50750202_89_dialog_content = "Rasanya seperti bunga-bunga di pohon plum ini mekar dalam sekejap mata.",
  ui_story_5075_50750202_90_dialog_content = "Tapi bukankah kamu hanya menyukai begonia saja?",
  ui_story_5075_50750202_91_dialog_content = "Ya, tapi aku merasa bunga plum hari ini juga menarik.",
  ui_story_5075_50750301_1_dialog_content = "(Meski penuh percaya diri saat setuju melakukan penyelidikan ini...)",
  ui_story_5075_50750301_2_dialog_content = "(Saya tidak menyangka akan bertemu dengan rintangan besar seperti ini begitu cepat!)",
  ui_story_5075_50750301_3_dialog_content = "Hei... Perlindungan sebanyak ini agak tidak perlu, bukan? Aku hanya ingin berbelanja sedikit.",
  ui_story_5075_50750301_4_dialog_content = "Yang Mulia, mengingat status Anda yang terhormat, enam pengawal hanyalah langkah keamanan dasar, tidak ada yang spesial.",
  ui_story_5075_50750301_5_dialog_content = "Saya sudah mengajukan penambahan sembilan penjaga lagi untuk memastikan keamanan Anda.",
  ui_story_5075_50750301_6_dialog_content = "Lebih banyak penjaga?",
  ui_story_5075_50750301_7_dialog_content = "Sudahlah, aku punya hal yang lebih penting untuk ditanyakan...",
  ui_story_5075_50750301_8_dialog_content = "Mengapa tidak ada satu orang pun di jalan ini?",
  ui_story_5075_50750301_9_dialog_content = "Untuk menghindari gangguan yang tidak diinginkan dalam waktu luang Anda, kami telah membersihkan area ini terlebih dahulu.",
  ui_story_5075_50750301_10_dialog_content = "Tapi itu hanya merusak seluruh pengalaman!",
  ui_story_5075_50750301_11_dialog_content = "Kamu terlalu protektif bagaimanapun caranya!",
  ui_story_5075_50750301_12_dialog_content = "(Jika saya bahkan tidak bisa berbicara dengan siapa pun di sini, penyelidikan saya akan berakhir sebelum dimulai.)",
  ui_story_5075_50750301_13_dialog_content = "... Tidak perlu repot. Aku akan mengantarkannya untukmu.",
  ui_story_5075_50750301_14_dialog_content = "(Hah? Ada yang bicara di luar?)",
  ui_story_5075_50750301_15_dialog_content = "Istana meminta saya untuk mengantarkan ini secara langsung kepada utusan. Tolong, jangan membuatnya sulit bagi saya.",
  ui_story_5075_50750301_16_dialog_content = "Jika itu masalahnya, silakan masuk.",
  ui_story_5075_50750301_17_dialog_content = "Salam, Yang Mulia.",
  ui_story_5075_50750301_18_dialog_content = "Ini adalah camilan yang disiapkan oleh koki baru istana. Para bangsawan merasa mereka cukup lezat.",
  ui_story_5075_50750301_19_dialog_content = "Jadi mereka mengirimku untuk membawakanmu beberapa untuk dicoba.",
  ui_story_5075_50750301_20_dialog_content = "Terima kasih. Hah? Masih hangat.",
  ui_story_5075_50750301_21_dialog_content = "Meskipun iklim Haojin yang lembut, ini masih musim dingin.",
  ui_story_5075_50750301_22_dialog_content = "Jadi, ada pemanas di bawah wadah makanan untuk menjaga semuanya tetap hangat dan lezat untukmu.",
  ui_story_5075_50750301_23_dialog_content = "Pemanas di sana menggunakan teknik baru yang diimpor dari Kerajaan Ye.",
  ui_story_5075_50750301_24_dialog_content = "Dan gayanya dirancang dengan teliti, dengan pengrajin yang terampil mengukir bunga di bagian dalam, menjadikannya ornamen yang cocok.",
  ui_story_5075_50750301_25_dialog_content = "Di bagian dalam? Kenapa membuat ukiran yang rumit di tempat yang tidak bisa dilihat orang?",
  ui_story_5075_50750301_26_dialog_content = "Nah, mereka bilang... lebih mudah menangani sesuatu di tempat yang tidak terlihat.",
  ui_story_5075_50750301_27_dialog_content = "Apa?",
  ui_story_5075_50750301_28_dialog_content = "Saya hanya bergumam pada diri sendiri. Luangkan waktu Anda dan nikmati, utusan yang terhormat. Saya akan kembali ke istana dan melaporkan.",
  ui_story_5075_50750301_29_dialog_content = "Duta yang terhormat, apakah Anda ingin camilan sekarang? Atau ada yang lain yang Anda butuhkan?",
  ui_story_5075_50750301_30_dialog_content = "Tidak, terima kasih. Aku sedikit lelah, jadi aku pikir aku akan tidur siang untuk sekarang. Kalian bisa pergi.",
  ui_story_5075_50750301_31_dialog_content = "Oh, kamu bisa tinggalkan makanannya di sini saja. Aku akan memakannya saat bangun tidur.",
  ui_story_5075_50750301_32_dialog_content = "Ya, Yang Mulia.",
  ui_story_5075_50750301_33_dialog_content = "<color=#e8d9bb>Pemanas tersebut mengeluarkan asap tipis, dan melalui potongan tembaga yang saling mengait, Anda bisa melihat api di dalamnya berkedip-kedip.</color>",
  ui_story_5075_50750301_34_dialog_content = "<color=#e8d9bb>Klik.</color>",
  ui_story_5075_50750301_35_dialog_content = "<color=#e8d9bb>Saat api di dalam pemanas padam, potongan tembaga yang sebelumnya saling mengait tiba-tiba menyebar.</color>",
  ui_story_5075_50750301_36_dialog_content = "<color=#e8d9bb>Kemudian, mereka membuka menjadi bunga begonia yang kecil dan halus.</color>",
  ui_story_5075_50750301_37_dialog_content = "Ada lambang tersembunyi di dalamnya, serta catatan?",
  ui_story_5075_50750301_38_dialog_content = "May semoga Anda menikmati kesehatan yang baik selama tinggal di Ji untuk meredakan kecemasan Tuan Putri Zhuohua, Yang Mulia.",
  ui_story_5075_50750301_39_dialog_content = "Dia sedang menyampaikan pesan rahasia dari Dantang!",
  ui_story_5075_50750301_40_dialog_content = "(Insignia itu milik \"Kantor Inspeksi,\" sepertinya, tapi aku tidak tahu harus berbuat apa dengan itu sekarang.)",
  ui_story_5075_50750301_41_dialog_content = "(Ini peta? Dengan alamat lagi!)",
  ui_story_5075_50750301_42_dialog_content = "(Pelayan-pelayan sedang tidak ada sekarang! Ini adalah kesempatanku!)",
  ui_story_5075_50750301_43_option_content = "Psychic Scan",
  ui_story_5075_50750301_44_dialog_content = "(Saya bisa merasakan ada dua pengawal di timur dan tiga di selatan... Jadi sepertinya saya akan ke barat.)",
  ui_story_5075_50750301_45_dialog_content = "Hei, bergerak cepat! Utusan itu hilang!",
  ui_story_5075_50750301_46_dialog_content = "Kamu tetap di sini. Aku akan pergi ke sana dan melihat apakah aku bisa menemukan sesuatu!",
  ui_story_5075_50750301_47_dialog_content = "(Itu tidak memakan waktu lama sama sekali, untungnya aku berhasil sampai di tepi halaman. Sekarang aku hanya perlu melewati tembok-tembok ini...)",
  ui_story_5075_50750301_48_dialog_content = "... Mereka terlalu tinggi!",
  ui_story_5075_50750301_49_dialog_content = "Terhormat utusan! Terhormat utusan!",
  ui_story_5075_50750301_50_dialog_content = "(Aku akan segera dikelilingi! Harus memikirkan sesuatu...)",
  ui_story_5075_50750301_51_dialog_content = "Kamu sedang main petak umpet?",
  ui_story_5075_50750301_52_dialog_content = "Hah?",
  ui_story_5075_50750301_53_dialog_content = "Di sini!",
  ui_story_5075_50750301_54_dialog_content = "Lihat ke atas.",
  ui_story_5075_50750301_55_dialog_content = "Seorang anak kecil? Apa yang kamu lakukan di atas tembok? Di atas sana berbahaya!",
  ui_story_5075_50750301_56_dialog_content = "Ini sama sekali tidak berbahaya. Bahkan, aku bisa berjalan di atas tali.",
  ui_story_5075_50750301_57_dialog_content = "Jadi kamu sedang main petak umpet? Aku juga mau ikut bermain.",
  ui_story_5075_50750301_58_dialog_content = "Aku tidak sedang bermain...",
  ui_story_5075_50750301_59_dialog_content = "Utusan terhormat? Apakah Anda di sini?",
  ui_story_5075_50750301_60_dialog_content = "Uh-oh! Maaf, tapi aku harus pergi—",
  ui_story_5075_50750301_61_dialog_content = "!",
  ui_story_5075_50750301_62_dialog_content = "Oh, uh... Aku hanya pergi jalan-jalan!",
  ui_story_5075_50750301_63_dialog_content = "Utusan? Apakah kamu di sekitar sini?",
  ui_story_5075_50750301_64_dialog_content = "?",
  ui_story_5075_50750301_65_dialog_content = "Di sini juga tidak ada. Ke mana dia pergi?",
  ui_story_5075_50750301_66_dialog_content = "Utusan—",
  ui_story_5075_50750301_67_dialog_content = "Dan Anda mengatakan bahwa Anda tidak bermain.",
  ui_story_5075_50750301_68_dialog_content = "Penjaga itu sama sekali tidak melihatku tadi. Apakah kamu yang melakukan ini?",
  ui_story_5075_50750301_69_dialog_content = "Hehe. Mungkin sedikit.",
  ui_story_5075_50750301_70_dialog_content = "?",
  ui_story_5075_50750301_71_dialog_content = "?",
  ui_story_5075_50750301_72_dialog_content = "Tunggu dulu.",
  ui_story_5075_50750301_73_dialog_content = "Bukankah seharusnya kau terpesona oleh aura dominanku dan berlutut kepada Chen'ni yang agung dan megah sekarang juga?",
  ui_story_5075_50750301_74_dialog_content = "Aura dominan...",
  ui_story_5075_50750301_75_dialog_content = "Uh, apa yang membuatmu berpikir aku seharusnya melakukan itu?",
  ui_story_5075_50750301_76_dialog_content = "Karena itulah yang saya dengar dari pendongeng di jembatan saat dalam perjalanan ke sini!",
  ui_story_5075_50750301_77_dialog_content = "Dia bilang itu tren yang sedang berlangsung. Bukan begitu, ya?",
  ui_story_5075_50750301_78_dialog_content = "Saya rasa itu bukan yang dia maksud, tepatnya...",
  ui_story_5075_50750301_79_dialog_content = "Omong-omong—",
  ui_story_5075_50750301_80_dialog_content = "Aku pasti mendengar ada sesuatu yang terjadi di sini.",
  ui_story_5075_50750301_81_dialog_content = "Tapi aku baru saja memeriksa... Yah, untuk berjaga-jaga, mari kita periksa lagi.",
  ui_story_5075_50750301_82_dialog_content = "Ayo main petak umpet!",
  ui_story_5075_50750301_83_dialog_content = "Saya hanya butuh bantuan untuk keluar dari sini terlebih dahulu. Pikir Anda bisa melakukan itu, Chen'ni yang hebat dan agung?",
  ui_story_5075_50750301_84_dialog_content = "Oh, kamu memang punya lidah yang fasih untuk seorang anak!",
  ui_story_5075_50750301_85_dialog_content = "Tenang. Saya adalah ahli dalam permainan ini. Kamu tidak akan salah pilih dengan Chen'ni!",
  ui_story_5075_50750301_86_dialog_content = "Rahasianya adalah berjuang habis-habisan!",
  ui_story_5075_50750302_1_dialog_content = "Huff... Puff...",
  ui_story_5075_50750302_2_dialog_content = "Aku mulai berpikir... bahwa kamu sebenarnya tidak tahu cara bermain petak umpet...",
  ui_story_5075_50750302_3_dialog_content = "Itu mustahil.",
  ui_story_5075_50750302_4_dialog_content = "Lihat, kita sudah berada di luar gerbang.",
  ui_story_5075_50750302_5_dialog_content = "Dan tidak ada seorang pun yang menangkap kita selama ini.",
  ui_story_5075_50750302_6_dialog_content = "Saya bilang kamu tidak seharusnya berlari seperti itu saat bermain petak umpet...",
  ui_story_5075_50750302_7_dialog_content = "Dan fakta bahwa tidak ada seorang pun yang melihat kita sama sekali berarti Anda telah berbuat curang dengan cara tertentu.",
  ui_story_5075_50750302_8_dialog_content = "... Lagi pula, saya rasa itu berarti saya juga curang.",
  ui_story_5075_50750302_9_dialog_content = "Pokoknya, terima kasih lagi, Chen'ni... Maksudku, Chen'ni yang hebat dan agung!",
  ui_story_5075_50750302_10_dialog_content = "Nah, karena kamu cukup baik untuk bermain denganku, kita bisa lewati penggunaan kata hormat.",
  ui_story_5075_50750302_11_dialog_content = "Tentu, Chen'ni. Ngomong-ngomong, nama saya PlayerName. Saya—",
  ui_story_5075_50750302_12_dialog_content = "Sebuah Caelestite.",
  ui_story_5075_50750302_13_dialog_content = "Aku tahu.",
  ui_story_5075_50750302_14_dialog_content = "Hah?",
  ui_story_5075_50750302_15_dialog_content = "Utusan? Apakah itu kamu di luar sana?",
  ui_story_5075_50750302_16_dialog_content = "Aku harus keluar dari sini selagi masih bisa.",
  ui_story_5075_50750302_17_dialog_content = "Utusan terhormat, ini benar-benar kamu!",
  ui_story_5075_50750302_18_dialog_content = "Mengapa kamu keluar tanpa pengawal? Itu terlalu berisiko.",
  ui_story_5075_50750302_19_dialog_content = "Penjaga!",
  ui_story_5075_50750302_20_dialog_content = "Tunggu, aku tidak—",
  ui_story_5075_50750302_21_dialog_content = "Ciit!",
  ui_story_5075_50750302_22_dialog_content = "Ahh—sebuah tikus! T-Tolong!",
  ui_story_5075_50750302_23_dialog_content = "<color=#e8d9bb>Wush!</color>",
  ui_story_5075_50750302_24_dialog_content = "Ahhh! Itu seorang fiendling... Seorang fiendling sedang menyerang kita!",
  ui_story_5075_50750302_25_dialog_content = "... Ssst, jangan terlalu keras.",
  ui_story_5075_50750302_26_dialog_content = "<color=#e8d9bb>Gedebuk.</color>",
  ui_story_5075_50750302_27_dialog_content = "Apa yang telah kau lakukan, Chen'ni?",
  ui_story_5075_50750302_28_dialog_content = "Tidurkan dia sebentar.",
  ui_story_5075_50750302_29_dialog_content = "Itu yang berikutnya.",
  ui_story_5075_50750302_30_dialog_content = "Mencicit...",
  ui_story_5075_50750302_31_dialog_content = "Itu pasti bukan tikus biasa...",
  ui_story_5075_50750302_32_dialog_content = "Ini pasti salah satu fiendling yang Liqing dan yang lainnya ceritakan padaku. Seorang fiendling yang gagal mengambil bentuk yang tepat.",
  ui_story_5075_50750302_33_dialog_content = "Ada sesuatu tentang itu yang membuatku merasa sangat tidak nyaman... Ini gila, bukan?",
  ui_story_5075_50750302_X33_dialog_content = "Menurut laporan mendesak, tepat setelah gempa bumi, makhluk jahat di dekat laut tiba-tiba menjadi liar dan mulai melukai orang-orang.",
  ui_story_5075_50750302_34_dialog_content = "Kau bisa tahu?",
  ui_story_5075_50750302_35_dialog_content = "Maka kamu pasti bisa melihat ini juga.",
  ui_story_5075_50750302_36_dialog_content = "<color=#e8d9bb>Ujung jari Chen'ni menyentuh fiendling yang jatuh, menarik bayangan gelap dari tubuhnya.</color>",
  ui_story_5075_50750302_37_dialog_content = "<color=#e8d9bb>Seolah-olah kabut yang keruh, dengan sentuhan kejahatan yang samar berkumpul.</color>",
  ui_story_5075_50750302_38_option_content = "Coba bangun telepati.",
  ui_story_5075_50750302_39_dialog_content = "Benci...",
  ui_story_5075_50750302_40_dialog_content = "Aduh—",
  ui_story_5075_50750302_41_dialog_content = "Rasanya sakit saat aku menggunakan kekuatanku pada itu, seperti menyentuh cairan korosif... Apa ini?",
  ui_story_5075_50750302_42_dialog_content = "Sebuah hama busuk yang gigih.",
  ui_story_5075_50750302_43_dialog_content = "Hati-hati, itu mulai bergerak! Mungkin dia akan mencoba kabur!",
  ui_story_5075_50750302_44_dialog_content = "<color=#e8d9bb>Tapi gadis itu bahkan tidak berkedip.</color>",
  ui_story_5075_50750302_45_dialog_content = "<color=#e8d9bb>Sejumput dan putaran sederhana dari Chen'ni, dan kabut hitam yang mengancam itu menghilang ke udara seperti api yang dipadamkan.</color>",
  ui_story_5075_50750302_46_dialog_content = "Ayolah, aku tidak melewatkan waktu tidur dan datang ke sini untuk masalah seperti ini.",
  ui_story_5075_50750302_47_dialog_content = "Kamu main sendiri saja, PlayerName. Aku punya hal lain yang harus dikerjakan.",
  ui_story_5075_50750302_48_dialog_content = "Tunggu—",
  ui_story_5075_50750302_49_dialog_content = "Apa yang harus aku lakukan dengan kedua orang ini?",
  ui_story_5075_50750302_50_dialog_content = "Ups, lupa tentang kekacauan ini.",
  ui_story_5075_50750302_51_dialog_content = "Fiuh.",
  ui_story_5075_50750302_52_dialog_content = "<color=#e8d9bb>Gadis itu mengangkat pembantu itu dari bahu dan \"menerbangkannya\" kembali ke Rumah Tamu Kerajaan.</color>",
  ui_story_5075_50750302_53_dialog_content = "<color=#e8d9bb>Kemudian, dengan meraih ekor iblis kecil itu, dia melemparkannya jauh ke langit.</color>",
  ui_story_5075_50750302_54_dialog_content = "Apakah ini benar-benar baik-baik saja?",
  ui_story_5075_50750302_55_dialog_content = "Tentu saja. Fiendlings tidak selemah itu.",
  ui_story_5075_50750302_56_dialog_content = "Jika mereka tidak bisa tahan itu, lebih baik mereka melupakan tentang bertransformasi dan tetap menjadi binatang untuk sisa hidup mereka.",
  ui_story_5075_50750302_57_dialog_content = "Aku mendapatkan perasaan itu ketika aku menggunakan kekuatanku, dan mengingat perilaku yang aneh...",
  ui_story_5075_50750302_58_dialog_content = "Kamu juga seorang fiendling, bukan?",
  ui_story_5075_50750302_59_dialog_content = "Chen'ni? Hei, kemana kamu pergi?",
  ui_story_5075_50750302_60_dialog_content = "Aku masih ingin bertanya padanya tentang bola kabut hitam itu... Ah sudahlah.",
  ui_story_5075_50750302_61_dialog_content = "Mungkin aku akan bertemu dengannya lagi selama penyelidikan saya.",
  ui_story_5075_50750302_62_dialog_content = "Untuk saat ini, sebaiknya saya mulai dengan memeriksa alamat ini.",
  ui_story_5075_50750302_63_dialog_content = "...",
  ui_story_5075_50750401_1_dialog_content = "Festival Musim Semi kembali lagi. Ayo dan coba jeruk keberuntungan manis kami!",
  ui_story_5075_50750401_2_dialog_content = "Cobalah jeruk keberuntungan ini! Ayo, aku akan kupas satu untukmu. Tidak ada biaya jika rasanya tidak manis.",
  ui_story_5075_50750401_3_dialog_content = "Biji wijen, biji melon, dan buah berlapis gula! Semua dibuat dengan cara yang telah teruji waktu! Hai pemuda, kenapa tidak mampir dan lihat?",
  ui_story_5075_50750401_4_dialog_content = "Sangat ramai di sini. Berjalan sendirian di jalan-jalan rasanya benar-benar berbeda.",
  ui_story_5075_50750401_5_dialog_content = "Permisi, tapi apakah kamu tahu cara menuju ke Jalan Yulin?",
  ui_story_5075_50750401_6_dialog_content = "Agak jauh. Kamu harus menuju ke jembatan yang paling ramai terlebih dahulu, lalu tanya pada orang lain setelah menyeberangi persimpangan.",
  ui_story_5075_50750401_7_dialog_content = "Terima kasih. Ada begitu banyak orang di sana.",
  ui_story_5075_50750401_8_dialog_content = "Pertama kali di sini? Kota Haojin mengadakan pameran setiap Festival Musim Semi—itu sangat populer.",
  ui_story_5075_50750401_9_dialog_content = "Itu tepat di jalan itu.",
  ui_story_5075_50750401_10_dialog_content = "Nanti akan ada aktor terkenal yang tampil. Kamu harus menonton jika kamu tidak terburu-buru atau apa pun.",
  ui_story_5075_50750401_11_dialog_content = "Tentu, saya akan melihatnya saat saya punya waktu.",
  ui_story_5075_50750401_12_dialog_content = "Oh, kamu datang di waktu yang salah. Tempat ini biasanya lebih meriah di tahun-tahun sebelumnya.",
  ui_story_5075_50750401_13_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5075_50750401_14_dialog_content = "Suara berisik apa itu?",
  ui_story_5075_50750401_15_dialog_content = "Oh, anak-anak itu sedang bersenang-senang bermain dengan petasan.",
  ui_story_5075_50750401_16_dialog_content = "Yang ini tidak cukup keras. Ambil yang lain!",
  ui_story_5075_50750401_17_dialog_content = "Petasan meledak, mengusir setan kecil, menghilangkan kesialan dengan cara yang ceria!",
  ui_story_5075_50750401_18_dialog_content = "<color=#e8d9bb>*brak-brak!*</color>",
  ui_story_5075_50750401_19_dialog_content = "Hahahahah!",
  ui_story_5075_50750401_20_dialog_content = "Mencicit...",
  ui_story_5075_50750401_21_dialog_content = "Apakah ini ide hiburanmu? Menyalakan kembang api di jalan yang ramai seperti ini sangat berbahaya!",
  ui_story_5075_50750401_22_dialog_content = "Makhluk jahat itu juga tidak menjadi liar... Bahkan, dia terlihat sama sekali tidak berbahaya!",
  ui_story_5075_50750401_23_dialog_content = "Tidak masalah besar. Lihat, bahkan untuk Festival Musim Semi biasa, ada tradisi menggunakan petasan untuk mengusir fiendlings.",
  ui_story_5075_50750401_24_dialog_content = "Satu-satunya perbedaan adalah mereka dulu merekrut aktor untuk memerankan fiendlings, dan anak-anak ini berurusan dengan yang asli.",
  ui_story_5075_50750401_25_dialog_content = "Aku tidak pernah serius melakukan ritual ini sebelumnya, tapi akhir-akhir ini, hal-hal mulai menjadi gelisah.",
  ui_story_5075_50750401_26_dialog_content = "Mungkin fiendlings memang sedikit menakutkan.",
  ui_story_5075_50750401_27_dialog_content = "Meski kamu pendatang baru, saya menyarankan kamu untuk menjauh dari hal-hal itu. Sayangnya, saya harus pergi sekarang.",
  ui_story_5075_50750401_28_dialog_content = "Mengapa itu sama sekali tidak bergerak? Apakah sudah mati?",
  ui_story_5075_50750401_29_dialog_content = "Haruskah kita mencoba ledakan lain?",
  ui_story_5075_50750401_30_dialog_content = "Berhenti! Kalian anak-anak ini sudah terlalu berlebihan dengan ini.",
  ui_story_5075_50750401_31_dialog_content = "!",
  ui_story_5075_50750401_32_dialog_content = "(Kabut hitam muncul lagi! Dan itu mengepung si iblis kecil!)",
  ui_story_5075_50750401_33_dialog_content = "Keluar dari sini, kalian anak-anak!",
  ui_story_5075_50750401_34_dialog_content = "Hah? Kenapa?",
  ui_story_5075_50750401_35_dialog_content = "...",
  ui_story_5075_50750401_36_dialog_content = "Yang ini... memang terlihat sedikit aneh, bukan?",
  ui_story_5075_50750401_37_dialog_content = "Ciit!",
  ui_story_5075_50750401_38_dialog_content = "Oh tidak, sudah terlambat—",
  ui_story_5075_50750401_39_dialog_content = "Berikut ini serudukan kepala!",
  ui_story_5075_50750401_40_dialog_content = "Mencicit—",
  ui_story_5075_50750401_41_dialog_content = "Fiendling itu... Dia ditanduk hingga terlempar ke langit.",
  ui_story_5075_50750401_42_dialog_content = "Tetap waspada! Itu datang kembali!",
  ui_story_5075_50750402_1_dialog_content = "Mencicit...",
  ui_story_5075_50750402_2_dialog_content = "Santai, semuanya baik-baik saja sekarang. Hei, berhenti menggeliat-geliut atau kamu akan semakin terluka.",
  ui_story_5075_50750402_3_dialog_content = "Mencicit! Mencicit!",
  ui_story_5075_50750402_4_dialog_content = "Kamu yang membantuku barusan, bukan? Terima kasih banyak, itu adalah perintah yang luar biasa!",
  ui_story_5075_50750402_5_dialog_content = "Aku baru saja melihatnya, cara kamu maju untuk menyelamatkan anak iblis ini. Kamu pasti orang yang sangat baik!",
  ui_story_5075_50750402_6_dialog_content = "Haha... Aku tidak melakukan banyak hal. Lagipula, kau lah yang mengalahkannya.",
  ui_story_5075_50750402_7_dialog_content = "Dan kamu melakukannya dengan sangat cepat juga! Saya rasa tidak ada yang menyadari bahwa sesuatu telah terjadi.",
  ui_story_5075_50750402_8_dialog_content = "Semua itu bagian dari pekerjaanku.",
  ui_story_5075_50750402_9_dialog_content = "Maaf, aku belum sempat memperkenalkan diri. Namaku Luo Song, dan aku adalah seorang pendeta pengembara.",
  ui_story_5075_50750402_10_dialog_content = "Ciit!",
  ui_story_5075_50750402_11_dialog_content = "Sebagian besar waktu saya hanya bepergian ke seluruh negeri, sesekali mengusir iblis.",
  ui_story_5075_50750402_12_dialog_content = "Mencicit! Mencicit!",
  ui_story_5075_50750402_13_dialog_content = "Belakangan ini, sesuatu telah membuat para fiendling di daerah ini menjadi gelisah, membuat mereka kehilangan akal sehat dan menyerang orang secara sembarangan.",
  ui_story_5075_50750402_14_dialog_content = "Aku datang ke sini untuk menyelidiki penyebab fenomena aneh ini, tapi bahkan kota yang dijaga seketat Haojin...",
  ui_story_5075_50750402_15_dialog_content = "Mencicit! Mencicit!",
  ui_story_5075_50750402_16_dialog_content = "Apakah ada yang salah dengan fiendling itu?",
  ui_story_5075_50750402_17_dialog_content = "Sepertinya begitu. Sejak saya menangkapnya, itu tidak pernah berhenti mencoba menggigit saya atau meronta untuk keluar.",
  ui_story_5075_50750402_18_dialog_content = "Hati-hati.",
  ui_story_5075_50750402_19_dialog_content = "Oh, ini bukan apa-apa. Lagipula, saya mencari nafkah dengan berurusan dengan fiendlings sepanjang waktu.",
  ui_story_5075_50750402_20_dialog_content = "Untuk fiendling seperti ini, yang perlu kamu lakukan hanyalah memegang ibu jari dan jari telunjukmu seperti ini...",
  ui_story_5075_50750402_21_dialog_content = "Dan dengan sedikit tekanan, itu tidak bisa melarikan diri!",
  ui_story_5075_50750402_22_dialog_content = "Oh begitu. Kamu pasti benar-benar seorang profesional setelah semua ini!",
  ui_story_5075_50750402_23_dialog_content = "... Tunggu, bukan itu yang sedang saya tanyakan!",
  ui_story_5075_50750402_24_dialog_content = "Biar kucoba merasakannya...",
  ui_story_5075_50750402_25_dialog_content = "Aku tahu itu. Bola kabut hitam aneh itu masih berada di dalam tubuh fiendling.",
  ui_story_5075_50750402_26_dialog_content = "\"Bola kabut hitam yang aneh\"?",
  ui_story_5075_50750402_27_dialog_content = "Ya, aku bisa melihatnya! Aku yakin kabut hitam ini yang membuat para fiendlings menjadi tidak terkendali.",
  ui_story_5075_50750402_28_dialog_content = "Seperti itu di luar keahlian saya. Sentuhan seorang master kemungkinan besar diperlukan untuk ini.",
  ui_story_5075_50750402_29_dialog_content = "Kecuali jika kamu pikir kita bisa mengalahkan kabut hitam itu?",
  ui_story_5075_50750402_30_dialog_content = "Eh, mungkin tidak.",
  ui_story_5075_50750402_31_dialog_content = "Tapi aku memang bertemu dengan seorang gadis lebih awal—",
  ui_story_5075_50750402_32_dialog_content = "Hei! Kenapa kalian tiba-tiba berlari dan berdiri di sini sambil berbisik? Apa masalahnya?",
  ui_story_5075_50750402_33_dialog_content = "Oh, aku hampir lupa tentang kumpulan anak-anak ini.",
  ui_story_5075_50750402_34_dialog_content = "Belum lagi... Aku belum sempat bertanya namamu.",
  ui_story_5075_50750402_35_dialog_content = "Aku? Saya PlayerName.",
  ui_story_5075_50750402_36_dialog_content = "Senang bertemu denganmu, PlayerName. Apakah kamu keberatan untuk menjaga orang ini untukku?",
  ui_story_5075_50750402_37_dialog_content = "Hah?",
  ui_story_5075_50750402_38_dialog_content = "Ciit!",
  ui_story_5075_50750402_39_dialog_content = "Hei, jangan asal lempar begitu saja kepadaku! Wah, setan kecil ini lebih kuat dari yang terlihat!",
  ui_story_5075_50750402_40_dialog_content = "(Itu bahkan tidak bergerak di tangan Luo Song sebelumnya! Betapa kuatnya dia—hei, berhenti menggeliat!)",
  ui_story_5075_50750402_41_option_content = "Force Boost!",
  ui_story_5075_50750402_42_dialog_content = "Mencicit...",
  ui_story_5075_50750402_43_dialog_content = "Fiuh, itu lebih baik.",
  ui_story_5075_50750402_44_dialog_content = "<color=#e8d9bb>Plak! Plak! Plak!</color>",
  ui_story_5075_50750402_45_dialog_content = "<color=#e8d9bb>Luo Song mencubit kepala anak-anak sebagai hukuman.</color>",
  ui_story_5075_50750402_46_dialog_content = "(Dengan kekuatan Luo Song, itu mungkin sangat menyakitkan...)",
  ui_story_5075_50750402_47_dialog_content = "Waaahhhh—",
  ui_story_5075_50750402_48_dialog_content = "Kamu pikir kamu siapa, memukul kepala kami seperti itu? Sakit tau!",
  ui_story_5075_50750402_49_dialog_content = "Nama saya Luo Song. Baik sedang berkeliaran di daratan atau mengendalikan iblis, itu tidak mengubah banyak hal.",
  ui_story_5075_50750402_50_dialog_content = "Itu karena aku tidak memiliki apa-apa untuk disembunyikan. Niatku tulus dan jujur.",
  ui_story_5075_50750402_51_dialog_content = "Kamu, di sisi lain, memiliki banyak yang harus dijelaskan kepada orang tuamu. Siapa namamu?",
  ui_story_5075_50750402_52_dialog_content = "Menyalakan kembang api di jalan untuk menggertak yang lemah dan tak berdaya bukanlah sesuatu yang bisa saya biarkan, bahkan untuk anak-anak.",
  ui_story_5075_50750402_53_dialog_content = "Aku, eh, namaku...",
  ui_story_5075_50750402_54_dialog_content = "Tunggu, kenapa harus aku yang memberitahumu?",
  ui_story_5075_50750402_55_dialog_content = "Orang tua saya mengatakan ini karena makhluk-makhluk jahat ini membawa nasib buruk sehingga roh-roh jahat telah bergentayangan liar akhir-akhir ini.",
  ui_story_5075_50750402_56_dialog_content = "Anda bersama mereka, yang berarti Anda juga tidak baik!",
  ui_story_5075_50750402_57_dialog_content = "Bagi saya, itu terdengar seperti takhayul belaka.",
  ui_story_5075_50750402_58_dialog_content = "Selain itu, menggunakan kata-kata orang lain untuk memaafkan perilaku burukmu tetap tidak dapat diterima.",
  ui_story_5075_50750402_59_dialog_content = "Apakah kamu pernah melihat fiendling bekerja sama dengan roh jahat?",
  ui_story_5075_50750402_60_dialog_content = "Yah... Meskipun kita belum melihat itu, makhluk jahat ini telah mencuri semangka gula kita!",
  ui_story_5075_50750402_61_dialog_content = "Semua orang menyumbang uang saku mereka untuk membelinya, tapi dalam sekejap, itu hilang.",
  ui_story_5075_50750402_62_dialog_content = "Memang!",
  ui_story_5075_50750402_63_dialog_content = "Pencuri itu tidak baik, jadi apa yang kami lakukan adalah demi menjaga keamanan komunitas!",
  ui_story_5075_50750402_64_dialog_content = "Kamu bilang itu hilang dalam sekejap, itu berarti kamu tidak pernah melihatnya mencuri camilanmu pada awalnya.",
  ui_story_5075_50750402_65_dialog_content = "Tapi makhluk ini adalah satu-satunya yang menyelinap di sekitar sini. Jika bukan dia, lalu siapa lagi yang bisa jadi?",
  ui_story_5075_50750402_66_dialog_content = "PlayerName.",
  ui_story_5075_50750402_67_dialog_content = "Bisakah kamu memeriksa mulut fiendling itu untuk sisa-sisa gula?",
  ui_story_5075_50750402_68_dialog_content = "Biarkan aku melihat... Tidak.",
  ui_story_5075_50750402_69_dialog_content = "Selain beberapa lumpur dan beberapa luka gores dan lebam, tidak ada yang lain di tubuh iblis kecil ini.",
  ui_story_5075_50750402_70_dialog_content = "Itu tidak membuktikan bahwa dia bukan pencurinya!",
  ui_story_5075_50750402_71_dialog_content = "Mungkin itu menggunakan sedikit sihir, memindahkan semangka gula ke tempat lain dengan cepat.",
  ui_story_5075_50750402_72_dialog_content = "Uh, saya tidak berpikir itu akan mencuri permen jika itu memiliki kekuatan seperti itu.",
  ui_story_5075_50750402_73_dialog_content = "Bagaimana tepatnya bentuk melon gula Anda?",
  ui_story_5075_50750402_74_dialog_content = "Bagaimana lagi bentuknya? Hanya putih, bulat, seperti...",
  ui_story_5075_50750402_75_dialog_content = "Jeruk keberuntungan yang sudah dikupas?",
  ui_story_5075_50750402_76_dialog_content = "Tepat sekali! Melon gula yang tampak begitu enak dan lezat, pasti akan disukai oleh para fiendlings.",
  ui_story_5075_50750402_77_dialog_content = "Kamu membelinya dari kios pria tua itu di atas jalan, 'kan?",
  ui_story_5075_50750402_78_dialog_content = "Jika Anda harus mengumpulkan semua uang Anda untuk membelinya, kemungkinan Anda tidak akan mampu membeli apa pun setelahnya.",
  ui_story_5075_50750402_79_dialog_content = "Tapi anak-anak itu serakah, terutama saat berhubungan dengan makanan ringan—dan kebetulan ada penjual jeruk keberuntungan yang menawarkan sampel gratis di dekat sana.",
  ui_story_5075_50750402_80_dialog_content = "Jangan bilang kau tidak melihatnya.",
  ui_story_5075_50750402_81_dialog_content = "Kita memang pergi ke sana, jadi apa?",
  ui_story_5075_50750402_82_dialog_content = "Saat kamu sedang makan jeruk keproknya, di mana kamu meletakkan semangka manismu?",
  ui_story_5075_50750402_83_dialog_content = "Saya baru saja menaruhnya tepat di sebelah stand buah... Oh!",
  ui_story_5075_50750402_84_dialog_content = "Memang, ini adalah melon gula kami, dicampur dengan jeruk keberuntungan yang sudah dikupas.",
  ui_story_5075_50750402_85_dialog_content = "...",
  ui_story_5075_50750402_86_dialog_content = "Dan begitu kebenaran muncul.",
  ui_story_5075_50750402_87_dialog_content = "Apa pembelaan kalian sekarang?",
  ui_story_5075_50750402_88_dialog_content = "Maaf...",
  ui_story_5075_50750402_89_dialog_content = "Lain kali kamu menghadapi situasi seperti ini, berhenti dan pikirkan dulu.",
  ui_story_5075_50750402_90_dialog_content = "Jangan berpikir bahwa kamu bisa menyalahkan fiendlings atas semua kemalanganmu.",
  ui_story_5075_50750402_91_dialog_content = "Katakan padaku, apakah menyakiti seorang fiendling seperti ini akan mengembalikan semangka manismu?",
  ui_story_5075_50750402_92_dialog_content = "Karena takhayul dan stereotip, kita cenderung memberi label pada hal-hal yang tidak kita mengerti sebagai \"jahat\" sehingga kita bisa menyerangnya...",
  ui_story_5075_50750402_93_dialog_content = "Tapi perilaku seperti itu tidak lebih baik dari seorang anak yang sedang mengamuk.",
  ui_story_5075_50750402_94_dialog_content = "Ini bukan tindakan kepahlawanan tetapi pengecutan. Apakah kamu mengerti?",
  ui_story_5075_50750402_95_dialog_content = "Mengerti...",
  ui_story_5075_50750402_96_dialog_content = "Baik, sekarang pulang dan ceritakan kepada orang tuamu tentang apa yang terjadi di sini hari ini.",
  ui_story_5075_50750402_97_dialog_content = "Baiklah…",
  ui_story_5075_50750402_98_dialog_content = "Apakah kamu pikir mereka benar-benar akan memberitahu orang tua mereka tentang ini?",
  ui_story_5075_50750402_99_dialog_content = "Kemungkinan besar tidak.",
  ui_story_5075_50750402_100_dialog_content = "Saya tahu bahwa kata-kata saya hanya menangani gejala masalah, bukan penyebab utamanya.",
  ui_story_5075_50750402_101_dialog_content = "Tapi rumor bisa sama berbahayanya. Ide bahwa fiendlings membawa bahaya dan kesialan hanya muncul karena cukup banyak orang yang membicarakannya.",
  ui_story_5075_50750402_102_dialog_content = "Apa yang saya katakan adalah kebenaran, dan selama saya terus mengatakan yang sebenarnya, sesuatu akan akhirnya muncul dari situ.",
  ui_story_5075_50750402_103_dialog_content = "Lagi pula, kebenaran adalah kebenaran, dan kebohongan adalah kebohongan.",
  ui_story_5075_50750402_104_dialog_content = "Kamu adalah orang yang cukup luar biasa, Luo Song.",
  ui_story_5075_50750402_105_dialog_content = "Kamu bahkan membantu mereka menemukan semangka gula mereka dalam sekejap. Seperti kamu yang secara pribadi melihat seluruh kejadian itu!",
  ui_story_5075_50750402_106_dialog_content = "Haha, soal itu...",
  ui_story_5075_50750402_107_dialog_content = "Aku tidak melihatnya sendiri, tapi ada orang yang melihatnya.",
  ui_story_5075_50750402_108_dialog_content = "Hmm... Apakah kamu ingin bertemu dengan temanku?",
  ui_story_5075_50750402_109_dialog_content = "Auuuum!",
  ui_story_5075_50750402_110_dialog_content = "Temanmu adalah seorang fiendling?",
  ui_story_5075_50750402_111_dialog_content = "Namanya adalah Ah Ding.",
  ui_story_5075_50750402_112_dialog_content = "Itu melihat anak-anak itu kehilangan semangka gula mereka sebelumnya dan menceritakannya semua padaku.",
  ui_story_5075_50750402_113_dialog_content = "Aku berniat membawanya untuk langsung memberitahu anak-anak kebenarannya, tapi seorang penjual figur gula menghentikanku.",
  ui_story_5075_50750402_114_dialog_content = "Dia memberitahuku bahwa orang-orang di sini memiliki pandangan yang sangat negatif terhadap fiendlings saat ini, dan membawa Ah Ding mungkin akan memperburuk keadaan.",
  ui_story_5075_50750402_115_dialog_content = "Jadi saya bilang pada Ah Ding untuk menunggu saya di sini.",
  ui_story_5075_50750402_116_dialog_content = "Penjual patung gula itulah yang mengajariku cara mendekati anak-anak itu dengan kejujuran.",
  ui_story_5075_50750402_117_dialog_content = "Ketika saya memikirkannya, pandangannya benar-benar valid.",
  ui_story_5075_50750402_118_dialog_content = "Aku harus pergi berterima kasih kepadanya dan membeli beberapa figurin gula untuk Ah Ding dan teman-temannya, yang bersembunyi di tempat lain.",
  ui_story_5075_50750402_119_dialog_content = "Uh, Luo Song? Aku tahu ini mungkin terdengar aneh, tapi... Apakah pria di sana itu \"penjual figur gula\" yang kamu maksud?",
  ui_story_5075_50750402_120_dialog_content = "Ya, itu dia!",
  ui_story_5075_50750402_121_dialog_content = "Bisakah kamu menunggu di sini beberapa menit sementara aku pergi menyapa teman-teman kecilku? Aku akan segera kembali.",
  ui_story_5075_50750402_122_dialog_content = "...",
  ui_story_5075_50750402_123_dialog_content = "\"Penjual patung gula\"?",
  ui_story_5075_50750402_124_dialog_content = "Ya, itu aku benar!",
  ui_story_5075_50750500_1_dialog_content = "... Bukankah kamu seharusnya seorang peramal?",
  ui_story_5075_50750500_2_dialog_content = "Tidak-tidak. Lihatlah sirup ini yang benar-benar jernih.",
  ui_story_5075_50750500_3_dialog_content = "Lalu lihatlah keahlian membuatnya tampak seperti nyata.",
  ui_story_5075_50750500_4_dialog_content = "Ini hanya mungkin dengan keterampilan yang diturunkan selama generasi ditambah tahun-tahun pengalaman.",
  ui_story_5075_50750500_5_dialog_content = "Saya bersumpah di makam leluhurku bahwa saya adalah pembuat figurin gula yang asli.",
  ui_story_5075_50750500_6_dialog_content = "Sudah cukup lama sejak kita berpisah di Shadowind.",
  ui_story_5075_50750500_7_dialog_content = "Takdir membawa kita berdua ke sini, jadi mengapa saya tidak menawarkan Anda patung gula gratis?",
  ui_story_5075_50750500_8_dialog_content = "Aku tidak bermaksud mencurigakanmu atau apa pun.",
  ui_story_5075_50750500_9_dialog_content = "Tapi, hadiah darimu bukanlah sesuatu yang bisa dengan mudah aku terima.",
  ui_story_5075_50750500_10_dialog_content = "Sayang sekali. Sulit dipercaya...",
  ui_story_5075_50750500_11_dialog_content = "Meskipun baru mengenalku dalam waktu singkat, kamu sudah sangat memahamiku.",
  ui_story_5075_50750500_12_dialog_content = "Karena kamu telah melihat melalui diriku, aku akan langsung ke intinya. Ini, silakan ambil ini.",
  ui_story_5075_50750500_13_dialog_content = "Itu adalah aksesori untuk gadis, bukan?",
  ui_story_5075_50750500_14_dialog_content = "Seorang pelanggan saya menjatuhkan ini secara tidak sengaja tepat sebelum Anda datang.",
  ui_story_5075_50750500_15_dialog_content = "Tapi saya terlalu sibuk dengan penjualan untuk mencarinya, jadi itu semua terserah kamu.",
  ui_story_5075_50750500_16_dialog_content = "Tapi aku juga punya hal yang harus dilakukan.",
  ui_story_5075_50750500_17_dialog_content = "Jangan khawatir. Saya menemukan ada ikatan karma yang kuat antara kalian berdua melalui ramalan.",
  ui_story_5075_50750500_18_dialog_content = "Lakukan saja urusanmu sendiri, dan kalian akan bertemu secara alami.",
  ui_story_5075_50750500_19_dialog_content = "Tebakanmu masih seorang peramal setelah semua ini.",
  ui_story_5075_50750500_20_dialog_content = "Tunggu, sekarang setelah aku melihat lebih dekat, ini terlihat seperti yang aku temukan di Kuil Maiden Naga.",
  ui_story_5075_50750500_21_dialog_content = "Dan aku ingat melihatnya juga pada orang lain.",
  ui_story_5075_50750500_22_dialog_content = "Mana mungkin...",
  ui_story_5075_50750500_23_dialog_content = "Beritahu saya, apakah Anda tahu sesuatu tentang <color=#FFB400>fiendlings</color>? Li Tianxian?",
  ui_story_5075_50750500_24_dialog_content = "Tentu saja saya ingat. Apakah kamu ingat <color=#FFB400>Heavenly Hexagram Divination</color> spesial yang saya ciptakan sendiri?",
  ui_story_5075_50750500_25_dialog_content = "Ini juga ada hubungannya dengan <color=#FFB400>Tiga Belas Fiendlings Utama</color> yang paling dihormati di Longzhou.",
  ui_story_5075_50750500_26_dialog_content = "Tapi bukankah itu hewan?",
  ui_story_5075_50750500_27_dialog_content = "Hewan, fiendlings, dan dewa hanya berbeda berdasarkan penampilan spesifik mereka.",
  ui_story_5075_50750500_28_dialog_content = "Bukankah Zhong Xu sudah menceritakan kepada Anda tentang kisah para pelindung iblis yang akhirnya dianugerahi kedewaan?",
  ui_story_5075_50750500_29_dialog_content = "Tiga belas fiendlings ini juga merupakan dewa paling unik di Longzhou.",
  ui_story_5075_50750500_30_dialog_content = "<color=#FFB400>Dragon Maiden</color> dalam <color=#FFB400>Dragon Maiden Over Turbulent Seas</color> yang kamu kenal adalah salah satunya.",
  ui_story_5075_50750500_31_dialog_content = "Meskipun waktu telah membuat orang-orang melupakan bahwa dewa yang mereka sembah sebenarnya adalah fiendlings.",
  ui_story_5075_50750500_32_dialog_content = "Saya melantur—kembali ke pertanyaan Anda.",
  ui_story_5075_50750500_33_dialog_content = "Fiendlings juga menguasai berbagai Seni Kekuatan, dan untuk fiendlings utama—atau dewa-dewa...",
  ui_story_5075_50750500_34_dialog_content = "Kekuatan mereka sangat canggih, sehingga disebut \"supranatural.\"",
  ui_story_5075_50750500_35_dialog_content = "Dikatakan mereka bisa mengubah cuaca, menjadi tak kasat mata, atau berubah bentuk sesuka hati.",
  ui_story_5075_50750500_36_dialog_content = "Betapa patut ditiru.",
  ui_story_5075_50750500_37_dialog_content = "Jangan bilang gadis itu juga seorang... Tunggu, apakah saya sudah bertanya tentang kekuatan para fiendling?",
  ui_story_5075_50750500_38_dialog_content = "Tentu saja kamu melakukannya!",
  ui_story_5075_50750500_39_dialog_content = "Oh... Ini pasti beberapa Luminatics yang sangat kuat. Saya tidak yakin apakah saya bisa merasakan sesuatu di level ini.",
  ui_story_5075_50750500_40_dialog_content = "Saya khawatir Anda harus menanyakan itu sendiri kepada <color=#FFB400>dewa-dewi</color>.",
  ui_story_5075_50750500_41_dialog_content = "Sebenarnya, saya punya mantra untukmu, meskipun itu tidak ada hubungannya dengan hal-hal supranatural.",
  ui_story_5075_50750500_42_dialog_content = "Ini diturunkan dari orang-orang Longzhou kuno dan sangat berguna untuk keadaan ini.",
  ui_story_5075_50750500_43_dialog_content = "Yuk, ulangi kata-kataku.",
  ui_story_5075_50750500_44_dialog_content = "<color=#FFB400>Merry—Tahun—Baru.</color>",
  ui_story_5075_50750500_45_dialog_content = "Merry—Tahun—Baru.",
  ui_story_5075_50750500_46_dialog_content = "Berikut ini. Kamu pasti akan menggunakannya dengan baik dalam beberapa hari ke depan, dijamin.",
  ui_story_5075_50750500_47_dialog_content = "Tidak peduli masalah apa yang Anda hadapi, cukup ulangi saja, dan sebagian besar segalanya akan baik-baik saja.",
  ui_story_5075_50750500_48_dialog_content = "Apakah mantra sederhana seperti itu benar-benar begitu kuat?",
  ui_story_5075_50750500_49_dialog_content = "Oh, jangan meremehkan kekuatan mantra kuno.",
  ui_story_5075_50750500_50_dialog_content = "Sebenarnya ada empat bagian dari mantra, tapi sisanya mungkin masih di luar jangkauanmu saat ini.",
  ui_story_5075_50750500_51_dialog_content = "Nanti jika ada kesempatan, aku akan mengajarkan mereka padamu.",
  ui_story_5075_50750500_52_dialog_content = "Oke! Terima kasih banyak!",
  ui_story_5075_50750500_53_dialog_content = "Bukan masalah.",
  ui_story_5075_50750500_54_dialog_content = "Mengenai masalah lainnya, saya sangat ingin membacakan untuk Anda...",
  ui_story_5075_50750500_55_dialog_content = "Aku kembali, PlayerName. Maaf telah membuatmu menunggu.",
  ui_story_5075_50750500_56_dialog_content = "Tapi aku benar-benar tidak punya waktu sekarang.",
  ui_story_5075_50750500_57_dialog_content = "Jadi kamu tidak akan membaca ramalan saya setelah semua ini?",
  ui_story_5075_50750500_58_dialog_content = "Keberuntungan apa yang kamu bicarakan?",
  ui_story_5075_50750500_59_dialog_content = "Itu mengingatkan saya! Anda mengatakan Anda adalah pendeta pengembara, Luo Song? Apakah itu berarti Anda juga bisa menggunakan ramalan untuk meramalkan masa depan?",
  ui_story_5075_50750500_60_dialog_content = "Apa? Jangan biarkan orang lain menipumu begitu saja, PlayerName.",
  ui_story_5075_50750500_61_dialog_content = "Semua pembicaraan tentang takdir, nasib, dan karma mungkin terdengar meyakinkan, bahkan seperti keajaiban.",
  ui_story_5075_50750500_62_dialog_content = "Tapi itu tidak lebih dari tipuan murah yang didukung oleh kebohongan cerdas.",
  ui_story_5075_50750500_63_dialog_content = "Hah?",
  ui_story_5075_50750500_64_dialog_content = "Selama Anda melakukan sesuatu dengan hati nurani yang jernih, hasil apa pun yang Anda inginkan adalah mungkin.",
  ui_story_5075_50750500_65_dialog_content = "Lebih baik mengambil nasibmu sendiri, daripada menyerahkannya pada tongkat sihir penipu.",
  ui_story_5075_50750500_66_dialog_content = "(Li Tianxian...)",
  ui_story_5075_50750500_67_dialog_content = "(Jangan lihat aku, aku hanya pembuat patung gula.)",
  ui_story_5075_50750500_68_dialog_content = "Yang konyol.",
  ui_story_5075_50750500_69_dialog_content = "Pikiran satu jalur.",
  ui_story_5075_50750500_70_dialog_content = "Tidak tahu apa-apa, tidak tahu apa-apa.",
  ui_story_5075_50750500_71_dialog_content = "Masalah, masalah.",
  ui_story_5075_50750500_72_dialog_content = "Omong kosong apa yang kalian berdua oceh sekarang? Sangat tidak jelas, haha.",
  ui_story_5075_50750500_73_dialog_content = "...",
  ui_story_5075_50750500_74_dialog_content = "Hei, patung gula Anda sudah siap.",
  ui_story_5075_50750500_75_dialog_content = "Terima kasih... Tunggu, ini hanya bunga plum! Di mana patung gulaku?",
  ui_story_5075_50750500_76_dialog_content = "Oh maaf, sirupku hampir habis.",
  ui_story_5075_50750500_77_dialog_content = "Tapi jangan marah, ya. Maksudku, seperti yang ada di puisi...",
  ui_story_5075_50750500_78_dialog_content = "Kecantikan surgawi, sumber kebahagiaanku, hujan di malam hari, kabut pagi yang samar, aku merindukan sentuhanmu sepanjang malam yang sepi. Sementara bunga plum mekar di jendela yang begitu terang, mereka mengulurkan kelopak mereka, begitu cepat mereka muncul, meyakinkan hatiku bahwa kecantikanku ada di dekat.",
  ui_story_5075_50750500_79_dialog_content = "Jadi mengapa kamu tidak bisa melihat <color=#FFB400>bunga plum</color> ini sebagai <color=#FFB400>kecantikan</color> yang manis?",
  ui_story_5075_50750500_80_dialog_content = "Menurutku itu terdengar seperti alasan yang cukup lemah.",
  ui_story_5075_50750500_81_dialog_content = "Ayo, kita semua harus romantis kadang-kadang.",
  ui_story_5075_50750500_82_dialog_content = "Baiklah, aku akan membiarkanmu pergi sekarang. Sampai jumpa nanti!",
  ui_story_5075_50750500_83_dialog_content = "Ingat apa yang saya katakan. Jika kamu ragu, coba <color=#FFB400>berdoa kepada para dewa</color>.",
  ui_story_5075_50750500_84_dialog_content = "Mereka seharusnya mempertunjukkan Dragon Maiden Over Turbulent Seas di pameran nanti.",
  ui_story_5075_50750500_85_dialog_content = "Tapi dewa di atas panggung itu bukan dewa betulan.",
  ui_story_5075_50750500_86_dialog_content = "Hah? Apakah itu... kabut hitam?",
  ui_story_5075_50750500_87_dialog_content = "Aku harus pergi menyelidiki!",
  ui_story_5075_50750500_88_dialog_content = "Tunggu, PlayerName, aku akan pergi bersamamu—",
  ui_story_5075_50750500_89_dialog_content = "Akhirnya, saya bisa membaca sekarang setelah gangguan itu hilang.",
  ui_story_5075_50750500_90_dialog_content = "Uh-oh.",
  ui_story_5075_50750500_91_dialog_content = "Dewa di atas panggung itu mungkin benar-benar nyata.",
  ui_story_5075_50750601_1_dialog_content = "Mencicit, mencicit!",
  ui_story_5075_50750601_2_dialog_content = "Tetap diam dan coba untuk tidak menarik perhatian terlalu banyak.",
  ui_story_5075_50750601_3_dialog_content = "Hah? Dia sudah bangun.",
  ui_story_5075_50750601_4_dialog_content = "Semakin dekat dengan pameran, semakin keras ia berjuang...",
  ui_story_5075_50750601_5_dialog_content = "Ini pasti karena kedekatannya dengan kabut hitam.",
  ui_story_5075_50750601_6_dialog_content = "Berdasarkan deskripsi Anda, saya rasa benda itu memiliki kemampuan untuk merusak.",
  ui_story_5075_50750601_7_dialog_content = "Seperti racun yang menyebabkan para fiendling menjadi gila.",
  ui_story_5075_50750601_8_dialog_content = "Sayangnya, saya tidak memiliki cara untuk mengusirnya dari tubuh mereka.",
  ui_story_5075_50750601_9_dialog_content = "Saya pernah melihat fiendlings di alam liar dengan gejala yang sama, tetapi mereka tidak pernah pulih dari gejala tersebut. Yang bisa mereka lakukan hanyalah menyembunyikan diri di tempat yang jauh dari manusia.",
  ui_story_5075_50750601_10_dialog_content = "Bocah iblis kecil ini tidak berbeda...",
  ui_story_5075_50750601_11_dialog_content = "Kamu sebutkan seorang gadis yang bisa menghilangkan noda seperti itu sebelumnya. Bisa kita pergi menemuinya?",
  ui_story_5075_50750601_12_dialog_content = "Untuk mengatakan yang sebenarnya, aku baru saja bertemu dengannya hari ini. Yang aku tahu hanyalah namanya adalah Chen'ni.",
  ui_story_5075_50750601_13_dialog_content = "Sepertinya dia sendiri adalah iblis yang sangat kuat.",
  ui_story_5075_50750601_14_dialog_content = "Aksesori yang ditinggalkannya adalah satu-satunya petunjuk kita.",
  ui_story_5075_50750601_15_dialog_content = "Bagaimana seseorang bisa membiarkan kehilangan sesuatu yang sangat berharga, apalagi dua dari mereka?",
  ui_story_5075_50750601_16_dialog_content = "Kamu tidak sedang membicarakan tentang gelang kaki dan gelang tangan emas, kan?",
  ui_story_5075_50750601_17_dialog_content = "Kok kau tahu?",
  ui_story_5075_50750601_18_dialog_content = "Karena aku juga telah melihat mereka.",
  ui_story_5075_50750601_19_dialog_content = "Kamu juga punya? Baru saja ada gadis kecil yang membeli pangsit kuah dariku.",
  ui_story_5075_50750601_20_dialog_content = "Dia hanya membeli satu pangsit dan membayarnya dengan ini.",
  ui_story_5075_50750601_21_dialog_content = "Apakah ini emas? Saya baru saja akan mengatakan itu terlalu berlebihan, dan dia tiba-tiba menghilang saat saya menengadah.",
  ui_story_5075_50750601_22_dialog_content = "Sama disini, tapi aku bahkan tidak melihatnya.",
  ui_story_5075_50750601_23_dialog_content = "Yang saya perhatikan hanyalah satu mangkuk taro gula berkurang di meja ini, dan yang tersisa hanyalah potongan emas ini.",
  ui_story_5075_50750601_24_dialog_content = "Apakah kamu pikir itu adalah Dewa Rezeki?",
  ui_story_5075_50750601_25_dialog_content = "Hmm... Dia sepertinya bukan dewi kekayaan, 'kan?",
  ui_story_5075_50750601_26_dialog_content = "Apakah itu benar-benar penting sekarang?",
  ui_story_5075_50750601_27_dialog_content = "Gadis muda yang membeli umbi teratai isi emas? Saya telah melihatnya. Dia mungkin sudah masuk ke dalam.",
  ui_story_5075_50750601_28_dialog_content = "Selamat datang! Lihatlah poster tahun baru saya! Setiap poster dibuat dengan sangat teliti dan penuh perhatian terhadap detail!",
  ui_story_5075_50750601_29_dialog_content = "Gadis yang membayar dengan emas? Ya, saya ingat dia.",
  ui_story_5075_50750601_30_dialog_content = "Dia sangat menyukai poster tahun baru saya, terutama yang bertema Dragon Maiden Over Turbulent Seas. Dia mengambil cukup banyak.",
  ui_story_5075_50750601_31_dialog_content = "Saya ingat setelah dia membeli poster, ada teriakan yang datang dari panggung.",
  ui_story_5075_50750601_32_dialog_content = "Mungkin dia pergi ke sana untuk melihat apa yang sedang terjadi.",
  ui_story_5075_50750601_33_dialog_content = "Dia bilang dia punya hal lain yang harus dilakukan sebelum dia pergi. Saya rasa dia maksudnya ingin melihat-lihat pameran.",
  ui_story_5075_50750601_34_dialog_content = "Sepertinya dia juga melakukan pekerjaan yang cukup menyeluruh.",
  ui_story_5075_50750601_35_dialog_content = "Semuanya di sini rasanya sangat enak!",
  ui_story_5075_50750601_36_dialog_content = "Camilan beras ini tidak se-manis yang ada di Astra, tapi tetap membuat saya ingin lebih banyak lagi!",
  ui_story_5075_50750601_37_dialog_content = "Setuju! Gadis itu pasti telah memilih umbi teratai isi terbaik di antara semua ini! Mereka benar-benar luar biasa!",
  ui_story_5075_50750601_38_dialog_content = "Kamu juga menyukai mereka, Ah Ding?",
  ui_story_5075_50750601_39_dialog_content = "Groar!",
  ui_story_5075_50750601_40_dialog_content = "Itu mengingatkan saya, apa yang sedang kita lakukan di sini lagi?",
  ui_story_5075_50750601_41_dialog_content = "...",
  ui_story_5075_50750601_42_dialog_content = "...",
  ui_story_5075_50750601_43_dialog_content = "Pasar benar-benar mengalihkan pikiranmu dari segala hal, 'kan?",
  ui_story_5075_50750601_44_dialog_content = "Benar, haha...",
  ui_story_5075_50750601_45_dialog_content = "Namun, apakah Anda memperhatikan sesuatu?",
  ui_story_5075_50750601_46_dialog_content = "Fiendling yang kami bawa ke sini berhenti berjuang segera setelah kami tiba. Sepertinya dia sudah cukup tenang.",
  ui_story_5075_50750601_47_dialog_content = "Biar kucoba menggunakan kekuatanku lagi...",
  ui_story_5075_50750601_48_dialog_content = "Tidak ada lagi kabut hitam di sekitar sini! Apakah itu baru saja hilang?",
  ui_story_5075_50750601_49_dialog_content = "Ada satu kemungkinan lain. Yang buruk.",
  ui_story_5075_50750601_50_dialog_content = "Kabut mungkin berkumpul di tempat lain. Kita perlu menemukan gadis itu sebelum ada yang terluka.",
  ui_story_5075_50750601_51_dialog_content = "Hoi, PlayerName!",
  ui_story_5075_50750601_52_dialog_content = "Chen'ni! Saya sangat senang akhirnya kita...",
  ui_story_5075_50750601_53_dialog_content = "Keren, kamu membawa seorang teman!",
  ui_story_5075_50750601_54_dialog_content = "Tepat waktu! Naik ke panggung sekarang!",
  ui_story_5075_50750601_55_dialog_content = "Lakukan apa sekarang?",
  ui_story_5075_50750601_56_dialog_content = "Kamu... Maksudku, maafkan saya, tapi fiendling ini—",
  ui_story_5075_50750601_57_dialog_content = "Lagi?",
  ui_story_5075_50750601_58_dialog_content = "<color=#e8d9bb>Seperti sebelumnya, Chen'ni melambaikan tangannya secara acak, bahkan agak lalai.</color>",
  ui_story_5075_50750601_59_dialog_content = "<color=#e8d9bb>Kabut hitam di dalam fiendling ditarik keluar dan dihancurkan, seolah-olah itu tidak pernah ada.</color>",
  ui_story_5075_50750601_60_dialog_content = "Ciit!",
  ui_story_5075_50750601_61_dialog_content = "<color=#e8d9bb>Si kecil iblis melompat ringan ke kaki Chen'ni, menundukkan kepalanya seolah-olah menunjukkan rasa terima kasih.</color>",
  ui_story_5075_50750601_62_dialog_content = "Jadi kau benar-benar—",
  ui_story_5075_50750601_63_dialog_content = "Ayo, giliran kita!",
  ui_story_5075_50750601_64_dialog_content = "Ada begitu banyak orang di bawah sana!",
  ui_story_5075_50750601_65_dialog_content = "Apa sebenarnya yang seharusnya kita lakukan di sini?",
  ui_story_5075_50750601_66_dialog_content = "Tentu saja, menari <color=#FFB400>Tarian Gadis Naga di Atas Lautan yang Bergolak</color>.",
  ui_story_5075_50750601_67_dialog_content = "Halo, warga negara yang saya cintai. Saya tahu semua orang datang ke sini hari ini untuk para penampil terkenal.",
  ui_story_5075_50750601_68_dialog_content = "Tapi saya yakin semua orang sudah mendengar bahwa penampil yang memerankan Dragon Maiden terbaik telah melukai kakinya dan tidak bisa tampil di panggung.",
  ui_story_5075_50750601_69_dialog_content = "Tapi kita tidak bisa meninggalkan panggung kosong selama pameran, jadi kami telah menemukan susunan baru.",
  ui_story_5075_50750601_70_dialog_content = "Selanjutnya, beberapa penampil Dragon Maiden akan bergiliran naik ke panggung, masing-masing menyajikan versi mereka sendiri dari Dragon Maiden Over Turbulent Seas.",
  ui_story_5075_50750601_71_dialog_content = "Kalian semua dapat memilih penampil Dragon Maiden terbaik di Festival Musim Semi tahun ini. Bagaimana menurut kalian?",
  ui_story_5075_50750601_72_dialog_content = "Bagus sekali!",
  ui_story_5075_50750601_73_dialog_content = "Sungguh beruntung kamu membawa seorang teman, PlayerName, atau kami tidak akan memiliki cukup orang.",
  ui_story_5075_50750601_74_dialog_content = "Temanmu akan bermain sebagai Black Dragon, si pengacau dan pengganggu di laut.",
  ui_story_5075_50750601_75_dialog_content = "Saya adalah Gadis Naga.",
  ui_story_5075_50750601_76_dialog_content = "Bagaimana dengan saya?",
  ui_story_5075_50750601_77_dialog_content = "Bersiaplah, PlayerName, karena kamu mendapatkan bagian yang paling penting.",
  ui_story_5075_50750601_78_dialog_content = "<size=50>Kamu akan menjadi laut!</size>",
  ui_story_5075_50750601_79_dialog_content = "Apakah itu perlu?",
  ui_story_5075_50750601_80_dialog_content = "Apa yang kamu katakan? Laut sangat penting.",
  ui_story_5075_50750601_81_dialog_content = "Ada musiknya. Mulai menari.",
  ui_story_5075_50750601_82_dialog_content = "Ahh—",
  ui_story_5075_50750601_83_dialog_content = "\"Diberkati takdir, Sang Gadis Naga membawa kabar baik saat ia turun ke dunia.\"",
  ui_story_5075_50750601_84_dialog_content = "\"Ombak samudra yang luas ini samar, seolah-olah terselubung asap.\"",
  ui_story_5075_50750601_85_dialog_content = "(Baiklah, tunjukkan betapa luas dan misteriusnya dirimu, laut.)",
  ui_story_5075_50750601_86_dialog_content = "(Mengedipkan mata padaku tidak mengubah apa-apa! A-Apalagi, sepertinya aku harus membuat beberapa gelombang.)",
  ui_story_5075_50750601_87_dialog_content = "\"Diberkati lah Sang Gadis Naga...\"",
  ui_story_5075_50750601_88_dialog_content = "...",
  ui_story_5075_50750601_89_dialog_content = "(Oh tidak... Jangan bilang kamu lupa dialogmu!)",
  ui_story_5075_50750601_90_dialog_content = "\"Berkat tak terhitung untuk semua\"! Itu bagian selanjutnya!",
  ui_story_5075_50750601_91_dialog_content = "(Tidak ada gunanya—dia sudah melewatkannya. Jelas kita tidak bisa mengharapkan Chen'ni untuk mengingat dialognya...)",
  ui_story_5075_50750601_92_dialog_content = "\"Saat naga jahat datang, baik matahari dan bulan kehilangan cahayanya.\"",
  ui_story_5075_50750601_93_dialog_content = "(Luo Song?)",
  ui_story_5075_50750601_94_dialog_content = "\"Guntur bergemuruh dan kilat menyambar.\"",
  ui_story_5075_50750601_95_dialog_content = "(Gerakannya kaku dan garisnya jelas salah, tapi dia melakukannya! Bagus sekali!)",
  ui_story_5075_50750601_96_dialog_content = "(Tunggu, kenapa dia tidak bergerak?)",
  ui_story_5075_50750601_97_dialog_content = "(Buruan! Guntur dan petir!)",
  ui_story_5075_50750601_98_dialog_content = "(Itu juga pekerjaanku?)",
  ui_story_5075_50750601_99_dialog_content = "(Apapun, waktunya membuat beberapa guntur.)",
  ui_story_5075_50750601_100_dialog_content = "Gruk!",
  ui_story_5075_50750601_101_dialog_content = "\"Orang-orang menonton dengan tidak berdaya saat roh-roh jahat mengaum dan mengamuk!\"",
  ui_story_5075_50750601_102_dialog_content = "\"Tapi segera, Dragon Maiden muncul dan menyelamatkan mereka dari kehancuran.\"",
  ui_story_5075_50750601_103_dialog_content = "\"Dengan kekuatan yang tak terbatas dan tekad yang tak goyah,\"",
  ui_story_5075_50750601_104_dialog_content = "\"Dia memukul para iblis dan mengirim mereka terbang ke segala arah!\"",
  ui_story_5075_50750601_105_dialog_content = "(Jadi sekarang Sang Gadis Naga menggunakan tinjunya untuk bertarung?)",
  ui_story_5075_50750601_106_dialog_content = "(Lagipula, kau seharusnya adalah naga jahat! Ucapanmu tidak bisa lebih kacau lagi!)",
  ui_story_5075_50750601_107_dialog_content = "Groar!",
  ui_story_5075_50750601_108_dialog_content = "(Dari semua kekacauan dalam drama yang berantakan ini, mengapa kamu harus membuat Eclipsite terlihat begitu nyata?)",
  ui_story_5075_50750601_109_dialog_content = "(Tunggu sebentar!)",
  ui_story_5075_50750601_110_dialog_content = "Ini adalah Eclipsite yang asli!",
  ui_story_5075_50750602_1_dialog_content = "Terima kasih kepada kalian semua yang telah membawa seperti ini...",
  ui_story_5075_50750602_2_dialog_content = "Unik... interpretasi kreatif dari... Gadis Naga di Atas Lautan yang Bergolak.",
  ui_story_5075_50750602_3_dialog_content = "Pemimpin rombongan terlihat sangat kalah. Kita pasti telah melakukan pekerjaan yang sangat buruk.",
  ui_story_5075_50750602_4_dialog_content = "Menurutku, serangan roh jahatlah yang paling merusak, jujur saja.",
  ui_story_5075_50750602_5_dialog_content = "Saya pikir Eclipsite Longzhou jarang muncul di kota-kota?",
  ui_story_5075_50750602_6_dialog_content = "Fiendlings yang gila, kabut hitam yang tak bisa dijelaskan, dan sekarang juga Eclipsites.",
  ui_story_5075_50750602_7_dialog_content = "Apa yang sebenarnya terjadi di Kota Haojin?",
  ui_story_5075_50750602_8_dialog_content = "Mengapa kalian berdua terlihat begitu khawatir?",
  ui_story_5075_50750602_9_dialog_content = "Saya pikir kita tampil baik, bahkan menangani roh jahat itu.",
  ui_story_5075_50750602_10_dialog_content = "Terutama pada bagian PlayerName. Aku suka itu!",
  ui_story_5075_50750602_11_dialog_content = "Jika kamu bisa menyebut itu sebagai pertunjukan...",
  ui_story_5075_50750602_12_dialog_content = "Aku tidak rasa bagian belakang cerita ini ada hubungannya dengan Dragon Maiden Over Turbulent Seas.",
  ui_story_5075_50750602_13_dialog_content = "Begitulah cara cerita itu diceritakan kepada saya.",
  ui_story_5075_50750602_14_dialog_content = "Delapan ratus tahun yang lalu, dunia diganggu oleh seekor naga hitam jahat.",
  ui_story_5075_50750602_15_dialog_content = "Tapi suatu hari, Maiden Naga muncul. Dari atas ombak lautan, dia berhasil mengalahkan naga jahat dengan tinjunya.",
  ui_story_5075_50750602_16_dialog_content = "Setiap pukulan memiliki kekuatan yang tak terbayangkan. Naga itu terkejut saat angin dari tinjunya mendorongnya berjalan berjauh-jauh.",
  ui_story_5075_50750602_17_dialog_content = "Sebelum bisa bereaksi, Sang Maiden Naga menyerang naga dengan hujan pukulan, menghajar hingga tak bisa dikenali lagi!",
  ui_story_5075_50750602_18_dialog_content = "Keren! Lalu? Lalu?",
  ui_story_5075_50750602_19_dialog_content = "Suara mendengung keras terdengar di telinga naga saat amarah membangun di hatinya, dan dengan ganas—",
  ui_story_5075_50750602_20_dialog_content = "Nah, saya percaya kamu tahu apa yang terjadi selanjutnya lebih baik daripada siapa pun. Lagi pula—",
  ui_story_5075_50750602_21_dialog_content = "Anda adalah Chen'ni, Naga Suci yang Maha Penyayang itu sendiri, bukan?",
  ui_story_5075_50750602_22_dialog_content = "Tunggu sebentar... Setelah mendengar apa yang Li Tianxian katakan tentang fiendling, saya tidak seharusnya kaget bahwa Chen'ni adalah semacam dewa.",
  ui_story_5075_50750602_23_dialog_content = "Tapi Chen'ni yang kita miliki di sini adalah Dragon Maiden?",
  ui_story_5075_50750602_24_dialog_content = "Itu aku, memang.",
  ui_story_5075_50750602_25_dialog_content = "Saya merasa terhormat berada di hadapan Anda, Naga Suci Yang Maha Pemurah!",
  ui_story_5075_50750602_26_dialog_content = "Itu tidak butuh waktu lama!",
  ui_story_5075_50750602_27_dialog_content = "Sebuah dewa yang asli, makhluk yang tercerahkan, berdiri tepat di depan kita. Adalah pantas jika kita menunjukkan penghormatan kita.",
  ui_story_5075_50750602_28_dialog_content = "Nona Chen'ni, apakah ada alasan khusus Anda muncul di Haojin?",
  ui_story_5075_50750602_29_dialog_content = "Seseorang merusak segel dan mengganggu tidurku. Saya di sini untuk keadilan.",
  ui_story_5075_50750602_30_dialog_content = "I-Itu terdengar seperti bencana!",
  ui_story_5075_50750602_31_dialog_content = "Jadi, kemunculan roh jahat dan makhluk iblis yang gelisah adalah karena segel naga jahat telah rusak?",
  ui_story_5075_50750602_32_dialog_content = "Jadi naga hitam itu juga nyata, ya?",
  ui_story_5075_50750602_33_dialog_content = "Benar, meskipun ada begitu banyak versi berbeda dari Dragon Maiden Over Turbulent Seas, semuanya berdasarkan pada peristiwa sejarah yang nyata.",
  ui_story_5075_50750602_34_dialog_content = "Inilah sebabnya mengapa bagian terpenting dari cerita ini sebagian besar sama.",
  ui_story_5075_50750602_35_dialog_content = "Naga jahat yang mengacaukan dunia, Gadis Naga yang menyegelnya di dasar laut, dan orang-orang yang kembali merasakan kedamaian.",
  ui_story_5075_50750602_36_dialog_content = "Tapi, peristiwa dalam cerita itu terjadi lebih dari delapan ratus tahun yang lalu.",
  ui_story_5075_50750602_37_dialog_content = "Bagaimana mungkin naga hitam masih bisa hidup setelah seluruh waktu ini?",
  ui_story_5075_50750602_38_dialog_content = "Naga hitam sudah lama mati. Itu bukanlah masalah.",
  ui_story_5075_50750602_39_dialog_content = "Tapi, apa yang terjadi pada waktu itu bukanlah salah dari keluargaku.",
  ui_story_5075_50750602_40_dialog_content = "Ada jurang dalam di bawah laut tempat seorang iblis yang kuat dikubur bersama dendamnya yang luar biasa.",
  ui_story_5075_50750602_41_dialog_content = "Rekan saya menemukannya dan dikalahkan oleh dendam, sehingga terjadi keributan di laut.",
  ui_story_5075_50750602_42_dialog_content = "Meskipun segel telah dilepaskan, kekuatanku tetap ada. Meskipun dendam juga telah dilepaskan, itu tidak bisa membahayakan dunia tanpa wadah fisik.",
  ui_story_5075_50750602_43_dialog_content = "Meskipun memiliki tubuh baru, ia masih tidak bisa bergerak bebas sampai benar-benar teraklimatisasi.",
  ui_story_5075_50750602_44_dialog_content = "(Jadi, hal yang sempat aku rasakan sebelumnya adalah iblis yang kuat?)",
  ui_story_5075_50750602_45_dialog_content = "(Itu tidak terasa benar... Tapi aku tidak sempat melihatnya dengan baik. Untungnya, menurut Chen'ni, kita masih punya waktu.)",
  ui_story_5075_50750602_46_dialog_content = "Tidak peduli bagaimana Anda melihatnya, Chen'ni memiliki tujuan yang sama dengan kita.",
  ui_story_5075_50750602_47_dialog_content = "Jika kita sedang bekerja sama untuk sementara waktu, bisakah aku mengajukan pertanyaan kecil?",
  ui_story_5075_50750602_48_dialog_content = "Ya.",
  ui_story_5075_50750602_49_dialog_content = "Aku yakin pertama kali kita bertemu adalah di Kuil Maiden Naga.",
  ui_story_5075_50750602_50_dialog_content = "Tapi jika kamu adalah Sang Dragon Maiden sendiri, lalu... kenapa kamu mencuri persembahanmu sendiri?",
  ui_story_5075_50750602_51_dialog_content = "... Itu bukan mencuri.",
  ui_story_5075_50750602_52_dialog_content = "Saya mengambil hadiah yang ditujukan untuk saya. Bagaimana itu bisa disebut mencuri? Humph!",
  ui_story_5075_50750602_53_dialog_content = "Haha, salahku. Kamu hanya menerima persembahanmu, bukan mencurinya.",
  ui_story_5075_50750602_54_dialog_content = "Kurasa aku sudah terbiasa melihatmu seperti ini.",
  ui_story_5075_50750602_55_dialog_content = "Pokoknya, saya cukup yakin aksesoris emas ini milikmu, Chen'ni?",
  ui_story_5075_50750602_56_dialog_content = "Saya menemukan salah satu dari ini di Kuil Gadis Naga, dan yang lain diberikan kepadaku oleh Li Tianxian... uh, maksudku seorang penjual figurin gula. Dia ingin mengembalikannya kepadamu.",
  ui_story_5075_50750602_57_dialog_content = "Aku hanya akan membawa satu kembali.",
  ui_story_5075_50750602_58_dialog_content = "Karena kamu menemukan yang lainnya di kuilku, PlayerName, kamu bisa menyimpannya.",
  ui_story_5075_50750602_59_dialog_content = "Jika kamu memiliki kebutuhan di masa mendatang, aku akan mengabulkan satu permintaanmu melalui itu.",
  ui_story_5075_50750602_60_dialog_content = "Sebuah harapan...",
  ui_story_5075_50750602_61_dialog_content = "Maaf mengganggu, teman-teman.",
  ui_story_5075_50750602_62_dialog_content = "Oh, halo. Maaf soal yang terjadi tadi.",
  ui_story_5075_50750602_63_dialog_content = "Nah, seharusnya aku yang berterima kasih padamu. Tidak ada kerusakan lain kecuali panggung yang rusak.",
  ui_story_5075_50750602_64_dialog_content = "Meski kompetisi harus berakhir seperti ini, dan kita tidak bisa memberikan hadiah, tetap saja, silakan terima ini.",
  ui_story_5075_50750602_65_dialog_content = "Ini adalah camilan buatan sendiri, tidak seaneh yang dijual di luar sana.",
  ui_story_5075_50750602_66_dialog_content = "Tapi ini dibuat dengan resep rahasia yang diwariskan dalam keluarga saya, tidak tersedia di tempat lain. Silakan coba.",
  ui_story_5075_50750602_67_dialog_content = "Ini dia!",
  ui_story_5075_50750602_68_dialog_content = "Aku mendaftar untuk kompetisi karena aku menciumnya. Aku melihat sebenarnya itu bukan hadiahnya.",
  ui_story_5075_50750602_69_dialog_content = "Kamu melakukan semua itu demi camilan?",
  ui_story_5075_50750602_70_dialog_content = "Nyam-nyam.",
  ui_story_5075_50750602_71_dialog_content = "Ya, ini dia rasanya. Kamu membuatnya dengan cara yang sama seperti cara kakekmu membuatnya!",
  ui_story_5075_50750602_72_dialog_content = "Yah, sepertinya aku bisa menyebut tur adilku sukses besar.",
  ui_story_5075_50750602_73_dialog_content = "Ayo.",
  ui_story_5075_50750602_74_dialog_content = "Ini persis seperti yang dibuat kakekku... Dia meninggal beberapa tahun yang lalu, dan kami tidak pernah menjual sesuatu seperti ini.",
  ui_story_5075_50750602_75_dialog_content = "Tunggu sebentar...!!!",
  ui_story_5075_50750602_76_dialog_content = "Coba cicipi juga, PlayerName, Luo Song, dan Ah Ding.",
  ui_story_5075_50750602_77_dialog_content = "Kudapan ini benar-benar fantastis. Sayangnya, hanya keluarganya yang bisa membuatnya.",
  ui_story_5075_50750602_78_dialog_content = "Groar!",
  ui_story_5075_50750602_79_dialog_content = "Terima kasih, Nona Chen'ni!",
  ui_story_5075_50750602_80_dialog_content = "Kita pernah berkumpul sebelumnya, jadi panggil saja aku Chen'ni.",
  ui_story_5075_50750602_81_dialog_content = "Perintahmu adalah perintahku!",
  ui_story_5075_50750602_82_dialog_content = "Kenapa kamu tidak makan, PlayerName?",
  ui_story_5075_50750602_83_dialog_content = "Apakah ini benar-benar baik-baik saja?",
  ui_story_5075_50750602_84_dialog_content = "Apa maksudmu?",
  ui_story_5075_50750602_85_dialog_content = "Pemimpin grup adalah keturunan dari seseorang yang dulu Anda kenal, bukan?",
  ui_story_5075_50750602_86_dialog_content = "Tidak ada lagi yang ingin kamu katakan kepadanya?",
  ui_story_5075_50750602_87_dialog_content = "Hmm…",
  ui_story_5075_50750602_88_dialog_content = "Aku adalah naga, fiendling utama, dan dewa laut bagi semua orang. Tidak seperti orang biasa, aku bisa hidup sangat, sangat lama.",
  ui_story_5075_50750602_89_dialog_content = "Jadi, aku bisa bertemu dengan banyak, banyak orang.",
  ui_story_5075_50750602_90_dialog_content = "Pemimpin rombongan itu adalah cucu dari seseorang yang dulu selalu memberi saya makanan ringan.",
  ui_story_5075_50750602_91_dialog_content = "Jalan di sisi timur adalah tempat cucu perempuan dari seorang pria yang pernah mendayung perahu bersamaku akan menikah.",
  ui_story_5075_50750602_92_dialog_content = "Sebuah gang di ujung selatan sungai adalah tempat keponakan muda dari pria yang selalu mengalahkan saya dalam pertandingan kriket dimakamkan.",
  ui_story_5075_50750602_93_dialog_content = "Anak itu juga kebetulan menjadi kerabat darah terakhirnya di dunia ini.",
  ui_story_5075_50750602_94_dialog_content = "Hidup terlalu singkat untuk semua orang, jadi mereka terburu-buru dalam segala hal.",
  ui_story_5075_50750602_95_dialog_content = "Lalu mereka selalu merasa perlu untuk membuktikan ikatan mereka dengan ritual atau upacara.",
  ui_story_5075_50750602_96_dialog_content = "Jika aku harus mengenal keturunan mereka hanya karena aku bertemu dengan seseorang...",
  ui_story_5075_50750602_97_dialog_content = "Aku akan menghabiskan seluruh waktuku bolak-balik menghadiri upacara.",
  ui_story_5075_50750602_98_dialog_content = "Tapi, tidakkah kamu merasa kesepian dengan cara itu?",
  ui_story_5075_50750602_99_dialog_content = "Karena umur panjangmu, kamu selalu menjadi orang yang harus mengucapkan selamat tinggal pada teman-temanmu.",
  ui_story_5075_50750602_100_dialog_content = "Tidak, saya rasa ini sudah baik seperti ini.",
  ui_story_5075_50750602_101_dialog_content = "Anda juga harus merasa beruntung, PlayerName.",
  ui_story_5075_50750602_102_dialog_content = "Karena kamu mengenal aku yang akan hidup dalam waktu yang sangat lama, dan aku akan mengingatmu.",
  ui_story_5075_50750602_103_dialog_content = "Bahkan jika kau harus mati, kau akan tetap ada dalam kenanganku, bersamaku selamanya.",
  ui_story_5075_50750602_104_dialog_content = "(Aku selalu bisa sedikit memahami apa yang dia maksud, tapi tidak pernah sepenuhnya mengerti.)",
  ui_story_5075_50750602_105_dialog_content = "(Baik itu senyum ceria di wajahnya, atau perasaan yang dia ungkapkan.)",
  ui_story_5075_50750602_106_dialog_content = "(Pada saat itu, tiba-tiba aku mengerti—kita memang tidak sama.)",
  ui_story_5075_50750701_1_dialog_content = "Kami. Adalah. Berbeda.",
  ui_story_5075_50750701_2_dialog_content = "Jadi.",
  ui_story_5075_50750701_3_dialog_content = "Kami. Tidak. Cocok.",
  ui_story_5075_50750701_4_dialog_content = "Argh…",
  ui_story_5075_50750701_5_dialog_content = "Apakah kamu baik-baik saja? Apakah kamu perlu istirahat?",
  ui_story_5075_50750701_6_dialog_content = "Kau telah merasakan kabut hitam sepanjang waktu ini. Apakah kamu yakin bisa terus melanjutkan?",
  ui_story_5075_50750701_7_dialog_content = "Tentu saja aku bisa. Aku tidak selemah itu.",
  ui_story_5075_50750701_8_dialog_content = "Juga, semakin saya merasakan kabut hitam ini, semakin saya menyadari bahwa itu tidak jauh berbeda dari Darkflow.",
  ui_story_5075_50750701_9_dialog_content = "Perbedaan terbesar adalah sifatnya yang menular dan merusak, yang membuatnya sulit untuk dihilangkan dengan metode biasa yang kita gunakan untuk melawan Darkflow.",
  ui_story_5075_50750701_10_dialog_content = "Jika Chen'ni benar, dan penyebab utama dari sifat-sifat ini adalah dendam, maka mungkin itu memiliki bentuk kesadaran tertentu.",
  ui_story_5075_50750701_11_dialog_content = "Jika begitu, seharusnya aku bisa menggunakan kekuatanku untuk mengganggunya!",
  ui_story_5075_50750701_12_dialog_content = "Setelah beberapa percobaan, saya menyadari bahwa saya bisa menggunakan kemampuan psikis saya untuk mengisolasi kekuatan korupsi dari kabut hitam.",
  ui_story_5075_50750701_13_dialog_content = "Jika aku terus berlatih, mungkin aku bahkan bisa membantu fiendlings yang sudah terkorupsi.",
  ui_story_5075_50750701_14_dialog_content = "Sebenarnya, tak masalah serahkan semuanya padaku.",
  ui_story_5075_50750701_15_dialog_content = "Itu tidak bisa. Kita sedang bekerja sama sekarang, yang berarti saya tidak bisa membiarkan kamu melakukan semua pekerjaan.",
  ui_story_5075_50750701_16_dialog_content = "Maka aku akan menyerahkan pekerjaan halus itu di tanganmu. Jika ada yang membutuhkan sentuhan yang lebih berat, tinju saya selalu siap untuk tugas itu!",
  ui_story_5075_50750701_17_dialog_content = "Mengaum-",
  ui_story_5075_50750701_18_dialog_content = "Hal yang sama berlaku untuk Ah Ding!",
  ui_story_5075_50750701_19_dialog_content = "Groar!",
  ui_story_5075_50750701_20_dialog_content = "Ciit!",
  ui_story_5075_50750701_21_dialog_content = "Bukankah itu bocah nakal kecil yang sama dari sebelumnya? Apa yang sedang dia lakukan di sini?",
  ui_story_5075_50750701_22_dialog_content = "Bukankah aku sudah memintamu untuk menyuruhnya mencari teman-temanmu, Ah Ding?",
  ui_story_5075_50750701_23_dialog_content = "Aum...",
  ui_story_5075_50750701_24_dialog_content = "Itu tidak mau mendengarkan, ya?",
  ui_story_5075_50750701_25_dialog_content = "Saat aku sedang berlatih dengan kemampuan psikisku, aku menyadari bahwa sejak awal itu telah mengikuti kita dari jarak jauh.",
  ui_story_5075_50750701_26_dialog_content = "Mungkin dia hanya takut? Dia mungkin berpikir lebih aman untuk tinggal bersama kita setelah dia rusak.",
  ui_story_5075_50750701_27_dialog_content = "Saya hampir tidak mempertimbangkan berada di sisi kita sebagai pilihan yang aman. Lagipula, kita akan...",
  ui_story_5075_50750701_28_dialog_content = "Tunggu, apakah saya lupa bertanya kemana kita akan pergi?",
  ui_story_5075_50750701_29_dialog_content = "Jalan Yulin.",
  ui_story_5075_50750701_30_dialog_content = "Dari mana asal getaran menjijikkan ini.",
  ui_story_5075_50750701_31_dialog_content = "Hah?",
  ui_story_5075_50750701_32_dialog_content = "Apakah ini berarti tujuan kita sebenarnya berbeda?",
  ui_story_5075_50750701_33_dialog_content = "?",
  ui_story_5075_50750701_34_dialog_content = "Kurasa bukan begitu. Jika itu masalahnya, kita pasti sudah mengalami masalah sejak lama.",
  ui_story_5075_50750701_35_dialog_content = "Mungkin itu tidak terlalu penting.",
  ui_story_5075_50750701_36_dialog_content = "Kita sudah berada di tujuan PlayerName sekarang juga.",
  ui_story_5075_50750701_37_dialog_content = "Apakah saya melihat sesuatu? Mengapa setiap toko tampak lebih mewah daripada yang sebelumnya?",
  ui_story_5075_50750701_38_dialog_content = "Jadi ini adalah Jalan Yulin... Meski tidak semeriah pameran, tapi tetap sangat mengesankan.",
  ui_story_5075_50750701_39_dialog_content = "Aku tahu. Ini adalah tempat di mana semua orang kaya tinggal.",
  ui_story_5075_50750701_40_dialog_content = "<color=#e8d9bb>Sungai yang jernih membelah seluruh jalan, dikelilingi oleh gedung-gedung tinggi. Bahkan di musim dingin, mereka dihiasi dengan bunga-bunga berwarna cerah dari berbagai warna.</color>",
  ui_story_5075_50750701_41_dialog_content = "<color=#e8d9bb>Pita-pita berwarna berkelip-kelip di antara bangunan, dan ketika angin bertiup, ia memicu suara gemerincing lonceng perak.</color>",
  ui_story_5075_50750701_42_dialog_content = "<color=#e8d9bb>Di menara tinggi dan rendah, tiga ribu gadis menari, kecantikan mereka bersinar. Dari timur ke barat, di perairan yang memberkahi, kapal-kapal berisi emas berbaris tanpa henti.</color>",
  ui_story_5075_50750701_43_dialog_content = "Apa itu patung di sisi jalan?",
  ui_story_5075_50750701_44_dialog_content = "Sekolah ikan mengelilingi sebuah perahu. Ada sesuatu yang familiar tentang perahu dan ekor ikan-ikan tersebut...",
  ui_story_5075_50750701_45_dialog_content = "Di mana saya pernah melihat ini sebelumnya?",
  ui_story_5075_50750701_46_dialog_content = "Mereka adalah ikan ular. Mereka selalu berenang bolak-balik dalam kelompok.",
  ui_story_5075_50750701_47_dialog_content = "Tetapi tidak peduli seberapa jauh mereka pergi, mereka akan kembali ke lepas pantai Longzhou untuk bertelur di musim dingin.",
  ui_story_5075_50750701_48_dialog_content = "Jadi banyak pelaut yang memohon kepada mereka untuk membimbing kapal mereka.",
  ui_story_5075_50750701_49_dialog_content = "Meminta bantuan pada ikan?",
  ui_story_5075_50750701_50_dialog_content = "Tentu. Orang selalu memberikan persembahan kepada hewan atau fiendling untuk bantuan.",
  ui_story_5075_50750701_51_dialog_content = "Bukankah itu sudah menjadi cara sejak zaman kuno?",
  ui_story_5075_50750701_52_dialog_content = "Sepertinya bukan itu masalahnya, setidaknya tidak sekarang...",
  ui_story_5075_50750701_53_dialog_content = "Patung ini pasti sudah berumur banyak tahun sekarang, dan ditutupi oleh goresan dan kotoran. Saya rasa tidak ada yang merawatnya dalam waktu yang lama.",
  ui_story_5075_50750701_54_dialog_content = "Meskipun mereka sebelumnya dalam hubungan baik, saya khawatir saat itu...",
  ui_story_5075_50750701_55_dialog_content = "Waktu itu telah lama berakhir.",
  ui_story_5075_50750701_56_dialog_content = "Yuebai! Akhirnya kamu kembali ke Haojin.",
  ui_story_5075_50750701_57_dialog_content = "Saya kembali beberapa hari yang lalu, tetapi urusan mendesak dengan keluarga Lin membuat saya tidak bisa bertemu dengan Anda lebih cepat.",
  ui_story_5075_50750701_58_dialog_content = "Maka itu adalah hal yang baik kita bertemu di sini!",
  ui_story_5075_50750701_59_dialog_content = "Masalah apa yang sedang dihadapi oleh Keluarga Lin sekarang?",
  ui_story_5075_50750701_60_dialog_content = "Saya tidak akan menyebutnya sebagai masalah.",
  ui_story_5075_50750701_61_dialog_content = "Ini lebih seperti sebuah kesalahan.",
  ui_story_5075_50750701_62_dialog_content = "Kesalahan yang dibuat oleh Keluarga Lin terkait ikan ular.",
  ui_story_5075_50750701_63_dialog_content = "Apakah itu sebabnya kamu bilang, \"Waktu itu sudah lama berakhir\"?",
  ui_story_5075_50750701_64_dialog_content = "Ya.",
  ui_story_5075_50750701_65_dialog_content = "Tolong jangan menyentuh ekorku.",
  ui_story_5075_50750701_66_dialog_content = "T-Tapi aku tidak menyentuh ekormu!",
  ui_story_5075_50750701_67_dialog_content = "Aku tidak membicarakanmu, PlayerName.",
  ui_story_5075_50750701_68_dialog_content = "Ups, pihak yang bersalah.",
  ui_story_5075_50750701_69_dialog_content = "Jarang sekali saya melihat Aurorian dengan warisan ikan ular, jadi saya tidak bisa menahan diri.",
  ui_story_5075_50750701_70_dialog_content = "Mengingat teori bahwa ikan ular dan naga adalah kerabat jauh, kita sebenarnya agak berhubungan.",
  ui_story_5075_50750701_71_dialog_content = "Itu kehormatan saya.",
  ui_story_5075_50750701_72_dialog_content = "Tidak heran jika aku merasa ikan-ikan itu terlihat familiar. Mereka mengingatkanku pada kamu, Yuebai.",
  ui_story_5075_50750701_73_dialog_content = "Dan setelah melihat lebih dekat, perahu ini tampak persis seperti Shadowind!",
  ui_story_5075_50750701_74_dialog_content = "Itu karena ini adalah versi awal dari itu.",
  ui_story_5075_50750701_75_dialog_content = "Ini juga merupakan kapal pertama dari Keluarga Lin yang menyeberangi laut dan mencapai Astra beberapa tahun yang lalu.",
  ui_story_5075_50750701_76_dialog_content = "Saya mengerti. Tapi apa yang dilakukan patung kapal Keluarga Lin di sini?",
  ui_story_5075_50750701_77_dialog_content = "Tidak tahu?",
  ui_story_5075_50750701_78_dialog_content = "Jalan belanja ini dulunya milik Keluarga Lin.",
  ui_story_5075_50750701_79_dialog_content = "Se-Seluruh jalannya?",
  ui_story_5075_50750701_80_dialog_content = "Sayangnya, karena sejumlah kesepakatan terbaru serta insiden terakhir Lin Family, sebagian besar jalan telah terbagi-bagi.",
  ui_story_5075_50750701_81_dialog_content = "Saat ini, hanya setengah dari jalan tersebut masih berada di bawah nama Lin Family.",
  ui_story_5075_50750701_82_dialog_content = "Untuk takdir akhir dari setengah yang tersisa ini, semuanya tergantung pada bagaimana perkembangan selanjutnya.",
  ui_story_5075_50750701_83_dialog_content = "Setengah dari seluruh jalan itu masih cukup mengesankan, tahu.",
  ui_story_5075_50750701_84_dialog_content = "Ciit!",
  ui_story_5075_50750701_85_dialog_content = "Aduh!",
  ui_story_5075_50750701_86_dialog_content = "<color=#e8d9bb>Saat kamu tiba-tiba ditumbangkan oleh fiendling yang melompat, Darkflow yang hitam pekat menghantam tanah tepat di samping kakimu.</color>",
  ui_story_5075_50750701_87_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50750701_88_dialog_content = "PlayerName! Apa kamu baik-baik saja?",
  ui_story_5075_50750701_89_dialog_content = "Aku baik-baik saja. Makhluk kecil itu baru saja menyelamatkanku.",
  ui_story_5075_50750701_90_dialog_content = "Mencicit...",
  ui_story_5075_50750701_91_dialog_content = "Apa yang salah dengannya? Sepertinya dia sangat kesakitan.",
  ui_story_5075_50750701_92_dialog_content = "... Tunggu, kapan itu terinfeksi kabut hitam lagi?",
  ui_story_5075_50750701_93_dialog_content = "Ah Ding?",
  ui_story_5075_50750701_94_dialog_content = "Aum...",
  ui_story_5075_50750701_95_dialog_content = "<color=#e8d9bb>Ah Ding mengeluarkan erangan rendah yang menyakitkan, dan Lumina yang sebelumnya stabil di sekelilingnya mulai berfluktuasi.</color>",
  ui_story_5075_50750701_96_dialog_content = "Jangan bilang gejala-gejala ini adalah...",
  ui_story_5075_50750701_97_dialog_content = "Force Boost!",
  ui_story_5075_50750701_98_dialog_content = "Saya berhasil mengisolasi kekuatan merusak kabut untuk saat ini, tetapi kita perlu menemukan sumbernya secepat mungkin.",
  ui_story_5075_50750701_99_dialog_content = "Dari mana asal awan hitam raksasa ini?",
  ui_story_5075_50750701_100_dialog_content = "Aku mencari orang yang memecahkan segel, bukan kamu. Tenang dan jangan mudah dibohongi.",
  ui_story_5075_50750701_101_dialog_content = "Hah? Kamu sedang berbicara dengan siapa, Chen'ni?",
  ui_story_5075_50750701_102_dialog_content = "Ikan itu.",
  ui_story_5075_50750701_103_dialog_content = "Ikan... Kamu maksud patungnya?",
  ui_story_5075_50750701_104_dialog_content = "Pemindaian Psikis!",
  ui_story_5075_50750701_105_dialog_content = "Apakah ini di bawah laut?",
  ui_story_5075_50750701_106_dialog_content = "Siapa. Yang. Pergi. Kesana.",
  ui_story_5075_50750701_107_dialog_content = "Ekor ikan ular?",
  ui_story_5075_50750701_108_dialog_content = "Apakah Anda memiliki hubungan dengan Keluarga Lin?",
  ui_story_5075_50750701_109_dialog_content = "Lins.",
  ui_story_5075_50750701_110_dialog_content = "Menjijikkan.",
  ui_story_5075_50750701_111_dialog_content = "De—dapat diuji!",
  ui_story_5075_50750701_112_dialog_content = "!",
  ui_story_5075_50750701_113_dialog_content = "Sakit...",
  ui_story_5075_50750701_114_dialog_content = "Tetap kuat, PlayerName.",
  ui_story_5075_50750701_115_dialog_content = "Aku baik-baik saja. Kekuatan korupsi kabut hitam jauh lebih kuat di tempat yang aku rasakan.",
  ui_story_5075_50750701_116_dialog_content = "Saya melihat seseorang di sana juga. Dia tampak seperti... dia somehow terhubung dengan Keluarga Lin.",
  ui_story_5075_50750701_117_dialog_content = "Ini Yoh.",
  ui_story_5075_50750701_118_dialog_content = "Kamu kenal dia, Yuebai?",
  ui_story_5075_50750701_119_dialog_content = "Yoh adalah seorang teman yang dulunya adalah sekutu dari Lin Family.",
  ui_story_5075_50750701_120_dialog_content = "Tidak lama yang lalu, ketua guild mengirimnya dalam sebuah misi ke tepi laut. Dia sedang menyelidiki alasan di balik gerakan aneh dari roh jahat, tetapi dia tidak pernah kembali.",
  ui_story_5075_50750701_121_dialog_content = "... Dia pasti telah menjadi \"wadah fisik\" yang disebutkan Chen'ni sebelumnya! Sepertinya skenario terburuk memang terjadi.",
  ui_story_5075_50750701_122_dialog_content = "Kekuatan yang telah disegel telah menemukan tuan baru.",
  ui_story_5075_50750701_123_dialog_content = "Ciit!",
  ui_story_5075_50750701_124_dialog_content = "<color=#e8d9bb>Si kecil iblis tiba-tiba melompat keluar dan menggigit keras pergelangan tangan orang asing di sudut.</color>",
  ui_story_5075_50750701_125_dialog_content = "Argh... Makhluk sialan!",
  ui_story_5075_50750701_126_dialog_content = "Enyah!",
  ui_story_5075_50750701_127_dialog_content = "<color=#e8d9bb>Makhluk kecil itu dilempar dengan keras ke samping, meluncur jauh di tanah, tak bergerak.</color>",
  ui_story_5075_50750701_128_dialog_content = "Oh, tidak!",
  ui_story_5075_50750701_129_dialog_content = "Huh.",
  ui_story_5075_50750701_130_dialog_content = "Orang itu... Tubuhnya juga ditutupi kabut hitam! Apa yang dia genggam di tangannya?",
  ui_story_5075_50750701_131_dialog_content = "Siapa kamu!",
  ui_story_5075_50750701_132_dialog_content = "Kau tak perlu tahu.",
  ui_story_5075_50750701_133_dialog_content = "Ini tidak baik! Seseorang hentikan dia!",
  ui_story_5075_50750701_134_dialog_content = "Sudah terlambat!",
  ui_story_5075_50750701_135_dialog_content = "<color=#e8d9bb>Orang asing itu menghancurkan benda yang dipegangnya ke tanah dan melepaskan kabut hitam yang besar.</color>",
  ui_story_5075_50750701_136_dialog_content = "!(Ini sama seperti kekuatan yang aku rasakan di lautan!)",
  ui_story_5075_50750701_137_dialog_content = "<color=#e8d9bb>Kali ini, kamu bisa melihatnya bahkan tanpa mencoba menggunakan kemampuan psikismu.</color>",
  ui_story_5075_50750701_138_dialog_content = "<color=#e8d9bb>Kali ini, kamu bisa melihatnya bahkan tanpa mencoba menggunakan kemampuan psikismu.</color>",
  ui_story_5075_50750701_139_dialog_content = "<color=#e8d9bb>Kabut hitam yang tak berujung membawa Darkflow yang sangat pekat, mendidih dan bergolak seperti air yang dipanaskan.</color>",
  ui_story_5075_50750701_140_dialog_content = "<color=#e8d9bb>Semua aliran energi yang tidak stabil itu bertemu menjadi satu, dan kemudian...</color>",
  ui_story_5075_50750701_141_dialog_content = "<color=#e8d9bb>Mereka tiba-tiba meledak!</color>",
  ui_story_5075_50750701_142_dialog_content = "Tidak, kau tidak!",
  ui_story_5075_50750701_143_dialog_content = "<color=#e8d9bb>Duarr...</color>",
  ui_story_5075_50750701_144_dialog_content = "<color=#e8d9bb>Sebuah sosok emas melompat keluar dengan petir dan menghalau gelombang gelap dari ledakan, namun kabut yang tersisa masih menyebar.</color>",
  ui_story_5075_50750701_145_dialog_content = "Kalian yang telah memecahkan segel? Ayo, bayar untuk kesalahanmu!",
  ui_story_5075_50750701_146_dialog_content = "*Batuk*",
  ui_story_5075_50750701_147_dialog_content = "Apa yang terjadi? Dimana Chen'ni?",
  ui_story_5075_50750701_148_dialog_content = "Setelah kami menabrak kabut hitam, dia langsung mengejarnya.",
  ui_story_5075_50750701_149_dialog_content = "Itu sangat ceroboh!",
  ui_story_5075_50750701_150_dialog_content = "Syukurlah, saya rasa tidak ada yang benar-benar bisa menyakitinya.",
  ui_story_5075_50750701_151_dialog_content = "Tapi kami sama sekali tidak seperti dia. Sepertinya tidak ada satupun dari kita yang terluka.",
  ui_story_5075_50750701_152_dialog_content = "Kami tidak terluka... Tapi Ah Ding dan anak kecil lainnya terluka!",
  ui_story_5075_50750701_153_dialog_content = "Aum...",
  ui_story_5075_50750701_154_dialog_content = "Ledakan barusan itu menyebabkan kabut hitam terbang ke segala arah. Korupsi mereka tampaknya juga semakin meningkat.",
  ui_story_5075_50750701_155_dialog_content = "Tidak hanya itu, tampaknya kabut juga menarik Eclipsites.",
  ui_story_5075_50750701_156_dialog_content = "Bersiaplah untuk bertempur.",
  ui_story_5075_50750701_157_dialog_content = "Graah!",
  ui_story_5075_50750702_1_dialog_content = "Aku tidak akan membiarkan roh jahat kalian mencemarkan tempat leluhur Keluarga Lin!",
  ui_story_5075_50750702_2_dialog_content = "Graah—",
  ui_story_5075_50750702_3_dialog_content = "Baguslah kamu di sini untuk membersihkan Eclipsite ini, Yuebai.",
  ui_story_5075_50750702_4_dialog_content = "Tapi kabut tampaknya telah menyebar ke seluruh kota. Aku khawatir sesuatu yang benar-benar buruk akan segera terjadi.",
  ui_story_5075_50750702_5_dialog_content = "Apakah tidak ada yang bisa kita lakukan untuk itu?",
  ui_story_5075_50750702_6_dialog_content = "Ada.",
  ui_story_5075_50750702_7_dialog_content = "Situasi mungkin jauh lebih buruk dari sebelumnya, tetapi Lin Family masih memiliki rencana darurat.",
  ui_story_5075_50750702_8_dialog_content = "Saya akan bertanggung jawab untuk mengawal semua orang dengan selamat ke perkebunan Keluarga Lin.",
  ui_story_5075_50750702_9_dialog_content = "Setelah itu, saya akan meyakinkan guildmaster untuk mengalokasikan sumber dayanya di kota untuk membantu dalam masalah ini.",
  ui_story_5075_50750702_10_dialog_content = "Terlihat baik bagiku! Tapi bukankah kamu penasaran untuk tahu apa yang terjadi sebelum membantu kami, Yuebai?",
  ui_story_5075_50750702_11_dialog_content = "Masalah ini erat kaitannya dengan Keluarga Lin...",
  ui_story_5075_50750702_12_dialog_content = "Selain itu, aku tidak perlu alasan untuk membantu teman seperti kamu.",
  ui_story_5075_50750702_13_dialog_content = "Tunggu, PlayerName.",
  ui_story_5075_50750702_14_dialog_content = "Apa itu, Luo Song?",
  ui_story_5075_50750702_15_dialog_content = "Bisakah saya meninggalkan si kecil nakal ini dalam asuhanmu untuk saat ini?",
  ui_story_5075_50750702_16_dialog_content = "Tentu saja. Jangan lupa Ah Ding juga.",
  ui_story_5075_50750702_17_dialog_content = "Chen'ni masih belum kembali, jadi yang bisa kulakukan adalah mencoba mengisolasi kerusakan kabut hitam.",
  ui_story_5075_50750702_18_dialog_content = "Aum...",
  ui_story_5075_50750702_19_dialog_content = "Ah Ding?",
  ui_story_5075_50750702_20_dialog_content = "Ini adalah tempat kita berpisah.",
  ui_story_5075_50750702_21_dialog_content = "Kamu juga, Luo Song?",
  ui_story_5075_50750702_22_dialog_content = "Dengan kabut hitam yang menyebar di seluruh Haojin, pasti akan ada lebih banyak makhluk jahat yang terinfeksi.",
  ui_story_5075_50750702_23_dialog_content = "Mereka tidak buruk, mereka hanya mengikuti insting mereka. Bagaimanapun, mereka masih roh hewan yang lahir dari alam liar.",
  ui_story_5075_50750702_24_dialog_content = "Sebagaimana adanya, pendapat orang terhadap fiendlings semakin memburuk.",
  ui_story_5075_50750702_25_dialog_content = "Jika ada yang terluka oleh fiendling akibat infeksi kabut hitam, saya khawatir hubungan antara kita akan tidak dapat diperbaiki.",
  ui_story_5075_50750702_26_dialog_content = "Itulah sebabnya saya perlu menaklukkan fiendlings yang terinfeksi sebelum terlambat.",
  ui_story_5075_50750702_27_dialog_content = "Memang benar bahwa kita pernah memiliki perbedaan dengan fiendlings.",
  ui_story_5075_50750702_28_dialog_content = "Tapi itu tidak memberi siapa pun hak untuk menentukan tempat mereka di dunia ini atau takdir mereka, dalam hal ini.",
  ui_story_5075_50750702_29_dialog_content = "Bukankah begitu, Ah Ding?",
  ui_story_5075_50750702_30_dialog_content = "Aku memuji kamu saat kamu berbuat baik, dan aku menegur kamu saat kamu berbuat buruk.",
  ui_story_5075_50750702_31_dialog_content = "Tapi pada akhirnya, pilihan untuk melakukan salah satu itu selalu milikmu sendiri.",
  ui_story_5075_50750702_32_dialog_content = "Apakah kamu ingin ikut denganku?",
  ui_story_5075_50750702_33_dialog_content = "<color=#e8d9bb>Luo Song membungkuk, menatap Ah Ding.</color>",
  ui_story_5075_50750702_34_dialog_content = "<color=#e8d9bb>Ah Ding, tergeletak dengan wajah di tanah, merangkak bangkit dan berjalan terhuyung-huyung.</color>",
  ui_story_5075_50750702_35_dialog_content = "Groar!",
  ui_story_5075_50750702_36_dialog_content = "Itulah pasanganku untukmu.",
  ui_story_5075_50750702_37_dialog_content = "Tapi Ah Ding tidak dalam kondisi untuk...",
  ui_story_5075_50750702_38_dialog_content = "Argh, andai saja Dragon Maiden ada di sini.",
  ui_story_5075_50750702_39_dialog_content = "Permintaanmu sedikit berlebihan, bukan begitu?",
  ui_story_5075_50750702_40_dialog_content = "Dewa tidak akan muncul di depan kita hanya karena kita meminta, tahu?",
  ui_story_5075_50750702_41_dialog_content = "Keluargamu akan memarahi kamu karena selalu meminta bantuan, dan dewa pun tidak berbeda.",
  ui_story_5075_50750702_42_dialog_content = "Ya, kau benar.",
  ui_story_5075_50750702_43_dialog_content = "Untuk mengatakan yang sebenarnya, ibadah dan doa tidak lebih dari sekedar angan-angan.",
  ui_story_5075_50750702_44_dialog_content = "Jika dewa memilih untuk turun tangan, itu karena mereka memiliki alasan mereka sendiri untuk melakukannya.",
  ui_story_5075_50750702_45_dialog_content = "Tapi di dunia fana ini, tinju kita adalah metode paling andal untuk mencapai tujuan kita!",
  ui_story_5075_50750702_46_dialog_content = "Tidak peduli seberapa keras jalannya, kita selalu bisa maju selama kita masih memiliki kekuatan di tinju kita.",
  ui_story_5075_50750702_47_dialog_content = "Groar!",
  ui_story_5075_50750702_48_dialog_content = "Saatnya kita pergi!",
  ui_story_5075_50750702_49_dialog_content = "Semoga berhasil, kalian berdua.",
  ui_story_5075_50750702_50_dialog_content = "Kita juga harus pergi.",
  ui_story_5075_50750702_51_dialog_content = "Ayo, saya akan membawa kamu ke kediaman Keluarga Lin.",
  ui_story_5075_50750801_1_dialog_content = "<color=#e8d9bb>Istana Kerajaan Ji</color>",
  ui_story_5075_50750801_2_dialog_content = "Lord, ada kabar lagi dari Kerajaan Ye.",
  ui_story_5075_50750801_3_dialog_content = "Mengenai <color=#FFB400>meriam pantai</color> yang kita pesan dari Kerajaan Ye? Sudah sampai belum?",
  ui_story_5075_50750801_4_dialog_content = "Tidak... belum...",
  ui_story_5075_50750801_5_dialog_content = "Tidak? Bukankah mereka mulai mengirim setelah menaikkan harga terakhir kali?",
  ui_story_5075_50750801_6_dialog_content = "Pesan Kerajaan Ye mengatakan itu.",
  ui_story_5075_50750801_7_dialog_content = "Tapi sudah setengah bulan, dan barang-barang masih belum tiba. Kami telah mengirim surat untuk mendesak mereka, tapi di pihak mereka...",
  ui_story_5075_50750801_8_dialog_content = "Biarkan saya menebak, mereka menaikkan harga lagi?",
  ui_story_5075_50750801_9_dialog_content = "... Iya.",
  ui_story_5075_50750801_10_dialog_content = "Surat itu mengatakan tim pengiriman hilang di pegunungan.",
  ui_story_5075_50750801_11_dialog_content = "Dan mengingat mereka adalah sesuatu yang sangat dibutuhkan oleh Kerajaan Ji kita, mereka bisa menyisihkan beberapa tangan untuk membantu kita mencari.",
  ui_story_5075_50750801_12_dialog_content = "Tapi kita perlu menanggung biaya dari pencarian tersebut.",
  ui_story_5075_50750801_13_dialog_content = "Tentu saja, mereka mengusulkan bahwa biaya ini dapat dikompensasikan dengan pinjaman yang dipinjam oleh Kerajaan Ye dari kita lima tahun lalu.",
  ui_story_5075_50750801_14_dialog_content = "Jadi, saya pikir mereka hanya menggunakan ini sebagai alasan untuk menaikkan harga.",
  ui_story_5075_50750801_15_dialog_content = "Jika kita tidak setuju untuk membayar, mereka akan terus mengklaim bahwa meriam pantai hilang.",
  ui_story_5075_50750801_16_dialog_content = "Dan pencarian mungkin akan berlanjut... selamanya.",
  ui_story_5075_50750801_17_dialog_content = "Konyol!",
  ui_story_5075_50750801_18_dialog_content = "Kami memesan segera setelah roh jahat mulai berulah, tetapi terus menerus tertunda.",
  ui_story_5075_50750801_19_dialog_content = "Kali ini tim pengiriman yang menghilang. Alasan apa lagi yang akan mereka berikan selanjutnya? Meriam yang misterius menghilang begitu saja?",
  ui_story_5075_50750801_20_dialog_content = "Dalam balasannya, jelaskan bahwa jika mereka mencoba memanfaatkan situasi, semua transaksi antara kerajaan kita akan dibatalkan!",
  ui_story_5075_50750801_21_dialog_content = "Tapi, Tuan saya, roh-roh jahat telah bergentayangan lebih liar di mana-mana akhir-akhir ini.",
  ui_story_5075_50750801_22_dialog_content = "Terutama di sepanjang pantai, semua wilayah mengharapkan dukungan dari istana.",
  ui_story_5075_50750801_23_dialog_content = "Jika meriam pesisir Kerajaan Ye tidak segera tiba, mungkin akan sulit untuk mempertahankan garis pertahanan lebih lama.",
  ui_story_5075_50750801_24_dialog_content = "Sulit untuk mempertahankan garis pertahanan?",
  ui_story_5075_50750801_25_dialog_content = "Apakah Kerajaan Ye adalah satu-satunya pemasok yang tersisa di Longzhou?",
  ui_story_5075_50750801_26_dialog_content = "Kerajaan Ji kita makmur dengan barang-barang melimpah serta kumpulan pedagang, dan keuntungan harian yang tak terukur.",
  ui_story_5075_50750801_27_dialog_content = "Jika pengiriman melalui laut menjadi tantangan sekarang, kita mungkin beralih ke transportasi sungai. Karena Kerajaan Ye menolak perdagangan yang adil, kita akan mencari orang lain.",
  ui_story_5075_50750801_28_dialog_content = "Uang membuat segalanya menjadi mungkin. Selama harganya tepat, bahkan kekuatan besar Yangjing akan berada di bawah perintahku.",
  ui_story_5075_50750801_29_dialog_content = "Bagaimana dengan tuntutan Kerajaan Ye?",
  ui_story_5075_50750801_30_dialog_content = "Tolak mereka semua.",
  ui_story_5075_50750801_31_dialog_content = "Ya, Lord.",
  ui_story_5075_50750801_32_dialog_content = "Humph, sekarang bahkan Kerajaan Ye berani bermain-main denganku.",
  ui_story_5075_50750801_33_dialog_content = "Mereka mungkin telah dengan mudah melupakan rasa malu ketika mereka meminta pinjaman dari Kerajaan Ji kami beberapa tahun lalu.",
  ui_story_5075_50750801_34_dialog_content = "Berbicara tentang itu, tahun itu juga ketika Zhuohua datang ke Kerajaan Ji.",
  ui_story_5075_50750801_35_dialog_content = "Kepala Penasihat, apa pendapat Anda? Jika Zhuohua benar-benar menjadi menantu perempuan saya, mungkin uang itu bisa dinegosiasikan.",
  ui_story_5075_50750801_36_dialog_content = "Tuan saya, jangan bercanda. Zhuohua adalah wanita yang berambisi dan bertekad. Masalah ini bukanlah lelucon.",
  ui_story_5075_50750801_37_dialog_content = "Huh, saya sangat menyadari itu.",
  ui_story_5075_50750801_38_dialog_content = "Sangat jarang menemukan seseorang yang bisa menjaga putra mahkota sebaik itu...",
  ui_story_5075_50750801_39_dialog_content = "Mari kita tidak terpaku pada masalah sepele anak-anak. Tuanku, apakah Anda telah mempertimbangkan strategi untuk situasi yang sedang kacau saat ini?",
  ui_story_5075_50750801_40_dialog_content = "Selama bertahun-tahun, Kerajaan Ji kami telah menempatkan penekanan berat pada perdagangan. Kebutuhan seperti makanan dan mesin semuanya bergantung pada perdagangan dengan kerajaan lain.",
  ui_story_5075_50750801_41_dialog_content = "Jika ada lebih banyak situasi seperti insiden hari ini dengan Kerajaan Ye...",
  ui_story_5075_50750801_42_dialog_content = "Kerajaan Ji telah berpusat pada perdagangan selama berabad-abad. Menciptakan strategi baru bukanlah hal yang mudah.",
  ui_story_5075_50750801_43_dialog_content = "Selain itu, ancaman dari roh jahat mungkin tidak akan bertahan lama.",
  ui_story_5075_50750801_44_dialog_content = "Mari kita bicarakan ini di hari lain.",
  ui_story_5075_50750801_45_dialog_content = "Aku lelah. Aku akan kembali untuk beristirahat sekarang.",
  ui_story_5075_50750801_46_dialog_content = "... Baiklah.",
  ui_story_5075_50750801_47_dialog_content = "Pak? Anda di sini.",
  ui_story_5075_50750801_48_dialog_content = "Aku mendengar roh-roh jahat di teluk telah bertambah kuat, dan kasus fiendling masih menjadi misteri.",
  ui_story_5075_50750801_49_dialog_content = "Juga, setelah berpisah di istana, saya belum mendengar kabar dari PlayerName sejak itu!",
  ui_story_5075_50750801_50_dialog_content = "Apa wawasan yang bisa Anda berikan kepada saya, Pak?",
  ui_story_5075_50750801_51_dialog_content = "Jangan khawatir. Anak muda itu aman dan sehat, dan tugas yang diberikan kepadanya berjalan dengan baik.",
  ui_story_5075_50750801_52_dialog_content = "Tapi, saya rasa ada lebih banyak hal yang ingin kamu tanyakan, benar?",
  ui_story_5075_50750801_53_dialog_content = "Saya tidak akan berbasa-basi dan akan langsung jujur dengan Anda.",
  ui_story_5075_50750801_54_dialog_content = "Anda menyarankan PlayerName untuk tetap sembunyi dan tidak memberi tahu siapa pun di pengadilan.",
  ui_story_5075_50750801_55_dialog_content = "Apakah itu karena Anda mencurigai adanya permainan kotor atau niat jahat?",
  ui_story_5075_50750801_56_dialog_content = "Untuk pertanyaan Anda, alih-alih bertanya kepada saya, mengapa tidak mengecek dengan penjaga Anda?",
  ui_story_5075_50750801_57_dialog_content = "<color=#FFB400>Jiu</color>? Dia ada di...",
  ui_story_5075_50750801_58_dialog_content = "Tidak perlu memberitahuku. Saya seorang pria tua, dan saya tidak bisa memahami permainan kalian gadis-gadis muda.",
  ui_story_5075_50750801_59_dialog_content = "Sana, lihatlah sendiri.",
  ui_story_5075_50750801_60_dialog_content = "... Begitu ya. Terima kasih atas penjelasannya.",
  ui_story_5075_50750801_61_dialog_content = "Oh, satu hal lagi. Izinkan saya untuk meminta maaf kepada Anda.",
  ui_story_5075_50750801_62_dialog_content = "Ketika kamu melihat anak muda nanti, tolong sampaikan permintaan maafku kepadanya juga.",
  ui_story_5075_50750801_63_dialog_content = "Sebelumnya, aku memberikan sesuatu kepada anak itu atas namamu.",
  ui_story_5075_50750801_64_dialog_content = "Saya harap ini terbukti berguna pada waktunya.",
  ui_story_5075_50750801_65_dialog_content = "(Dia memang sangat berhati-hati terhadap seseorang di pengadilan.)",
  ui_story_5075_50750801_66_dialog_content = "(Tapi siapa yang bisa membuat dia begitu waspada?)",
  ui_story_5075_50750801_67_dialog_content = "(Aku penasaran, apakah ini ada hubungannya dengan kasus yang sedang diselidiki oleh Jiu...)",
  ui_story_5075_50750801_68_dialog_content = "(Berbicara tentang itu, kenapa istana diam tentang spionase di kota?)",
  ui_story_5075_50750801_69_dialog_content = "(Hanya Jiu yang berhasil mengungkapnya? Atau, apakah seseorang sengaja membiarkannya mengungkapnya?)",
  ui_story_5075_50750801_70_dialog_content = "(Tapi dia hanya pengawal untuk tuan putri sandera, dan dia hanya melakukannya untukku.)",
  ui_story_5075_50750801_71_dialog_content = "(Tidak perlu bagi siapa pun di pengadilan untuk melakukan ini meskipun mereka memiliki motif tersembunyi, kecuali...)",
  ui_story_5075_50750801_72_dialog_content = "(Otak di balik komplotan ini bukanlah bekerja untuk Kerajaan Ji tapi...)",
  ui_story_5075_50750801_73_dialog_content = "Bip.",
  ui_story_5075_50750801_74_dialog_content = "Seekor burung pengantar dari <color=#FFB400>Ministress Armilla</color>?",
  ui_story_5075_50750801_75_dialog_content = "Dia mengatakan bahwa mereka tidak bekerja cukup baik untuk menghindari pengawal sebagai alasan dia tidak pernah mengirimkan apa pun kepada saya.",
  ui_story_5075_50750801_76_dialog_content = "Aku tahu itu hanya alasan.",
  ui_story_5075_50750801_77_dialog_content = "...",
  ui_story_5075_50750801_78_dialog_content = "Betapa beraninya kamu, Xuan Ji!",
  ui_story_5075_50750801_79_dialog_content = "Aku harus meninggalkan istana sekarang.",
  ui_story_5075_50750801_80_dialog_content = "Kepala Penasihat, sesuai instruksi Anda, kami telah menghapus penjaga dari sekitarnya.",
  ui_story_5075_50750801_81_dialog_content = "Putri Zhuohua juga telah menerima surat tersebut.",
  ui_story_5075_50750801_82_dialog_content = "Bagus.",
  ui_story_5075_50750902_1_dialog_content = "Ini dia. Selamat datang di perkebunan Yulin Street milik Keluarga Lin.",
  ui_story_5075_50750902_2_dialog_content = "Hah? Bukankah ini alamat yang sama yang tertulis di catatan itu?",
  ui_story_5075_50750902_3_dialog_content = "Catatan?",
  ui_story_5075_50750902_4_dialog_content = "Saya menerima kotak makanan dari istana lebih awal hari ini, dan di dalamnya terdapat peta kecil dengan alamat ini ditandai di atasnya.",
  ui_story_5075_50750902_5_dialog_content = "Ini juga datang dengan lambang ini, tetapi saya tidak yakin apa yang harus saya lakukan dengannya.",
  ui_story_5075_50750902_6_dialog_content = "Ini... adalah lambang dari Kantor Inspeksi.",
  ui_story_5075_50750902_7_dialog_content = "Anak muda, tahukah kamu bahwa selain angkatan laut, Kerajaan Ji tidak memiliki pasukan tetap di darat?",
  ui_story_5075_50750902_8_dialog_content = "Menjaga rute vital, menyelidiki pengkhianatan, dan membasmi roh jahat—semua menjadi tanggung jawab Kantor Inspeksi.",
  ui_story_5075_50750902_9_dialog_content = "Dan lencana di tanganmu memungkinkan kamu untuk memobilisasi pasukan Kantor Inspeksi.",
  ui_story_5075_50750902_10_dialog_content = "Selain dari penjaga istana kerajaan, apa yang kamu pegang adalah komando dari pasukan terkuat di Haojin.",
  ui_story_5075_50750902_11_dialog_content = "Maksudmu selama ini aku telah membawa sesuatu yang sepenting itu?",
  ui_story_5075_50750902_12_dialog_content = "Hah? Tunggu, kamu siapa?",
  ui_story_5075_50750902_13_dialog_content = "Guildmaster, Anda tidak perlu keluar dan menyambut kami.",
  ui_story_5075_50750902_14_dialog_content = "Mendengar ada keributan di luar, jadi saya keluar untuk melihat apa yang terjadi.",
  ui_story_5075_50750902_15_dialog_content = "Aku tidak menyangka kamu memiliki tamu.",
  ui_story_5075_50750902_16_dialog_content = "Kamu pasti PlayerName, 'kan?",
  ui_story_5075_50750902_17_dialog_content = "Sering kali aku mendengar namamu dari Zhong Xu, Liqing, dan Yuebai. Sungguh keberuntunganku bisa bertemu denganmu hari ini.",
  ui_story_5075_50750902_18_dialog_content = "Tapi sekarang bukan waktunya untuk basa-basi.",
  ui_story_5075_50750902_19_dialog_content = "Anak muda, bisakah kamu katakan kenapa kamu terlihat sangat terkejut saat melihatku?",
  ui_story_5075_50750902_20_dialog_content = "Ah, maaf soal itu. Tapi, aku merasa seperti pernah melihatmu di suatu tempat sebelumnya.",
  ui_story_5075_50750902_21_dialog_content = "Kupikir itu ada di dasar samudra... dalam kenangan dari makhluk jahat yang mengendalikan kabut hitam.",
  ui_story_5075_50750902_22_dialog_content = "Apakah ini Yoh?",
  ui_story_5075_50750902_23_dialog_content = "Kurasa begitu.",
  ui_story_5075_50750902_24_dialog_content = "Jadi kamu tahu tentang Yoh dan dendamnya terhadap keluarga Lin. Apa sebenarnya yang terjadi di antara kalian?",
  ui_story_5075_50750902_25_dialog_content = "Itu cerita panjang.",
  ui_story_5075_50750902_26_dialog_content = "Mari kita bicara di dalam.",
  ui_story_5075_50750902_27_dialog_content = "Aku punya beberapa urusan yang harus diurus. Yuebai, tolong hibur tamu kita untuk sementara.",
  ui_story_5075_50750902_28_dialog_content = "Baiklah.",
  ui_story_5075_50750902_29_dialog_content = "Ingin minum teh?",
  ui_story_5075_50750902_30_dialog_content = "Oh, tidak, terima kasih.",
  ui_story_5075_50750902_31_dialog_content = "Mengerti. Mungkin lain kali.",
  ui_story_5075_50750902_32_dialog_content = "Hahaha... Hampir saja aku lupa dengan cara biasa kamu melakukan sesuatu.",
  ui_story_5075_50750902_33_dialog_content = "?",
  ui_story_5075_50750902_34_dialog_content = "Bukan apa-apa. Saya hanya berpikir kita tidak perlu formalitas yang kaku lagi.",
  ui_story_5075_50750902_35_dialog_content = "Mari kita langsung ke intinya. Apa cerita di antara Yoh dan keluarga Lin?",
  ui_story_5075_50750902_36_dialog_content = "Tahu tidak, sejarah bersama antara Keluarga Lin dan para fiendling berawal jauh di masa lalu.",
  ui_story_5075_50750902_37_dialog_content = "Pada saat itu, Keluarga Lin hanyalah sebuah guild kecil, yang berada di ambang kebangkrutan karena bertahun-tahun bisnis yang buruk.",
  ui_story_5075_50750902_38_dialog_content = "Dalam tindakan terakhir yang penuh keputusasaan, guildmaster menukarkan kekayaan keluarga yang tersisa dengan kapal pedagang, dengan harapan menemukan cara yang lebih baik untuk bertahan di laut.",
  ui_story_5075_50750902_39_dialog_content = "Tak perlu dikatakan, dia berhasil.",
  ui_story_5075_50750902_40_dialog_content = "Itulah awal dari hubungan bisnis Keluarga Lin dengan Astra.",
  ui_story_5075_50750902_41_dialog_content = "Saya ingat Carleen menceritakan kisah ini kepada saya. Twin Pavilions Bay juga mulai berkembang pada saat itu.",
  ui_story_5075_50750902_42_dialog_content = "Lalu, sepertinya kau sudah tahu sisanya.",
  ui_story_5075_50750902_43_dialog_content = "Namun, yang lebih penting untuk situasi kita saat ini adalah apa yang terjadi setelahnya. Dalam perjalanan pulangnya ke Longzhou, kapal guildmaster secara tidak sengaja berlayar ke perairan yang tenang.",
  ui_story_5075_50750902_44_dialog_content = "Pada saat itu, Keluarga Lin tidak memiliki armillary spheres, dan mereka juga tidak memiliki pengrajin terampil seperti Xuan Ji untuk menyelamatkan mereka.",
  ui_story_5075_50750902_45_dialog_content = "Gilde master dan krunya menghabiskan dua minggu mengapung tanpa arah di laut, dan mereka hampir kehabisan stok makanan mereka.",
  ui_story_5075_50750902_46_dialog_content = "Itu adalah saat mereka bertemu dengan sekolah ikan ular.",
  ui_story_5075_50750902_47_dialog_content = "Chen'ni mengatakan bahwa ikan ular kembali ke Longzhou dalam kelompok besar setiap musim dingin untuk bertelur.",
  ui_story_5075_50750902_48_dialog_content = "Jadi ikan ular menyelamatkan ketua guild?",
  ui_story_5075_50750902_49_dialog_content = "Tepat sekali.",
  ui_story_5075_50750902_50_dialog_content = "Mereka mengikuti sekolah ikan ular, yang mereka anggap sebagai pertanda baik, dan itu membawa mereka keluar dari perairan yang tenang dan kembali ke pantai Longzhou.",
  ui_story_5075_50750902_51_dialog_content = "Untuk alasan itu, dia hanya menyewa perjalanan pulang dari Astra di bulan-bulan musim dingin.",
  ui_story_5075_50750902_52_dialog_content = "Sebagai imbalan atas persembahan makanan yang melimpah, serpentfish membimbing kapal-kapal Keluarga Lin dengan aman melintasi laut.",
  ui_story_5075_50750902_53_dialog_content = "Dan begitu ikan ular menjadi semacam totem bagi Keluarga Lin.",
  ui_story_5075_50750902_54_dialog_content = "Ini juga adalah nama yang menjadi ciri khas dari seluruh jalan ini.",
  ui_story_5075_50750902_55_dialog_content = "Namun, setelah kematian guildmaster sebelumnya, Lin Guild hanya bertambah skala dengan setiap generasi yang berlalu.",
  ui_story_5075_50750902_56_dialog_content = "Segera, tuntutan guild yang semakin meningkat tidak bisa dipenuhi hanya dengan satu perjalanan pulang di musim dingin.",
  ui_story_5075_50750902_57_dialog_content = "Pada saat itu, ketua guild saat itu mulai meminta ikan ular untuk semakin banyak mengantar melintasi laut.",
  ui_story_5075_50750902_58_dialog_content = "Tunggu, dia bernegosiasi... dengan ikan?",
  ui_story_5075_50750902_59_dialog_content = "Meski aku berdiri tepat di depanmu, kamu masih belum menyadari juga, ya?",
  ui_story_5075_50750902_60_dialog_content = "Dulu, pemimpin ikan ular adalah seorang <color=#FFB400>fiendling</color>.",
  ui_story_5075_50750902_61_dialog_content = "Garis keturunan ikan ular Keluarga Lin juga dimulai pada saat itu.",
  ui_story_5075_50750902_62_dialog_content = "Namun dengan menuntut lebih banyak pengawalan dari serpentfish tanpa mempertimbangkan kecenderungan alamiah mereka, Keluarga Lin gagal memenuhi perjanjian asli mereka.",
  ui_story_5075_50750902_63_dialog_content = "Akibatnya, hubungan di antara mereka mulai memburuk secara bertahap.",
  ui_story_5075_50750902_64_dialog_content = "Pada satu titik, sebuah kapal Keluarga Lin bahkan menghancurkan habitat ikan ular.",
  ui_story_5075_50750902_65_dialog_content = "Insiden ini membuat pemimpin ikan ular saat ini marah, dan dia bertekad untuk sepenuhnya mengakhiri kerjasama mereka dengan Keluarga Lin.",
  ui_story_5075_50750902_66_dialog_content = "Saya masih ingat bagaimana Yoh yang baru berubah itu menerobos masuk ke halaman rumah saya dan berteriak betapa dia sangat membenci saya.",
  ui_story_5075_50750902_67_dialog_content = "Selamat kembali, Guildmaster.",
  ui_story_5075_50750902_68_dialog_content = "Maaf, kamu...",
  ui_story_5075_50750902_69_dialog_content = "Haha, aku mendengar apa yang kamu katakan barusan.",
  ui_story_5075_50750902_70_dialog_content = "Hal semacam ini pasti sulit bagi seseorang muda sepertimu untuk menerima.",
  ui_story_5075_50750902_71_dialog_content = "Aku tidak akan membela tindakan dari Keluarga Lin. Apa yang dilakukan oleh pendahulu kita memang tidak setia.",
  ui_story_5075_50750902_72_dialog_content = "Namun, sebagai seorang pengusaha, saya sangat menyadari bahwa Keluarga Lin pada akhirnya mendapatkan keuntungan dari hal itu, menjadi pemain teratas di sektor bisnis Haojin.",
  ui_story_5075_50750902_73_dialog_content = "Jika saya yang memegang kendali saat itu, saya mungkin akan melakukan hal yang sama.",
  ui_story_5075_50750902_74_dialog_content = "Jika kita tidak menerima informasi tentang bola armilari sebelumnya, keluarga Lin tidak akan melepaskannya begitu saja.",
  ui_story_5075_50750902_75_dialog_content = "Mereka mungkin telah menahannya sebagai tawanan, menggunakan dia sebagai pion.",
  ui_story_5075_50750902_76_dialog_content = "Dia membenci saya, membenci keluarga Lin, dan itu memang seharusnya.",
  ui_story_5075_50750902_77_dialog_content = "Melanggar janji dan mengkhianati kepercayaan—memang, Keluarga Lin telah melakukan perbuatan seperti itu di masa lalu.",
  ui_story_5075_50750902_78_dialog_content = "Sekarang, Keluarga Lin menuai apa yang telah mereka tabur.",
  ui_story_5075_50750902_79_dialog_content = "Roh-roh jahat berkeliaran di daerah pesisir, namun Kerajaan Ji masih belum mampu membentuk garis pertahanan yang stabil.",
  ui_story_5075_50750902_80_dialog_content = "Meriam pantai yang kami pesan dari Kerajaan Ye belum tiba, seperti yang saya dengar.",
  ui_story_5075_50750902_81_dialog_content = "Kapal dagang keluarga Lin sudah lama tidak dapat berlayar, dan bisnis pesisir menjadi stagnan. Malang tak dapat ditolak, untung tak dapat diraih.",
  ui_story_5075_50750902_82_dialog_content = "Begitu saya berhasil keluar dari Kantor Perdagangan Maritim, saya langsung menuju ke Yoh, tanpa mempedulikan pertimbangan yang lebih baik dari Zhong.",
  ui_story_5075_50750902_83_dialog_content = "Saya berharap dia bisa membantu Keluarga Lin menjelajahi rute air dan melindungi kapal dagang. Tentu saja, saya diusir.",
  ui_story_5075_50750902_84_dialog_content = "Menurut PlayerName, dia pergi untuk menyelidiki situasi di laut setelah semua...",
  ui_story_5075_50750902_85_dialog_content = "Namun kemudian dia terkorupsi oleh pengaruh naga jahat, menyebabkan dia kehilangan kendali dan menularkan dendamnya ke setiap iblis di sekitarnya.",
  ui_story_5075_50750902_86_dialog_content = "... Keluarga Lin bertanggung jawab atas insiden ini, dan tugas kami untuk memperbaikinya.",
  ui_story_5075_50750902_87_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5075_50750902_88_dialog_content = "Usir fiendlings itu!",
  ui_story_5075_50750902_89_dialog_content = "Apa yang terjadi di luar?",
  ui_story_5075_50751001_1_dialog_content = "<color=#e8d9bb>Luo Song berhadapan dengan kerumunan warga kota yang marah di tengah jalan, melindungi sejumlah fiendlings yang terbaring tak sadarkan diri di tanah.</color>",
  ui_story_5075_50751001_2_dialog_content = "Tenang, semua orang! Makhluk jahat ini sama sekali tidak bermaksud menyakiti siapa pun!",
  ui_story_5075_50751001_3_dialog_content = "Aku sudah menundukkan mereka. Yang tersisa hanyalah menghilangkan kejahatan dari tubuh mereka dan—",
  ui_story_5075_50751001_4_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5075_50751001_5_dialog_content = "<color=#e8d9bb>Sebuah batu terbang keluar dari kerumunan, mengenai Luo Song.</color>",
  ui_story_5075_50751001_6_dialog_content = "Groar!",
  ui_story_5075_50751001_7_dialog_content = "Ah Ding! Kamu juga harus tenang!",
  ui_story_5075_50751001_8_dialog_content = "Saya baik-baik saja, saya janji. Kita tidak mampu untuk berkelahi dengan mereka, tidak sekarang.",
  ui_story_5075_50751001_9_dialog_content = "Orang-orang sudah terluka. Siapa peduli mereka bermaksud atau tidak!",
  ui_story_5075_50751001_10_dialog_content = "Aku sudah bilang kalau makhluk-makhluk jahat itu tidak baik! Mencuri barang itu satu hal, tapi sekarang mereka membunuh orang!",
  ui_story_5075_50751001_11_dialog_content = "Haojin telah damai selama berabad-abad, tetapi hari ini bahkan ada roh jahat di kota!",
  ui_story_5075_50751001_12_dialog_content = "Dan kau masih berkeras bukan fiendling yang membuat masalah? Mereka jelas sama! Sama-sama jahat!",
  ui_story_5075_50751001_13_dialog_content = "Kalian orang-orang yang tahu sihir, jadi mudah bagi kalian untuk berbicara tanpa merasa takut.",
  ui_story_5075_50751001_14_dialog_content = "Kamu tidak takut pada mereka, tapi kami takut!",
  ui_story_5075_50751001_15_dialog_content = "Kita tidak bisa membiarkan hal-hal menakutkan ini tinggal di kota. Usir mereka semua!",
  ui_story_5075_50751001_16_dialog_content = "Usir mereka! USIR MEREKA!",
  ui_story_5075_50751001_17_dialog_content = "Aku harus membantunya—",
  ui_story_5075_50751001_18_dialog_content = "Tunggu. Jika kamu pergi ke sana tanpa persiapan, kamu hanya akan memperburuk keadaan.",
  ui_story_5075_50751001_19_dialog_content = "Kerumunan orang yang marah tidak akan mendengarkan alasan, tidak peduli itu benar atau salah.",
  ui_story_5075_50751001_20_dialog_content = "Selain dari penampilan kekuatan yang lebih besar, satu-satunya cara untuk menenangkan mereka adalah dengan memberikan jaminan yang tak terbantahkan bahwa segala sesuatu akan menjadi lebih baik.",
  ui_story_5075_50751001_21_dialog_content = "Saya memiliki insignia itu! Bukankah itu berarti saya bisa meminta Biro Inspeksi untuk membantu kita?",
  ui_story_5075_50751001_22_dialog_content = "Saat ini, Kantor Inspeksi seharusnya sedang menangani Eclipsites yang tersebar di seluruh kota.",
  ui_story_5075_50751001_23_dialog_content = "Lagipula, jika mereka ikut campur... Saya khawatir orang-orang ini hanya akan menjadi lebih gelisah.",
  ui_story_5075_50751001_24_dialog_content = "Tapi pasti ada sesuatu yang bisa kita lakukan...",
  ui_story_5075_50751001_25_dialog_content = "Saya sudah bilang ada, bukan? Lebih spesifik, keluarga Lin punya solusinya.",
  ui_story_5075_50751001_26_dialog_content = "Guildmaster, aku punya permintaan untukmu.",
  ui_story_5075_50751001_27_dialog_content = "Saya secara resmi meminta otoritas untuk <color=#FFB400>bertindak atas nama Lin Guildmaster</color> dari Haojin.",
  ui_story_5075_50751001_28_dialog_content = "Mohon berikan saya hak untuk mengalokasikan orang-orang dan sumber daya Keluarga Lin untuk menyelesaikan insiden ini.",
  ui_story_5075_50751001_29_dialog_content = "Apa rencanamu?",
  ui_story_5075_50751001_30_dialog_content = "Meskipun kejayaan Persekutuan Lin telah meredup dalam beberapa tahun terakhir, tetap saja kami adalah organisasi lama yang memiliki hubungan dekat dengan masyarakat.",
  ui_story_5075_50751001_31_dialog_content = "Saya ingin menawarkan janji keselamatan kepada penduduk kota ini atas nama guild dan mengirim medis kami untuk merawat yang terluka.",
  ui_story_5075_50751001_32_dialog_content = "Apakah kamu paham apa yang dipertaruhkan dengan kata-kata santai yang kamu ucapkan?",
  ui_story_5075_50751001_33_dialog_content = "Ya, Keluarga Lin memang memiliki kekayaan yang cukup besar, tetapi tidak sampai pada titik di mana kita bisa mengambil alih kesejahteraan seluruh penduduk kota.",
  ui_story_5075_50751001_34_dialog_content = "Selain itu, Keluarga Lin pernah terlibat dalam kasus penyelundupan sebelumnya, dan membutuhkan banyak usaha untuk membersihkan nama kami.",
  ui_story_5075_50751001_35_dialog_content = "Dunia bisnis itu seperti medan perang—tidak apa-apa bermain kotor di belakang layar, tetapi citra publik kita harus tetap bersih.",
  ui_story_5075_50751001_36_dialog_content = "Kamu menggunakan nama Keluarga Lin untuk menjamin orang-orang jahat. Setiap kesalahan, dan Keluarga Lin akan menjadi target publik.",
  ui_story_5075_50751001_37_dialog_content = "Aku sangat tahu akan hal ini.",
  ui_story_5075_50751001_38_dialog_content = "Tapi Yoh berada di balik ancaman fiendling, dan Lins adalah penyebab dendam pada awalnya.",
  ui_story_5075_50751001_39_dialog_content = "Lins harus bertanggung jawab.",
  ui_story_5075_50751001_40_dialog_content = "Waktu telah berubah, memang.",
  ui_story_5075_50751001_41_dialog_content = "Kerajaan Ji menghargai perdagangan, dan para pedagang selalu mengutamakan keuntungan.",
  ui_story_5075_50751001_42_dialog_content = "Saat aku masih muda, semua orang berebut untuk mendapatkan keuntungan sekecil apapun, bahkan menginginkan semangkuk nasi di tangan pengemis.",
  ui_story_5075_50751001_43_dialog_content = "Dan Lins bahkan akan mengorbankan ikan ular yang telah mereka sembah selama generasi untuk melayani kepentingan mereka.",
  ui_story_5075_50751001_44_dialog_content = "Jadi sekarang kamu ingin saya menaruh segala hal yang telah saya kerjakan dengan keras di garis depan hanya karena \"pertanggungjawaban\"?",
  ui_story_5075_50751001_45_dialog_content = "Ucapan saya jauh dari kosong, Guildmaster. Saya tahu bahwa saya bisa mewujudkannya.",
  ui_story_5075_50751001_46_dialog_content = "Tunggu, kalian berdua! Ini bukan waktunya untuk berdebat...",
  ui_story_5075_50751001_47_dialog_content = "Saya memiliki mantra untuk kamu pelajari.",
  ui_story_5075_50751001_48_dialog_content = "Tidak peduli masalah apa yang Anda hadapi, cukup ulangi saja, dan sebagian besar segalanya akan baik-baik saja.",
  ui_story_5075_50751001_49_dialog_content = "(Meskipun aku ragu itu akan membantu, aku tidak akan tahu kecuali aku mencoba!)",
  ui_story_5075_50751001_50_dialog_content = "<color=#FFB400>Merry... <size=45>Merry Tahun Baru!</size></color>",
  ui_story_5075_50751001_51_dialog_content = "...",
  ui_story_5075_50751001_52_dialog_content = "...",
  ui_story_5075_50751001_53_dialog_content = "Hahaha... Ini tahun baru.",
  ui_story_5075_50751001_54_dialog_content = "Ucapkan selamat tinggal pada yang lama dan sambut yang baru—saatnya untuk awal yang baru.",
  ui_story_5075_50751001_55_dialog_content = "Setelah semua persiapan, hari resmi dari Festival Musim Semi adalah besok, bukan?",
  ui_story_5075_50751001_56_dialog_content = "Benar.",
  ui_story_5075_50751001_57_dialog_content = "Apakah semuanya sudah siap? Bagaimana dengan makan malam Tahun Baru Eve?",
  ui_story_5075_50751001_58_dialog_content = "Sebagian besar bahan kami telah ditempatkan di penyimpanan dingin, dan sayuran segar akan dikirimkan kepada kami pada hari itu.",
  ui_story_5075_50751001_59_dialog_content = "Akun guild diselesaikan dua hari yang lalu. Sebuah ringkasan telah ditempatkan di studi Anda untuk Anda baca sesuai kenyamanan Anda.",
  ui_story_5075_50751001_60_dialog_content = "Bisnis guild kami kembali kesulitan tahun ini, tetapi saya masih merasa perlu untuk memberi penghargaan kepada pengawal dan pekerja dengan tambahan upah selama dua bulan.",
  ui_story_5075_50751001_61_dialog_content = "Kamu pasti punya pikiran sendiri.",
  ui_story_5075_50751001_62_dialog_content = "Ketika berlayar di laut yang selalu tak menentu, seorang kapten harus merespons dengan cepat dan tegas.",
  ui_story_5075_50751001_63_dialog_content = "Angin buntut atau arus yang melonjak bisa sepenuhnya terlewatkan jika aku gagal menangkapnya tepat waktu.",
  ui_story_5075_50751001_64_dialog_content = "Apa menurutmu apa yang kita hadapi sekarang ini adalah angin bertiup ke belakang untuk Lin Family?",
  ui_story_5075_50751001_65_dialog_content = "Jika kamu yakin tentang itu, saya akan setuju dengan permintaanmu.",
  ui_story_5075_50751001_66_dialog_content = "Syukurlah... Kau baik-baik saja...",
  ui_story_5075_50751001_67_dialog_content = "<size=45>Saya tidak bisa.</size>",
  ui_story_5075_50751001_68_dialog_content = "Kau…",
  ui_story_5075_50751001_69_dialog_content = "Saya tahu betul bahwa segala rencana atau perhitungan bisa langsung tersapu oleh gelombang yang cukup besar.",
  ui_story_5075_50751001_70_dialog_content = "Ketika itu terjadi, satu-satunya hal yang akan mencegah kapal dari terbalik adalah lunas yang kuat dan stabil.",
  ui_story_5075_50751001_71_dialog_content = "Tulang punggung kapal tidak boleh pernah bengkok atau patah.",
  ui_story_5075_50751001_72_dialog_content = "...",
  ui_story_5075_50751001_73_dialog_content = "Mungkin penilaianmu tentang situasi saat ini benar, tapi aku tetap menjadi produk dari era lama.",
  ui_story_5075_50751001_74_dialog_content = "Dari sudut pandang saya, tindakan Anda terlalu radikal dan berisiko.",
  ui_story_5075_50751001_75_dialog_content = "Guildmaster—",
  ui_story_5075_50751001_76_dialog_content = "Namun, Anda adalah kapten dari Shadowind, yang mengendalikan rute pengiriman yang sangat penting untuk Keluarga Lin.",
  ui_story_5075_50751001_77_dialog_content = "Di mata orang lain, apa yang Anda katakan mewakili seluruh Keluarga Lin.",
  ui_story_5075_50751001_78_dialog_content = "Apa ini artinya...",
  ui_story_5075_50751001_79_dialog_content = "Mungkin saya kuno, tetapi yang terpenting, saya adalah seorang pengusaha yang mempertimbangkan berbagai faktor dan menimbang pro dan kontra.",
  ui_story_5075_50751001_80_dialog_content = "Kamu adalah kapten yang mampu menguasai kapal modern yang rumit dan tentunya bebas melakukan apa yang kamu inginkan.",
  ui_story_5075_50751001_81_dialog_content = "Jika Anda berhasil, Anda akan menjadi pahlawan bagi Lin Guild, dan saya akan menempatkan Anda untuk mengendalikan rute laut di dekat Longzhou juga.",
  ui_story_5075_50751001_82_dialog_content = "Jika ini tidak berhasil, kamu akan menjadi seseorang yang telah melanggar perintah ketua guild, bertindak tanpa izin.",
  ui_story_5075_50751001_83_dialog_content = "Keluarga mungkin akan segera membuangmu, dan kamu bahkan mungkin kehilangan nama belakangmu.",
  ui_story_5075_50751001_84_dialog_content = "Bisakah kamu menerima kondisi-kondisi ini?",
  ui_story_5075_50751001_85_dialog_content = "<size=45>Aku terima.</size>",
  ui_story_5075_50751001_86_dialog_content = "Ayo, PlayerName.",
  ui_story_5075_50751001_87_dialog_content = "Tentu... Oh, tapi tunggu sebentar.",
  ui_story_5075_50751001_88_dialog_content = "Bisakah kamu menjaga lambang ini untukku untuk sementara waktu, Guildmaster?",
  ui_story_5075_50751001_89_dialog_content = "Kamu akan mempercayai saya dengan sesuatu yang sangat penting?",
  ui_story_5075_50751001_91_dialog_content = "Jangan lupa bahwa aku adalah orang yang penuh tipu daya dan tidak berprinsip.",
  ui_story_5075_50751001_92_dialog_content = "Haha... Aku akan berbohong jika aku bilang aku benar-benar merasa lega dengan keputusan ini.",
  ui_story_5075_50751001_93_dialog_content = "Tapi saya tidak melihat ada kesempatan untuk menggunakannya dalam waktu dekat, dan peta yang datang bersamanya juga menunjukkan saya ke arahmu.",
  ui_story_5075_50751001_94_dialog_content = "Kamu terus bersikeras bahwa kamu tidak bisa dipercaya, tapi Yuebai dan Zhong Xu masih percaya padamu.",
  ui_story_5075_50751001_95_dialog_content = "Dan saya percaya penilaian mereka.",
  ui_story_5075_50751001_96_dialog_content = "Kemampuan psikisku juga memberitahuku bahwa meskipun kamu mencoba melakukan sesuatu yang buruk dengan itu, seseorang di sini akan menghentikanmu.",
  ui_story_5075_50751001_97_dialog_content = "Baiklah, dalam hal itu, aku akan menerimanya.",
  ui_story_5075_50751001_98_dialog_content = "Terima kasih.",
  ui_story_5075_50751001_99_dialog_content = "Ayo, Yuebai, mari pergi—",
  ui_story_5075_50751001_100_dialog_content = "Haha, generasi muda.",
  ui_story_5075_50751001_101_dialog_content = "Selalu menuju ke tempat-tempat berisiko, mereka masih terlalu impulsif. Sulit untuk merasa tenang tentang masa depan Lin Family.",
  ui_story_5075_50751001_102_dialog_content = "Nah, raut wajahmu mengatakan sebaliknya.",
  ui_story_5075_50751001_103_dialog_content = "Ini hampir berteriak, \"Lins memiliki banyak penerus yang menunggu di belakang layar.\"",
  ui_story_5075_50751001_104_dialog_content = "Hahaha, Zhong Xu, rupanya matamu tajam juga.",
  ui_story_5075_50751001_105_dialog_content = "Saya berharap bisa perlahan mengurai masalah-masalah masa lalu dan meninggalkan segalanya bersih untuk generasi berikutnya.",
  ui_story_5075_50751001_106_dialog_content = "Saya tidak menyangka dia selangkah lebih maju dariku dan dia sudah mengambil tanggung jawab ini sebelum saya bisa turut campur.",
  ui_story_5075_50751001_107_dialog_content = "Tapi Zhong Xu, kamu telah mengawasi dari bayangan. Mengapa tidak membantu?",
  ui_story_5075_50751001_108_dialog_content = "PlayerName sudah menyadari keterlibatan Anda.",
  ui_story_5075_50751001_109_dialog_content = "Jadi, kau juga.",
  ui_story_5075_50751001_110_dialog_content = "Teman muda kita bahkan membawa lambang dari Kantor Inspeksi ke sini, namun kau masih menolak untuk membicarakan kesepakatanmu dengan Penasihat Utama.",
  ui_story_5075_50751001_111_dialog_content = "Sudah jelas kamu berjanji padanya bahwa kamu akan membantu. Begitu teman muda kita tiba di sini, saya didesak untuk memobilisasi pengawal Lin.",
  ui_story_5075_50751001_112_dialog_content = "Jadi, kenapa harus berpura-pura?",
  ui_story_5075_50751001_113_dialog_content = "Cara kami berbicara secara tidak langsung, sulit bagi kami orang tua untuk berkomunikasi dengan orang muda.",
  ui_story_5075_50751001_114_dialog_content = "Pikirkan saja ini sebagai persiapan saya untuk Festival Musim Semi, sebuah upacara untuk melepas yang lama dan menyambut yang baru.",
  ui_story_5075_50751001_115_dialog_content = "Lihat? Ini belum Festival Musim Semi, dan kita sudah mendengar begitu banyak kata-kata yang bagus.",
  ui_story_5075_50751001_116_dialog_content = "Ini pertanda baik, bukan?",
  ui_story_5075_50751001_117_dialog_content = "Berhenti bicara omong kosong! Orang ini membela fiendling. Dia pasti berniat jahat.",
  ui_story_5075_50751001_118_dialog_content = "Minggir sekarang dan biarkan kami mengusir makhluk jahat ini sebelum terlambat.",
  ui_story_5075_50751001_119_dialog_content = "Jika tidak, meskipun Anda memiliki sihir, kami tidak akan membiarkan Anda dengan mudah.",
  ui_story_5075_50751001_120_dialog_content = "Aku tahu kalian semua takut, tapi kita harus berpikir masuk akal tentang ini—",
  ui_story_5075_50751001_121_dialog_content = "Usir mereka semua!",
  ui_story_5075_50751001_122_dialog_content = "Usir mereka!",
  ui_story_5075_50751001_123_dialog_content = "Groar!",
  ui_story_5075_50751001_124_dialog_content = "Ini buruk. Aku tidak bisa mengumpulkan semua fiendlings...",
  ui_story_5075_50751001_125_dialog_content = "Penyempitan Ular!",
  ui_story_5075_50751002_1_dialog_content = "<color=#e8d9bb>Mu Yuebai dengan cepat memotong melalui kawanan fiendlings seperti belati yang sangat tajam.</color>",
  ui_story_5075_50751002_2_dialog_content = "<color=#e8d9bb>Kerumunan hampir tidak punya waktu untuk bereaksi. Makhluk jahat yang baru saja mengamuk sudah kehilangan kesadaran, roboh ke tanah.</color>",
  ui_story_5075_50751002_3_dialog_content = "Siapa... Siapa itu? Sungguh luar biasa!",
  ui_story_5075_50751002_4_dialog_content = "Aku tahu! Itu adalah Kapten Mu dari Lin Guild.",
  ui_story_5075_50751002_5_dialog_content = "Tapi ekornya... Dia punya darah iblis di dalamnya, bukan...",
  ui_story_5075_50751002_6_dialog_content = "Bagaimana kamu bisa mengatakan itu? Dia baru saja menyelamatkan kita!",
  ui_story_5075_50751002_7_dialog_content = "Semuanya, tolong dengarkan apa yang ingin saya katakan.",
  ui_story_5075_50751002_8_dialog_content = "Aku tahu hari ini adalah hari yang menakutkan. Beberapa orang terluka sementara yang lain mengalami kerugian.",
  ui_story_5075_50751002_9_dialog_content = "Aku juga merasakan frustrasi semua orang.",
  ui_story_5075_50751002_10_dialog_content = "Tapi, makhluk-makhluk jahat ini bukanlah penyebab dari masalah yang kita alami. Mereka hanyalah boneka dari pelaku yang lebih jahat lagi.",
  ui_story_5075_50751002_11_dialog_content = "Dengan hanya melawan para fiendling, kita justru bermain sesuai keinginan mereka.",
  ui_story_5075_50751002_12_dialog_content = "Kamu berbagi garis keturunan dengan mereka, dan itulah mengapa kamu mengatakan itu!",
  ui_story_5075_50751002_13_dialog_content = "Tapi aku lebih Aurorian daripada ikan ular, itu selalu benar. Selain itu, Keluarga Lin berbisnis dengan orang, bukan fiendlings.",
  ui_story_5075_50751002_14_dialog_content = "Mengapa saya harus merusak prospek guild kita dengan bekerja melawanmu?",
  ui_story_5075_50751002_15_dialog_content = "...",
  ui_story_5075_50751002_16_dialog_content = "Kata-kata seringkali tak berdasar, dan aku tahu aku tak punya hak untuk memintamu percaya pada kata-kataku.",
  ui_story_5075_50751002_17_dialog_content = "Tapi demi nama Lin Guild, saya berjanji untuk memberikan Anda semua bukti yang tak terbantahkan tentang kebenaran di balik insiden ini.",
  ui_story_5075_50751002_18_dialog_content = "Kita tidak boleh membiarkan diri kita disesatkan dan dieksploitasi oleh musuh. Jika kita melakukannya, hanya akan membiarkan mereka beroperasi dengan bebas tanpa hukuman.",
  ui_story_5075_50751002_19_dialog_content = "Meski kamu bilang begitu...",
  ui_story_5075_50751002_20_dialog_content = "(Mereka masih belum sepenuhnya yakin, tapi apa yang bisa kita tawarkan kepada mereka sebagai bukti? ... Tunggu, aku tahu!)",
  ui_story_5075_50751002_21_dialog_content = "Force Boost!",
  ui_story_5075_50751002_22_dialog_content = "(Tolong, meskipun hanya sedikit, biarkan aku menunjukkan pada semua orang apa yang aku lihat...)",
  ui_story_5075_50751002_23_dialog_content = "Semuanya! Tolong lihat lebih dekat fiendlings ini!",
  ui_story_5075_50751002_24_dialog_content = "Apa sih itu?",
  ui_story_5075_50751002_25_dialog_content = "Ini adalah apa yang digunakan oleh pelaku sebenarnya untuk mengendalikan para setan ini.",
  ui_story_5075_50751002_26_dialog_content = "Selama mereka masih terinfeksi kekuatan ini, mengusir fiendlings dari kota tidak akan mengubah apa-apa.",
  ui_story_5075_50751002_27_dialog_content = "Mereka... sebenarnya tidak terlihat berbohong.",
  ui_story_5075_50751002_28_dialog_content = "Lins memang telah melakukan banyak hal untuk semua orang selama bertahun-tahun, tapi...",
  ui_story_5075_50751002_29_dialog_content = "<color=#e8d9bb>Mereka berkerumun dan, setelah diskusi singkat dengan bisikan, mengirimkan seorang wakil.</color>",
  ui_story_5075_50751002_30_dialog_content = "Baik, kami akan mempercayaimu untuk saat ini.",
  ui_story_5075_50751002_31_dialog_content = "Sudah larut, dan kita tidak ingin membuang waktu di sini.",
  ui_story_5075_50751002_32_dialog_content = "Tapi masih ada beberapa fiendlings yang bersembunyi di kota. Siapa tahu apa yang mungkin mereka lakukan saat kamu sedang menyelidiki?",
  ui_story_5075_50751002_33_dialog_content = "Jadi, kami memiliki syarat.",
  ui_story_5075_50751002_34_dialog_content = "Kamu harus menyelesaikan ini sebelum Festival Musim Semi, sehingga kita semua bisa menikmati liburan yang baik.",
  ui_story_5075_50751002_35_dialog_content = "Aku mengerti.",
  ui_story_5075_50751002_36_dialog_content = "Benar sekali! Ini Tahun Baru! Semua orang ingin masalah ini diselesaikan secepat mungkin!",
  ui_story_5075_50751002_37_dialog_content = "<color=#e8d9bb>Mu Yuebai mengirim orang untuk meredakan kerumunan hingga mereka akhirnya bubar.</color>",
  ui_story_5075_50751002_38_dialog_content = "Terima kasih atas bantuanmu.",
  ui_story_5075_50751002_39_dialog_content = "Menghadapi sebanyak itu orang sendirian pasti sangat melelahkan.",
  ui_story_5075_50751002_40_dialog_content = "Ketika kamu mengatakan \"mengambil,\" kamu tidak bermaksud...",
  ui_story_5075_50751002_41_dialog_content = "Tidak apa-apa. Festival Musim Semi hanya sehari lagi, jadi kita sebaiknya bergegas.",
  ui_story_5075_50751002_42_dialog_content = "Beruntung, kami berhasil menggali banyak petunjuk.",
  ui_story_5075_50751002_43_dialog_content = "Untuk memulai, seseorang menghancurkan segel Chen'ni, memungkinkan kekuatan naga hitam untuk bangkit dari laut.",
  ui_story_5075_50751002_44_dialog_content = "Meskipun kekuatan itu memiliki sejumlah sifat unik, pada akhirnya itu masih hanya jenis Darkflow.",
  ui_story_5075_50751002_45_dialog_content = "Darkflow itu, pada gilirannya, telah menarik banyak Eclipsite ke pantai Haojin, mencegah kapal-kapal Keluarga Lin untuk berlayar dan efektif menghentikan bisnis mereka.",
  ui_story_5075_50751002_46_dialog_content = "Ini memaksa Guildmaster Lin untuk mencari Yoh, setan yang dia kerjakan, dan memintanya untuk mencari alasan mengapa Eclipsite berkumpul.",
  ui_story_5075_50751002_47_dialog_content = "Hanya untuk Yoh yang tercemar oleh kabut gelap selama investigasi dan tidak menyisakan apa-apa kecuali kebencian pada Keluarga Lin.",
  ui_story_5075_50751002_48_dialog_content = "Dan setelah mendapatkan wadah fisik, kabut hitam menjadi lebih aktif dan mulai mempengaruhi fiendlings di area tersebut.",
  ui_story_5075_50751002_49_dialog_content = "Pengaruhnya akhirnya merasuk ke dalam kota Haojin.",
  ui_story_5075_50751002_50_dialog_content = "Oleh karena itu, kita harus menemukan Yoh terlebih dahulu dan menghapus korupsi darinya.",
  ui_story_5075_50751002_51_dialog_content = "Setelah itu, kita perlu menemukan cara untuk menyegel kabut hitam ini, sama seperti yang dilakukan Chen'ni di masa lalu.",
  ui_story_5075_50751002_52_dialog_content = "Lantas, apa yang kita tunggu?",
  ui_story_5075_50751002_53_dialog_content = "Ciit!",
  ui_story_5075_50751002_54_dialog_content = "Api Penjaga Fiendling!",
  ui_story_5075_50751002_55_dialog_content = "Argh, kabut hitam telah menyebar ke sebagian besar kota! Semakin banyak makhluk jahat yang tunduk pada efeknya.",
  ui_story_5075_50751002_56_dialog_content = "Kamu harus tinggal di sini, Luo Song.",
  ui_story_5075_50751002_57_dialog_content = "Mereka butuh bantuanmu.",
  ui_story_5075_50751002_58_dialog_content = "Baiklah. Tapi sebelum kamu pergi, ini—",
  ui_story_5075_50751002_59_dialog_content = "Ada apa ini?",
  ui_story_5075_50751002_60_dialog_content = "Tinju bertemu.",
  ui_story_5075_50751002_61_dialog_content = "Ini akan menjadikan kita teman dalam perjuangan bersama.",
  ui_story_5075_50751002_62_dialog_content = "Ketika kamu kembali, aku akan mentraktirmu beberapa water chestnut paling segar di dunia.",
  ui_story_5075_50751002_63_dialog_content = "Baiklah!",
  ui_story_5075_50751002_64_dialog_content = "Aku akan pergi mencari lebih banyak fiendlings yang rusak. Lakukan yang terbaik di luar sana!",
  ui_story_5075_50751002_65_dialog_content = "Aku akan! Sekarang untuk mencari Yuebai... Hah?",
  ui_story_5075_50751002_66_dialog_content = "Yang Mulia, kami akhirnya menemukan Anda lagi.",
  ui_story_5075_50751002_67_dialog_content = "Kamu benar-benar tahu cara... berkeliling.",
  ui_story_5075_50751002_68_dialog_content = "Ini adalah pengurus rumah tangga... Ap-Apa yang membawa Anda ke sini, Tuan?",
  ui_story_5075_50751002_69_dialog_content = "Mengingat meningkatnya keberadaan makhluk jahat di kota, tugas kami adalah menjamin keamanan Anda.",
  ui_story_5075_50751002_70_dialog_content = "Silakan ikuti kami kembali ke Penginapan Kerajaan.",
  ui_story_5075_50751002_71_dialog_content = "Maaf, tapi aku tidak bisa kembali sekarang. Aku masih memiliki hal penting yang harus dilakukan.",
  ui_story_5075_50751002_72_dialog_content = "Tolong, jangan membuat segalanya sulit bagi kami. Anda adalah tamu terhormat yang datang jauh-jauh ke Kerajaan Ji kami.",
  ui_story_5075_50751002_73_dialog_content = "Jika sesuatu terjadi padamu, kami mungkin bisa kehilangan kepala kami. Tolong mengerti situasi kami.",
  ui_story_5075_50751002_74_dialog_content = "Antar utusan terhormat kembali ke rumah tamu!",
  ui_story_5075_50751002_75_dialog_content = "Tunggu! Lepaskan aku—",
  ui_story_5075_50751002_76_dialog_content = "Aku kembali, PlayerName.",
  ui_story_5075_50751002_77_dialog_content = "... PlayerName?",
  ui_story_5075_50751101_1_dialog_content = "Bunga, Mekar Tanpa Henti!",
  ui_story_5075_50751101_2_dialog_content = "Hmm…",
  ui_story_5075_50751101_3_dialog_content = "Semua dari kalian tampaknya adalah pembunuh yang terampil, namun tidak ada satu pun gerakan kalian yang mematikan.",
  ui_story_5075_50751101_4_dialog_content = "Apakah niatnya untuk mengalihkan dan menundaku?",
  ui_story_5075_50751101_5_dialog_content = "...",
  ui_story_5075_50751101_6_dialog_content = "Bahkan ketika aku pura-pura menyerang bagian vitalmu, kau tidak melakukan perlawanan.",
  ui_story_5075_50751101_7_dialog_content = "Beberapa orang terluka sementara saya tetap tak tergores.",
  ui_story_5075_50751101_8_dialog_content = "Heheh. Kurasa aku akhirnya mengerti apa yang dimaksud PlayerName sekarang.",
  ui_story_5075_50751101_9_dialog_content = "Sangat aneh untuk diperlakukan begitu baik secara tiba-tiba.",
  ui_story_5075_50751101_10_dialog_content = "Tapi ada alasan di balik setiap keanehan di dunia ini.",
  ui_story_5075_50751101_11_dialog_content = "Apa yang ditulis oleh Menteri Armilla dalam pesannya, apa yang disebutkan oleh Jiu sebelum dia pergi, dan nasihat dari mentorku.",
  ui_story_5075_50751101_12_dialog_content = "Hanya orang bodoh yang tidak bisa mengetahui dengan banyak petunjuk ini.",
  ui_story_5075_50751101_13_dialog_content = "Kamu adalah mata-mata untuk Kerajaan Ye, benar?",
  ui_story_5075_50751101_14_dialog_content = "!",
  ui_story_5075_50751101_15_dialog_content = "Yang Mulia, tebakan Anda benar. Sekarang Anda harus tahu kami tidak berniat membahayakan Anda.",
  ui_story_5075_50751101_16_dialog_content = "Situasi semakin rumit di Kota Haojin. Jadi tolong, Yang Mulia, kembali ke istana demi keselamatan Anda.",
  ui_story_5075_50751101_17_dialog_content = "Apakah kepergianku dari istana sekarang akan merusak rencanamu?",
  ui_story_5075_50751101_18_dialog_content = "Antara dua kerajaan, konflik bolak-balik, baik yang terbuka maupun yang di belakang layar, adalah hal yang umum terjadi.",
  ui_story_5075_50751101_19_dialog_content = "Yang Mulia, Anda berhati baik, dan <color=#FFB400>tuan kami</color> tidak ingin melihat Anda dalam situasi yang sulit. Jadi, silakan kembali.",
  ui_story_5075_50751101_20_dialog_content = "... <color=#FFB400>Tuanmu</color>.",
  ui_story_5075_50751101_21_dialog_content = "Yang Mulia, jika Anda tetap bersikeras melawan saran kami, kami harus menggunakan kekerasan.",
  ui_story_5075_50751101_22_dialog_content = "Pergi dapatkan dia!",
  ui_story_5075_50751101_23_dialog_content = "Bangkitlah Angin!",
  ui_story_5075_50751101_24_dialog_content = "<color=#e8d9bb>Wush—</color>",
  ui_story_5075_50751101_25_dialog_content = "Apakah Anda terluka, Yang Mulia?",
  ui_story_5075_50751101_26_dialog_content = "Jiu? Saya pikir mereka membuatmu sibuk, dan kamu tidak akan kembali dalam waktu yang lama.",
  ui_story_5075_50751101_27_dialog_content = "Tugasku adalah melindungi kamu.",
  ui_story_5075_50751101_28_dialog_content = "Selama kamu membutuhkanku, aku akan kembali berada di sisimu, di mana pun aku berada.",
  ui_story_5075_50751101_29_dialog_content = "<color=#e8d9bb>Tiba-tiba, sebuah tangan meraih pergelangan kaki Jiu.</color>",
  ui_story_5075_50751101_30_dialog_content = "Frost... Pedang... Kamu tidak bisa...",
  ui_story_5075_50751101_31_dialog_content = "<color=#e8d9bb>Wush—</color>",
  ui_story_5075_50751101_32_dialog_content = "Aku punya firasat bahwa aku akan meminta banyak hal padamu nanti.",
  ui_story_5075_50751101_33_dialog_content = "Tapi kita memiliki masalah mendesak yang harus ditangani. Ayo pergi bersamaku untuk menemui PlayerName segera.",
  ui_story_5075_50751101_34_dialog_content = "Apakah Anda tahu di mana PlayerName berada, Yang Mulia?",
  ui_story_5075_50751101_35_dialog_content = "Aku terlalu terburu-buru untuk bertanya...",
  ui_story_5075_50751101_36_dialog_content = "Bisakah saya menarik minat Anda dalam sedikit ramalan?",
  ui_story_5075_50751101_37_dialog_content = "... Li Tianxian.",
  ui_story_5075_50751101_38_dialog_content = "Apa selama ini kamu telah mengawasi?",
  ui_story_5075_50751101_39_dialog_content = "Apa yang kamu katakan? Saya baru saja menjual habis patung gula saya dan punya firasat.",
  ui_story_5075_50751101_40_dialog_content = "Aku punya firasat aku akan bertemu dengan seseorang yang penting dengan cara ini, jadi di sinilah aku, mencoba peruntunganku.",
  ui_story_5075_50751101_41_dialog_content = "Tapi aku tidak melihat apa pun yang seharusnya tidak kulihat. Jujur.",
  ui_story_5075_50751101_42_dialog_content = "Tidak apa-apa. Lupakan saja.",
  ui_story_5075_50751101_43_dialog_content = "Saya lihat sulit untuk mendapatkan klien baru. PlayerName masih yang terbaik karena percaya semua yang saya katakan.",
  ui_story_5075_50751101_44_dialog_content = "... Kamu melihat PlayerName?",
  ui_story_5075_50751101_45_dialog_content = "Tentu saja. Dapatkan permen bunga plum dan puisi dari saya juga.",
  ui_story_5075_50751101_46_dialog_content = "Tapi, tidak perlu berterima kasih padaku.",
  ui_story_5075_50751101_47_dialog_content = "Itu absurd. Kenapa aku harus berterima kasih padamu?",
  ui_story_5075_50751101_48_dialog_content = "Tapi jika kamu bisa memberitahu saya di mana PlayerName berada, saya akan sangat berterima kasih.",
  ui_story_5075_50751101_49_dialog_content = "Di sana di Jalan Yulin, tapi sebaiknya kamu bergegas.",
  ui_story_5075_50751101_50_dialog_content = "Atau seseorang akan mengalahkanmu.",
  ui_story_5075_50751101_51_dialog_content = "... Ayo pergi, Jiu.",
  ui_story_5075_50751101_52_dialog_content = "Tunggu sebentar. Saya sangat senang karena semua patung gula hari ini terjual habis.",
  ui_story_5075_50751101_53_dialog_content = "Jadi, saya akan memberi Anda bacaan secara gratis.",
  ui_story_5075_50751101_54_dialog_content = "Sejauh yang bisa saya katakan, kamu akan menuju ke tenggara untuk bertemu dengan seseorang yang penting.",
  ui_story_5075_50751101_55_dialog_content = "Itulah lokasi Jalan Yulin. Kamu sendiri yang memberi tahu aku lokasinya.",
  ui_story_5075_50751101_56_dialog_content = "Tapi, tidak bisakah kamu hanya mengikuti arus dan mengakui bahwa itu adalah tujuanmu?",
  ui_story_5075_50751101_57_dialog_content = "Aku tidak punya waktu untuk omong kosongmu.",
  ui_story_5075_50751101_58_dialog_content = "Itulah takdir yang telah saya simpulkan dari bacaan Anda.",
  ui_story_5075_50751101_59_dialog_content = "Putri Dantang, kami berkonsultasi dengan roh dan dewa dalam kebanyakan ramalan.",
  ui_story_5075_50751101_60_dialog_content = "Tapi ramalan yang paling akurat adalah dengan berkonsultasi pada diri sendiri.",
  ui_story_5075_50751101_61_dialog_content = "Pikiran dan tindakan Anda menentukan takdir Anda.",
  ui_story_5075_50751101_62_dialog_content = "Ups, maaf telah menyita lebih banyak waktu Anda. Saya sudah selesai dan tidak akan menahan Anda lagi.",
  ui_story_5075_50751101_63_dialog_content = "...",
  ui_story_5075_50751101_64_dialog_content = "Terima kasih banyak.",
  ui_story_5075_50751101_65_dialog_content = "Jangan sebutkan itu, meski saya akan menghargai bisnis di masa depan.",
  ui_story_5075_50751101_66_dialog_content = "Jangan khawatir, aku tidak berencana untuk.",
  ui_story_5075_50751102_1_dialog_content = "Argh…",
  ui_story_5075_50751102_2_dialog_content = "Ini... sepertinya bukan seperti penginapan.",
  ui_story_5075_50751102_3_dialog_content = "Untuk semua pembicaraanmu tentang keramahan, ini adalah pertama kalinya aku melihat seseorang menjatuhkan dan menculik tamunya.",
  ui_story_5075_50751102_4_dialog_content = "Jika kamu hanya mau bekerja sama, aku tidak berniat muncul di depanmu seperti ini.",
  ui_story_5075_50751102_5_dialog_content = "Setelah semua, peran sebagai pengelola Guesthouse Kerajaan cukup nyaman, dan saya tidak ingin mengubahnya.",
  ui_story_5075_50751102_6_dialog_content = "Aku tidak menyangka kamu akan menyebabkan begitu banyak masalah, bahkan membuat keluarga Lin membantumu.",
  ui_story_5075_50751102_7_dialog_content = "Dalam skenario terburuk, kamu mungkin justru bisa menyelesaikan kekacauan yang sengaja kita buat.",
  ui_story_5075_50751102_8_dialog_content = "Jadi, kalianlah yang berada di balik ini?",
  ui_story_5075_50751102_9_dialog_content = "Memecahkan segel naga, menyebar kabut hitam di seluruh kota, mempertentangkan manusia dan makhluk iblis satu sama lain.",
  ui_story_5075_50751102_10_dialog_content = "Apa sebenarnya yang kamu cari?",
  ui_story_5075_50751102_11_dialog_content = "Itu bukan hal yang perlu kamu khawatirkan.",
  ui_story_5075_50751102_12_dialog_content = "Cukup beristirahat di tempat persembunyian ini untuk sekarang. Setelah semuanya tenang, <color=#FFB400>kami</color> akan membiarkanmu pergi.",
  ui_story_5075_50751102_13_dialog_content = "Dengan <color=#FFB400>\"kami,\"</color> apakah kamu maksud sekutumu di dalam pemerintahan Kerajaan Ji?",
  ui_story_5075_50751102_14_dialog_content = "Penasihat Utama itu memberitahumu, 'kan?",
  ui_story_5075_50751102_15_dialog_content = "Pria tua itu mengacaukan banyak tindakan kami bahkan sebelum menyadari keberadaan kami.",
  ui_story_5075_50751102_16_dialog_content = "Tapi dia tidak akan ada di sekitar kita lebih lama lagi.",
  ui_story_5075_50751102_17_dialog_content = "Dan ini semua berkatmu.",
  ui_story_5075_50751102_18_dialog_content = "Aku?",
  ui_story_5075_50751102_19_dialog_content = "Saya mendengar percakapanmu dengan Penasihat Utama dan Yang Mulia pada hari kamu tiba di istana.",
  ui_story_5075_50751102_20_dialog_content = "Jangan tertipu oleh tembok tinggi istana. Di dalam sana, itulah tempat dengan sedikit rahasia di dunia.",
  ui_story_5075_50751102_21_dialog_content = "Dia mungkin menyadari bahwa agen kami perlahan-lahan menyusup ke pemerintahan, tetapi tidak bisa memastikan siapa.",
  ui_story_5075_50751102_22_dialog_content = "Itulah sebabnya dia ingin menggunakan seseorang seperti kamu, seorang orang luar.",
  ui_story_5075_50751102_23_dialog_content = "Tetapi langkahnya telah memberi saya celah.",
  ui_story_5075_50751102_24_dialog_content = "Saya tahu pria tua itu memberikanmu lencana Kantor Inspeksi melalui kotak makanan itu.",
  ui_story_5075_50751102_25_dialog_content = "Jika memang kamu menggunakan kekuatan Kantor Inspeksi untuk menyelesaikan masalah saat ini, tindakannya hanya akan dianggap sebagai tindakan yang tepat.",
  ui_story_5075_50751102_26_dialog_content = "Ada ruang untuk pembenaran meski jika ada yang menyelidikinya.",
  ui_story_5075_50751102_27_dialog_content = "Tetapi jika seseorang mengetahui bahwa lambang itu ada padamu sebelum kamu bisa melakukan apa pun dengannya...",
  ui_story_5075_50751102_28_dialog_content = "Menjadi Penasihat Utama dan menyerahkan barang penting seperti itu kepada orang asing, terutama seseorang dari benua lain...",
  ui_story_5075_50751102_29_dialog_content = "Seseorang yang gerak-geriknya penuh misteri di saat-saat paling kacau di Haojin.",
  ui_story_5075_50751102_30_dialog_content = "Siapa yang bisa percaya bahwa kamu tidak berkonspirasi, merencanakan sesuatu terhadap Kerajaan Ji?",
  ui_story_5075_50751102_31_dialog_content = "Setiap orang di pemerintahan pasti akan mengutuknya karena pengkhianatan.",
  ui_story_5075_50751102_32_dialog_content = "Biarkan saya lihat, di mana kamu menyembunyikan lambang itu? Di saku Anda? Lengan?",
  ui_story_5075_50751102_33_dialog_content = "Kamu bisa berhenti mencari. Saya tidak membawanya lagi.",
  ui_story_5075_50751102_34_dialog_content = "Ketika Penasihat Utama meminta saya untuk beroperasi secara rahasia, saya merasa itu karena orang-orang di sekitar saya.",
  ui_story_5075_50751102_35_dialog_content = "Setelah saya menerima kotak makanan itu, saya semakin yakin bahwa ada seseorang di Penginapan Kerajaan yang tidak bisa dipercaya.",
  ui_story_5075_50751102_36_dialog_content = "Jika itu masalahnya, maka hanya masalah waktu sebelum kamu menemukannya.",
  ui_story_5075_50751102_37_dialog_content = "Itulah sebabnya saya harus segera keluar dari sana.",
  ui_story_5075_50751102_38_dialog_content = "Apa gunanya? Kamu masih belum menemukan kesempatan untuk memobilisasi Kantor Inspeksi.",
  ui_story_5075_50751102_39_dialog_content = "Ditambah, sebagai seseorang dari negeri yang jauh, jumlah orang yang Anda kenal di Longzhou sangat terbatas.",
  ui_story_5075_50751102_40_dialog_content = "Meskipun kamu kenal dengan Putri Zhuohua, dia berada di istana, dan aku telah memerintahkan mata-mata untuk memantau dia setiap saat, tidak memberi kamu kesempatan untuk berkomunikasi satu sama lain.",
  ui_story_5075_50751102_41_dialog_content = "Siapa pun yang Anda beri insignia dapat terungkap dengan penyelidikan sederhana.",
  ui_story_5075_50751102_42_dialog_content = "Oh, begitu. Itu keluarga Lin, bukan?",
  ui_story_5075_50751102_43_dialog_content = "Lin Guildmaster akan mengambil segala risiko selama itu menguntungkan.",
  ui_story_5075_50751102_44_dialog_content = "Tapi memberikan perintah Kantor Inspeksi kepada seorang pedagang dengan sejarah yang buruk... Hahaha!",
  ui_story_5075_50751102_45_dialog_content = "Bahkan di Kerajaan Ji, di mana perdagangan dan pedagang sangat dihargai, keabsurdan tindakan Anda belum pernah terjadi sebelumnya, sehingga mudah untuk menuduh Anda melakukan kejahatan.",
  ui_story_5075_50751102_46_dialog_content = "Untuk sesaat, saya benar-benar berpikir kamu memiliki kartu tersembunyi, ternyata kamu hanya anak kecil yang naif.",
  ui_story_5075_50751102_47_dialog_content = "Aku perlu mengawasi kruku. Tidak ada waktu untuk membuang-buang waktu padamu.",
  ui_story_5075_50751102_48_dialog_content = "Siapa bilang saya memberikan lambang kepada Keluarga Lin?",
  ui_story_5075_50751102_49_dialog_content = "Jika bukan Lins, kemungkinan besar adalah kedua orang yang tadi bersamamu.",
  ui_story_5075_50751102_50_dialog_content = "Rakyat jelata atau pedagang, tidak banyak perbedaan di sana—",
  ui_story_5075_50751102_51_dialog_content = "Bukan orang biasa.",
  ui_story_5075_50751102_52_dialog_content = "<size=45>Itu adalah <color=#FFB400>Tuan Putri Zhuohua</color>.</size>",
  ui_story_5075_50751102_53_dialog_content = "Tidakkah kamu mendengar? Saya bilang ada mata-mata di sekitar putri, dan dia tidak mungkin...",
  ui_story_5075_50751102_54_dialog_content = "<size=45>Dia akan segera ada di sini.</size>",
  ui_story_5075_50751102_55_dialog_content = "Lambang tersebut adalah simbol dari Kantor Inspeksi, alamat tersebut milik Keluarga Lin, dan orang yang membimbing saya adalah mentornya.",
  ui_story_5075_50751102_56_dialog_content = "Dan semuanya diikat bersama oleh begonia.",
  ui_story_5075_50751102_57_dialog_content = "Dantang adalah satu-satunya yang bisa memanfaatkan kedua hal ini sepenuhnya!",
  ui_story_5075_50751102_58_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5075_50751102_59_dialog_content = "Jangan bergerak atau kamu akan kehilangan kepalamu.",
  ui_story_5075_50751102_60_dialog_content = "Kau baik-baik saja, PlayerName?",
  ui_story_5075_50751102_61_dialog_content = "Dantang! Jiu!",
  ui_story_5075_50751102_62_dialog_content = "Kamu... Bagaimana kau... Ah!",
  ui_story_5075_50751102_63_dialog_content = "<color=#e8d9bb>Dantang tiba-tiba menarik wajah pengurus Penginapan Kerajaan.</color>",
  ui_story_5075_50751102_64_dialog_content = "<color=#e8d9bb>Sebuah topeng, tipis seperti sayap cicada, dilepas, mengungkapkan wajah baru yang aneh di bawahnya.</color>",
  ui_story_5075_50751102_65_dialog_content = "Anda memang bukan pengurus asli Penginapan Kerajaan tetapi seorang peniru.",
  ui_story_5075_50751102_66_dialog_content = "... Jadi apa jika kamu menangkapku? Itu tidak akan mengubah apapun.",
  ui_story_5075_50751102_67_dialog_content = "Kebijaksanaan tuan kita tak tertandingi. Kami, <color=#FFB400>Fate Riders</color>, ada di mana-mana.",
  ui_story_5075_50751102_68_dialog_content = "Rencana kami hampir selesai. Segel di dasar laut telah rusak, dan mimpi buruk yang tertidur telah terbangun!",
  ui_story_5075_50751102_69_dialog_content = "Ketika Haojin jatuh ke dalam kekacauan, kita akan masuk dan mengambil Kerajaan Ji tanpa keringat.",
  ui_story_5075_50751102_70_dialog_content = "Kecuali jika kamu memiliki dewa di pihakmu, jika tidak—urgh!",
  ui_story_5075_50751102_71_dialog_content = "Apakah ada seseorang yang meminta bantuan?",
  ui_story_5075_50751102_72_dialog_content = "Grr! Pff-urgh!",
  ui_story_5075_50751102_73_dialog_content = "Chen'ni? Sedang apa kau di sini?",
  ui_story_5075_50751102_74_dialog_content = "Saya mengejar pelaku yang memecahkan segel, tetapi akhirnya saya kehilangan bajingan itu.",
  ui_story_5075_50751102_75_dialog_content = "Jadi saya memutuskan untuk mengikuti jejaknya, menyelidiki setiap tempat yang dilalui orang itu dan setiap orang yang berhubungan dengannya.",
  ui_story_5075_50751102_76_dialog_content = "Termasuk di sini!",
  ui_story_5075_50751102_77_dialog_content = "Grr! Urgh!",
  ui_story_5075_50751102_78_dialog_content = "Dan aku bahkan bertemu dengan penjual patung gula.",
  ui_story_5075_50751102_79_dialog_content = "Penjual figurin gula yang membuat permen bunga plum?",
  ui_story_5075_50751102_80_dialog_content = "Itu dia! Dia sangat murah hati dan menawariku sekelompok figurin.",
  ui_story_5075_50751102_81_dialog_content = "Dia hanya menginginkan satu hal—itu adalah agar saya menanam ranting bunga plum di mana pun saya pergi.",
  ui_story_5075_50751102_82_dialog_content = "Jadi, kamu melakukannya?",
  ui_story_5075_50751102_83_dialog_content = "Tentu saja. Saya sudah mendapatkan persembahanku, jadi saya harus menepati janjiku.",
  ui_story_5075_50751102_84_dialog_content = "Saya juga menanam satu di luar rumah ini.",
  ui_story_5075_50751102_85_dialog_content = "Syukurlah... Dantang!",
  ui_story_5075_50751102_86_dialog_content = "Aku di sini.",
  ui_story_5075_50751102_87_dialog_content = "Saya mendapatkan lambang dari Tuan Lin Guild dan bantuan dari Penjaga Keluarga.",
  ui_story_5075_50751102_88_dialog_content = "Para pengawal sudah siap untuk perintah dari Zhong Xu untuk menekan Eclipsites dan fiendlings yang gila di kota.",
  ui_story_5075_50751102_89_dialog_content = "Setelah Kantor Inspeksi menangani apa yang disebut Fate Riders, mereka juga akan bergabung dalam pertempuran.",
  ui_story_5075_50751102_90_dialog_content = "Terima kasih... karena mengingat bunga yang aku cintai.",
  ui_story_5075_50751102_91_dialog_content = "Haha, saya hanya senang semuanya berhasil! Bagaimana keadaan di luar sana?",
  ui_story_5075_50751102_92_dialog_content = "Kami masih bertahan di kota, tetapi untuk pinggiran kota, itu tergantung pada Yuebai.",
  ui_story_5075_50751102_93_dialog_content = "Bagus. Sedangkan untuk luar kota, pengelola Penginapan Kerajaan... Pria ini baru saja mengatakan bahwa rencana mereka hampir selesai.",
  ui_story_5075_50751102_94_dialog_content = "Mungkin Yoh sudah sepenuhnya bergabung dengan kabut hitam sekarang.",
  ui_story_5075_50751102_95_dialog_content = "Kita perlu menemukannya dan menghentikan ini segera!",
  ui_story_5075_50751102_96_dialog_content = "Kalau begitu, ikutlah denganku.",
  ui_story_5075_50751102_97_dialog_content = "Saya telah mengatur sebuah kapal kecil untuk membawa kita langsung ke teluk.",
  ui_story_5075_50751102_98_dialog_content = "Dantang memiliki kota. Aku akan pergi dengan Yuebai untuk mencari Yoh... Huh?",
  ui_story_5075_50751102_99_dialog_content = "Uh... Gadis Naga?",
  ui_story_5075_50751102_100_dialog_content = "Aku tidak begitu mengerti ini, tapi ada seseorang yang menghukum orang yang memecahkan segel untukku, benar?",
  ui_story_5075_50751102_101_dialog_content = "Aku akan pergi bersamamu ke tepi laut!",
  ui_story_5075_50751102_102_dialog_content = "Mungkin ilusi yang diciptakan oleh Yoh terlalu tangguh untuk ditaklukkan oleh kekuatan seorang Caelestite sendirian.",
  ui_story_5075_50751201_1_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_2_dialog_content = "Hmm... Maaf, sepertinya aku tertidur. Sudah sampai belum, Yue...",
  ui_story_5075_50751201_3_dialog_content = "Hah?",
  ui_story_5075_50751201_4_dialog_content = "Nama siapa yang coba aku sebutkan barusan?",
  ui_story_5075_50751201_5_dialog_content = "Lebih penting lagi, apa yang sedang saya lakukan di kapal ini?",
  ui_story_5075_50751201_6_dialog_content = "Urgh... Kepalaku sakit.",
  ui_story_5075_50751201_7_dialog_content = "Hei, kamu lagi melamun lagi? Ayo bergerak, dan terus pindahkan kargo itu! Kami akan berlayar sebentar lagi.",
  ui_story_5075_50751201_8_dialog_content = "M-Muatan kargo? Saya?",
  ui_story_5075_50751201_9_dialog_content = "Tak ada orang lain di sini.",
  ui_story_5075_50751201_10_dialog_content = "Bukankah kamu yang mengatakan bahwa kerabatmu, Soroz atau siapa pun itu, sakit, dan kamu perlu bekerja untuk mengumpulkan uang obat dengan cepat?",
  ui_story_5075_50751201_11_dialog_content = "Siapa tahu apakah pelayaran ke luar negeri yang mereka bicarakan ini akan kembali dengan selamat.",
  ui_story_5075_50751201_12_dialog_content = "Baguslah bahwa Lin Guild mungkin kecil, tetapi mereka bersedia membayar mahal untuk perjalanan ini, bahkan memberikan setengahnya di muka.",
  ui_story_5075_50751201_13_dialog_content = "Dengan uang ini, akhirnya saya bisa membeli makanan enak untuk istri dan anak-anak saya.",
  ui_story_5075_50751201_14_dialog_content = "Keluarga Anda tidak perlu khawatir tentang uang obat untuk sementara waktu, bukan?",
  ui_story_5075_50751201_15_dialog_content = "(Ada yang tidak beres tentang ini, tapi apa yang dia katakan memang masuk akal...)",
  ui_story_5075_50751201_16_dialog_content = "(Argh... Kepalaku sakit lagi.)",
  ui_story_5075_50751201_17_dialog_content = "(Lebih baik aku hanya memuat kargo ini.)",
  ui_story_5075_50751201_18_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_19_dialog_content = "Hah? Ada apa ini?",
  ui_story_5075_50751201_20_dialog_content = "Dari mana semua kabut ini berasal?",
  ui_story_5075_50751201_21_dialog_content = "Kehilangan akal karena kelaparan? Kita sudah terjebak dalam kabut ini hampir dua minggu sekarang, hanya berputar-putar saja.",
  ui_story_5075_50751201_22_dialog_content = "Sepertinya kita semua di kapal ini mungkin akan bertemu akhir kita di sini.",
  ui_story_5075_50751201_23_dialog_content = "Istri dan anak-anakku menungguku di rumah, aku tidak bisa mati sekarang...",
  ui_story_5075_50751201_24_dialog_content = "<color=#e8d9bb>Desahannya memicu gelombang tangisan yang menyedihkan.</color>",
  ui_story_5075_50751201_25_dialog_content = "<color=#e8d9bb>Awak kapal dan pedagang tergeletak di seluruh geladak, nafas mereka terasa penuh dengan putus asa yang melelahkan.</color>",
  ui_story_5075_50751201_26_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751201_27_dialog_content = "(Apakah ada sesuatu yang baru saja menabrak kapal?)",
  ui_story_5075_50751201_28_dialog_content = "Cepat... Kemarilah dan lihat!",
  ui_story_5075_50751201_29_dialog_content = "Ikan-ikan itu, ikan-ikan itu mendorong kapal dari bawah!",
  ui_story_5075_50751201_30_dialog_content = "Mereka adalah ikan ular! Kita beruntung! Ini musim dingin, dan mereka selalu kembali ke Longzhou pada waktu ini setiap tahunnya!",
  ui_story_5075_50751201_31_dialog_content = "Ikuti mereka, dan kita bisa keluar dari sini!",
  ui_story_5075_50751201_32_dialog_content = "Lihat itu? Itu adalah berkat ilahi! Dewa pasti telah mendengar kita!",
  ui_story_5075_50751201_33_dialog_content = "(Apakah saya sedang berhalusinasi atau apa? Ikan ular di paling depan... Mengapa tampak begitu akrab?)",
  ui_story_5075_50751201_34_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_35_dialog_content = "Saya... adalah ikan ular.",
  ui_story_5075_50751201_36_dialog_content = "Saya mencari makanan saat berlayar di laut, dan sesekali saya mencari nasihat dari pengguna Luminatics lainnya.",
  ui_story_5075_50751201_37_dialog_content = "Setiap musim dingin, kami kembali ke Longzhou, tempat kelahiran kami.",
  ui_story_5075_50751201_38_dialog_content = "Suatu hari, kami menemukan sebuah kapal yang hilang di laut.",
  ui_story_5075_50751201_39_dialog_content = "Ini mengikuti kami kembali ke pantai Longzhou, di mana pemimpin mereka membuat perjanjian dengan pemimpin kami.",
  ui_story_5075_50751201_40_dialog_content = "Setiap musim dingin sejak saat itu, kami telah mengawal kapal itu dalam perjalanan kami ke Longzhou.",
  ui_story_5075_50751201_41_dialog_content = "Kami membimbing jalannya, dan sebagai balasannya, mereka menawarkan kami makanan.",
  ui_story_5075_50751201_42_dialog_content = "Itu adalah pertukaran yang menyenangkan, yang seharusnya membuat kita bahagia.",
  ui_story_5075_50751201_43_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_44_dialog_content = "Bos, bos? Lagi melamun di ikan serpent lagi?",
  ui_story_5075_50751201_45_dialog_content = "Maaf, tapi entah kenapa, salah satu ikan ular itu terlihat sangat familiar.",
  ui_story_5075_50751201_46_dialog_content = "Mereka semua tampak sama. Ada apa yang bisa dilihat? Di sini, cek ini.",
  ui_story_5075_50751201_47_dialog_content = "Ini bagianmu dari pelayaran ke luar negeri.",
  ui_story_5075_50751201_48_dialog_content = "Itu jauh terlalu berlebihan!",
  ui_story_5075_50751201_49_dialog_content = "Sejak Lins memulai jalur laut, kita semakin banyak menghasilkan. Ini hanyalah sepele.",
  ui_story_5075_50751201_50_dialog_content = "Tertarik untuk menghasilkan uang tambahan?",
  ui_story_5075_50751201_51_dialog_content = "A-Aku bisa membuat lebih banyak lagi?",
  ui_story_5075_50751201_52_dialog_content = "Saya telah berbicara dengan yang lain sebelum datang ke sini. Bisnis dari Lin Guild sedang berkembang.",
  ui_story_5075_50751201_53_dialog_content = "Semakin banyak kebutuhan untuk berdagang dengan tempat-tempat seperti Astra. Hanya satu pelayaran setahun bahkan tidak akan cukup untuk memenuhi permintaan!",
  ui_story_5075_50751201_54_dialog_content = "Bagaimana kalau kita bekerja sama dan berbicara dengan guildmaster tentang menambahkan satu lagi misi?",
  ui_story_5075_50751201_55_dialog_content = "Dua kali perjalanan dalam setahun, bagaimana menurutmu?",
  ui_story_5075_50751201_56_dialog_content = "Tapi saya pikir ikan ular hanya kembali ke Longzhou di musim dingin?",
  ui_story_5075_50751201_57_dialog_content = "Mereka sebagian besar waktu hanya berkeliaran di laut. Perjalanan tambahan kembali ke Longzhou seharusnya tidak begitu penting.",
  ui_story_5075_50751201_58_dialog_content = "Dengan uang tambahan yang kita dapatkan, kita bisa membeli lebih banyak makanan ikan untuk mereka, bukan?",
  ui_story_5075_50751201_59_dialog_content = "Saya tidak pikir ikan ular benar-benar peduli tentang itu.",
  ui_story_5075_50751201_60_dialog_content = "Tsk, sepertinya mustahil membujukmu untuk ini. Tidak apa-apa. Semua orang lain sudah setuju, jadi kamu tidak ikut bukan masalah besar.",
  ui_story_5075_50751201_61_dialog_content = "Tunggu, aku tidak—",
  ui_story_5075_50751201_62_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_63_dialog_content = "Setelah itu, pemimpin kami memberi tahu kami bahwa kami juga harus kembali ke Longzhou di musim panas.",
  ui_story_5075_50751201_64_dialog_content = "Air musim panas panas dan tidak menyenangkan.",
  ui_story_5075_50751201_65_dialog_content = "Namun teman-teman kami di kapal membutuhkan bantuan kami.",
  ui_story_5075_50751201_66_dialog_content = "Jadi kita sepakat.",
  ui_story_5075_50751201_67_dialog_content = "Meskipun perjalanan itu panjang dan melelahkan, kami setuju.",
  ui_story_5075_50751201_68_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_69_dialog_content = "Hari ini, saya telah mengumpulkan semua orang di sini untuk membuat pengumuman.",
  ui_story_5075_50751201_70_dialog_content = "Kami telah mengamankan kesepakatan bisnis dari Yangjing, dan untuk memenuhi permintaan, kita harus melakukan perjalanan jauh lagi tahun ini.",
  ui_story_5075_50751201_71_dialog_content = "Tapi tunggu, perjanjian kita dengan ikan ular hanya mencakup satu perjalanan per tahun.",
  ui_story_5075_50751201_72_dialog_content = "Meminta mereka untuk membimbing kita ke Longzhou di musim panas sudah merupakan pelanggaran kontrak, belum lagi—",
  ui_story_5075_50751201_73_dialog_content = "Ini adalah kesepakatan dari Yangjing, sesuatu yang banyak guild impikan.",
  ui_story_5075_50751201_74_dialog_content = "Apakah kamu sadar berapa banyak keuntungan yang akan didapatkan keluarga Lin dari kesepakatan ini?",
  ui_story_5075_50751201_75_dialog_content = "Saya mengerti keputusan ini tidak adil bagi serpentfish, dan saya akan minta maaf secara pribadi kepada fiendling setelahnya.",
  ui_story_5075_50751201_76_dialog_content = "Itu rencana kami sekarang.",
  ui_story_5075_50751201_77_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_78_dialog_content = "Tahun itu, kami kembali ke Longzhou tiga kali.",
  ui_story_5075_50751201_79_dialog_content = "Pemimpin kami mengatakan itu hanya sementara, dan bahwa teman-teman kita sedang dalam masalah.",
  ui_story_5075_50751201_80_dialog_content = "Namun tahun depan juga terdapat tiga perjalanan. Tahun berikutnya pun tidak berbeda.",
  ui_story_5075_50751201_81_dialog_content = "Beberapa dari kita sudah menghilang.",
  ui_story_5075_50751201_82_dialog_content = "Setelah itu, pemimpin kami meninggal dunia secara tak terduga.",
  ui_story_5075_50751201_83_dialog_content = "Dan begitu, saya menjadi pemimpin baru dari ikan ular.",
  ui_story_5075_50751201_84_dialog_content = "Teman-teman kami di kapal muncul suatu hari. Mereka membawa saya ke darat dan menempatkan saya dalam tangki di dalam sebuah bangunan kayu.",
  ui_story_5075_50751201_85_dialog_content = "Tangki itu sangat kecil dan sempit.",
  ui_story_5075_50751201_86_dialog_content = "Itu tak tertahankan.",
  ui_story_5075_50751201_87_dialog_content = "Tahun keempat melihat tiga perjalanan lainnya ke Longzhou.",
  ui_story_5075_50751201_88_dialog_content = "Tapi bahkan selama perjalanan kami, mereka menolak untuk membiarkan saya berenang di lautan.",
  ui_story_5075_50751201_89_dialog_content = "Mereka membawa tangki saya ke atas kapal mereka dan memberi saya makan dengan baik. Mereka mengatakan bahwa satu-satunya tugas saya adalah menginstruksikan jenis saya dari sana.",
  ui_story_5075_50751201_90_dialog_content = "Mereka menyebutnya \"ibadah,\" sebuah cara untuk menunjukkan rasa hormat mereka kepada fiendlings.",
  ui_story_5075_50751201_91_dialog_content = "Sudah bisa mengubah bentukmu, ya?",
  ui_story_5075_50751201_92_dialog_content = "...",
  ui_story_5075_50751201_93_dialog_content = "Tapi, kau masih tidak bisa bicara, 'kan?",
  ui_story_5075_50751201_94_dialog_content = "Apakah kamu ingin belajar? Aku bisa mengajarimu. Anggap saja ini sebagai kompensasi...",
  ui_story_5075_50751201_95_dialog_content = "Tidak apa-apa, kamu memang tidak bisa mengerti apa yang aku katakan.",
  ui_story_5075_50751201_96_dialog_content = "Lagi pula, kesalahan yang telah saya lakukan kepada Anda bukanlah sesuatu yang bisa diperbaiki dengan beberapa tindakan kecil.",
  ui_story_5075_50751201_97_dialog_content = "(Aku tahu dia adalah pemimpin mereka.)",
  ui_story_5075_50751201_98_dialog_content = "(Dia mengajari saya berbicara dan membaca bahasa mereka.)",
  ui_story_5075_50751201_99_dialog_content = "(Tapi aku juga tahu bahwa dia adalah seorang pria yang sangat jahat.)",
  ui_story_5075_50751201_100_dialog_content = "<color=#e8d9bb>Splash</color>",
  ui_story_5075_50751201_101_dialog_content = "Empat perjalanan?",
  ui_story_5075_50751201_102_dialog_content = "Keluarga Qi telah mengincar gelar Merchant Kekaisaran, ingin menantang Guild kami, Lin.",
  ui_story_5075_50751201_103_dialog_content = "Tanpa pencapaian yang lebih menonjol, kita mungkin akan keluar dari permainan.",
  ui_story_5075_50751201_104_dialog_content = "Kita tidak bisa membiarkan kejayaan berabad-abad dari Keluarga Lin menjadi ternoda di bawah pengawasan kita.",
  ui_story_5075_50751201_105_dialog_content = "Selama beberapa tahun terakhir, ikan ular semakin banyak yang mati! Jangan pura-pura tidak tahu!",
  ui_story_5075_50751201_106_dialog_content = "Dan? Jadi apa?",
  ui_story_5075_50751201_107_dialog_content = "Apa maksudmu, \"Jadi apa?\" Apa rencana yang akan kamu lakukan tentang itu?",
  ui_story_5075_50751201_108_dialog_content = "Ketika kami perlu mengirim lebih banyak barang, kami mulai melakukan dua perjalanan. Setelah menerima permintaan mendesak, itu naik menjadi tiga.",
  ui_story_5075_50751201_109_dialog_content = "Keluarga Lin berutang kesuksesan besarnya pada ikan ular!",
  ui_story_5075_50751201_110_dialog_content = "Mereka menyelamatkan kita dari kematian yang pasti dan bahkan setuju untuk membantu kita, dan inikah cara kita membalas mereka?",
  ui_story_5075_50751201_111_dialog_content = "Berhenti mencoba menyembunyikan keserakahanmu dengan alasan yang terdengar mulia!",
  ui_story_5075_50751201_112_dialog_content = "PlayerName…",
  ui_story_5075_50751201_113_dialog_content = "Argh... Siapa itu barusan?",
  ui_story_5075_50751201_114_dialog_content = "Kamu menerima bayaran dari Lin Guild kami tetapi tampaknya lebih berbakti pada ikan ular, huh?",
  ui_story_5075_50751201_115_dialog_content = "Kami tidak memerlukan seseorang seperti kamu. Kau boleh pergi.",
  ui_story_5075_50751201_116_dialog_content = "Saya harus menghadiri rapat tentang perjalanan keempat. Kamu pergi sendiri menyelesaikan pembayaran bulananmu dengan pengurus.",
  ui_story_5075_50751201_117_dialog_content = "... Apakah kamu yakin ingin melanjutkan ini?",
  ui_story_5075_50751201_118_dialog_content = "Apa maumu?",
  ui_story_5075_50751201_119_dialog_content = "Saya akan mengembalikan pemimpin ikan ular kembali ke laut.",
  ui_story_5075_50751201_120_dialog_content = "Disana! Aku menemukan tank!",
  ui_story_5075_50751201_121_dialog_content = "Maaf, tapi untuk mengembalikanmu ke laut, aku harus mengeluarkanmu dari air untuk sementara waktu.",
  ui_story_5075_50751201_122_dialog_content = "Hentikan dia!",
  ui_story_5075_50751201_123_dialog_content = "Dari mana semua orang ini berasal? Saya harus mencari cara untuk melewati mereka...",
  ui_story_5075_50751201_124_dialog_content = "Force Boost!",
  ui_story_5075_50751201_125_dialog_content = "Argh!",
  ui_story_5075_50751201_126_dialog_content = "... Hah? Kekuatan apa itu?",
  ui_story_5075_50751201_127_dialog_content = "PlayerName!",
  ui_story_5075_50751201_128_dialog_content = "... Chen'ni?",
  ui_story_5075_50751201_129_dialog_content = "Sudah waktunya kamu memperhatikan saya.",
  ui_story_5075_50751201_130_dialog_content = "Begitu kapal kita masuk ke teluk, kamu dan Yuebai langsung tertidur. Aku tidak bisa membangunkanmu tidak peduli apa yang aku coba.",
  ui_story_5075_50751201_131_dialog_content = "Aku sangat bosan dan ingin kalian berdua bangun.",
  ui_story_5075_50751201_132_dialog_content = "Aku ingat sekarang! Saat kami berlayar masuk ke teluk, gelombang besar kabut hitam langsung mengarah ke kami!",
  ui_story_5075_50751201_133_dialog_content = "Kekuatan itu pasti yang menjebak kita dalam mimpi ini... Ataukah ini semacam ilusi?",
  ui_story_5075_50751201_134_dialog_content = "Bagaimanapun.",
  ui_story_5075_50751201_135_dialog_content = "Kamu terlalu tenang tentang ini!",
  ui_story_5075_50751201_136_dialog_content = "Bukan itu yang penting.",
  ui_story_5075_50751201_137_dialog_content = "Lebih baik kamu periksa Yuebai sekarang.",
  ui_story_5075_50751201_138_dialog_content = "Sepertinya dia sangat menderita.",
  ui_story_5075_50751201_139_dialog_content = "Ini korupsi kabut hitam? Chen'ni, tidak bisakah kamu...",
  ui_story_5075_50751201_140_dialog_content = "Aku bisa, tapi tidak kali ini.",
  ui_story_5075_50751201_141_dialog_content = "Tapi, kenapa-",
  ui_story_5075_50751201_142_dialog_content = "Tidak baik mengandalkan dewa untuk segala hal.",
  ui_story_5075_50751201_143_dialog_content = "Kamu harus mengurus urusanmu sendiri.",
  ui_story_5075_50751201_144_dialog_content = "... Aku mengerti.",
  ui_story_5075_50751201_145_option_content = "Pemindaian Psikis!",
  ui_story_5075_50751201_146_dialog_content = "Yuebai! Di mana kamu?",
  ui_story_5075_50751201_147_dialog_content = "PlayerName.",
  ui_story_5075_50751201_148_dialog_content = "Ikan ular ini... Apakah itu kamu, Yuebai?",
  ui_story_5075_50751201_149_dialog_content = "Berhenti!",
  ui_story_5075_50751201_150_dialog_content = "Jangan ini lagi!",
  ui_story_5075_50751201_151_dialog_content = "... Ayo, kita harus menuju ke pantai!",
  ui_story_5075_50751201_152_dialog_content = "Fiuh... Kita... Kita berhasil.",
  ui_story_5075_50751201_153_dialog_content = "Kenapa aku harus merasa lelah bahkan dalam mimpi?",
  ui_story_5075_50751201_154_dialog_content = "Ayo kita masukkan kamu ke dalam air dulu, Yuebai. Setelah itu, kita akan...",
  ui_story_5075_50751201_155_dialog_content = "Yuebai?",
  ui_story_5075_50751201_156_dialog_content = "(Aku kehilangan jejaknya begitu dia masuk...)",
  ui_story_5075_50751201_157_dialog_content = "(Airnya... Penuh dengan kabut hitam!)",
  ui_story_5075_50751201_158_dialog_content = "...",
  ui_story_5075_50751201_159_dialog_content = "(Leader, aku lelah. Leader, aku lapar. Leader, itu sakit.)",
  ui_story_5075_50751201_160_dialog_content = "(Aku benci ini. Aku ingin kembali. Leader, tolong selamatkan aku.)",
  ui_story_5075_50751201_161_dialog_content = "(Selamatkan kami. Pemimpin... Selamatkan kami.)",
  ui_story_5075_50751201_162_dialog_content = "(Orang lain sedang memanggilku.)",
  ui_story_5075_50751201_163_dialog_content = "(Begitu bingung. Begitu kacau. Suara-suara ini... Hati ikan ular sedang menjerit.)",
  ui_story_5075_50751201_164_dialog_content = "Suara-suara itu.",
  ui_story_5075_50751201_165_dialog_content = "Mereka. Memanggil. Setiap. Hari.",
  ui_story_5075_50751201_166_dialog_content = "Selalu. Selalu.",
  ui_story_5075_50751201_167_dialog_content = "Mereka. Benci.",
  ui_story_5075_50751201_168_dialog_content = "Yoh.",
  ui_story_5075_50751201_169_dialog_content = "Sekarang aku paham.",
  ui_story_5075_50751201_170_dialog_content = "Apa yang baru saja aku alami adalah kenanganmu sendiri.",
  ui_story_5075_50751201_171_dialog_content = "Lins.",
  ui_story_5075_50751201_172_dialog_content = "Pengkhianat. Mereka.",
  ui_story_5075_50751201_173_dialog_content = "Orang. Tak. Bisa. Dipercaya.",
  ui_story_5075_50751201_174_dialog_content = "Kamu. Juga. Ikan.",
  ui_story_5075_50751201_175_dialog_content = "Harus. Benci!",
  ui_story_5075_50751201_176_dialog_content = "Yuebai! Bisakah kamu mendengarku?",
  ui_story_5075_50751201_177_dialog_content = "Aku datang untuk mencarimu!",
  ui_story_5075_50751201_178_dialog_content = "Tidak perlu, PlayerName.",
  ui_story_5075_50751201_179_dialog_content = "Hah?",
  ui_story_5075_50751201_180_dialog_content = "Keluarga Lin melakukan ini kepada Yoh.",
  ui_story_5075_50751201_181_dialog_content = "Dan karena saya diberi wewenang penuh atas Keluarga Lin hari ini, Yoh sepenuhnya dibenarkan untuk membalas dendam pada saya.",
  ui_story_5075_50751201_182_dialog_content = "...",
  ui_story_5075_50751201_183_dialog_content = "Kabut hitam berhenti?",
  ui_story_5075_50751201_184_dialog_content = "Tidak... Ini tidak benar...",
  ui_story_5075_50751201_185_dialog_content = "Aku... Tidak...",
  ui_story_5075_50751201_186_dialog_content = "Apa yang salah dengan Yoh? Dia terlihat seperti sedang kesakitan...",
  ui_story_5075_50751201_187_dialog_content = "Itu karena ini bukan apa yang sebenarnya dia inginkan.",
  ui_story_5075_50751201_188_dialog_content = "Yoh yang saya kenal peduli pada teman-temannya dan juga jenisnya sendiri. Dia tidak ingin kebenciannya menyakiti mereka atau fiendling lainnya.",
  ui_story_5075_50751201_189_dialog_content = "Lagi pula, tidak semua dari kita sejahat pendahulu kita.",
  ui_story_5075_50751201_190_dialog_content = "Aku yakin kamu melihat apa yang PlayerName coba lakukan.",
  ui_story_5075_50751201_191_dialog_content = "Jika dia adalah bagian dari Keluarga Lin saat itu... Saya yakin dia akan melakukan hal yang sama.",
  ui_story_5075_50751201_192_dialog_content = "...",
  ui_story_5075_50751201_193_dialog_content = "Keluarga Lin telah cukup lama menjebakmu.",
  ui_story_5075_50751201_194_dialog_content = "Aku tidak akan membiarkan orang lain menjebakmu dalam belenggu kebencian.",
  ui_story_5075_50751201_195_dialog_content = "Aku juga bisa mendengar suara ikan ular.",
  ui_story_5075_50751201_196_dialog_content = "Itulah sebabnya aku akan menyelamatkanmu.",
  ui_story_5075_50751201_197_dialog_content = "Tidak!",
  ui_story_5075_50751201_198_dialog_content = "Aku. Benci!",
  ui_story_5075_50751201_199_dialog_content = "Kamu. Memang. Terlalu.",
  ui_story_5075_50751201_200_dialog_content = "<size=45>Pengkhianat!</size>",
  ui_story_5075_50751202_1_dialog_content = "Bagus! Akhirnya kamu bangun juga. Anak-anak yang tidur larut bisa menghambat pertumbuhan mereka sendiri, loh.",
  ui_story_5075_50751202_2_dialog_content = "Benarkah? Jadi jika aku mulai tidur dan bangun lebih awal... Apakah aku masih bisa sedikit lebih tinggi?",
  ui_story_5075_50751202_3_dialog_content = "Kamu bisa mencoba berdoa padaku!",
  ui_story_5075_50751202_4_dialog_content = "Dan Yuebai juga.",
  ui_story_5075_50751202_5_dialog_content = "Aku bukan anak kecil lagi.",
  ui_story_5075_50751202_6_dialog_content = "Oh, kau adalah satu dibandingkan denganku.",
  ui_story_5075_50751202_7_dialog_content = "Jadi jangan cemberut terus. Lagipula, Yoh hanya tidak ingin melawanmu dan kabur.",
  ui_story_5075_50751202_8_dialog_content = "Selama dia masih di sana, sangat mudah untuk mengeluarkannya dari laut.",
  ui_story_5075_50751202_9_dialog_content = "<color=#e8d9bb>Tiba-tiba, Chen'ni mengangkat tangannya dan melemparkan sinar cahaya emas ke laut.</color>",
  ui_story_5075_50751202_10_dialog_content = "Mungkin sebaiknya aku tidak bertanya tentang apa yang baru saja kamu lakukan, benar?",
  ui_story_5075_50751202_11_dialog_content = "Yah, itu tidak penting lagi bagiku, jadi mungkin juga memecahkan sisanya segel.",
  ui_story_5075_50751202_12_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50751202_13_dialog_content = "<color=#e8d9bb>Permukaan laut yang sebelumnya tenang tiba-tiba bergolak dengan hebat, dengan ombak tinggi yang muncul.</color>",
  ui_story_5075_50751202_14_dialog_content = "<color=#e8d9bb>Sebuah sosok muncul dari lautan ke udara.</color>",
  ui_story_5075_50751202_15_dialog_content = "<color=#e8d9bb>Countless pusaran air mengoyak permukaan laut, dari mana kabut hitam yang tak terbatas muncul.</color>",
  ui_story_5075_50751202_16_dialog_content = "Apakah itu Yoh yang selama ini kamu maksud? Dia cukup muda.",
  ui_story_5075_50751202_17_dialog_content = "Aku. Mengenal. Kamu.",
  ui_story_5075_50751202_18_dialog_content = "Chen. Naga.",
  ui_story_5075_50751202_19_dialog_content = "Dia mengenalku dari amarah yang menguasainya? Itu waktu yang lama untuk menyimpan dendam.",
  ui_story_5075_50751202_20_dialog_content = "Aku. Ingin. Balas. Dendam.",
  ui_story_5075_50751202_21_dialog_content = "Jangan. Kamu. Ikut campur.",
  ui_story_5075_50751202_22_dialog_content = "Atau. Kalau tidak.",
  ui_story_5075_50751202_23_dialog_content = "Banjir. Kota.",
  ui_story_5075_50751202_24_dialog_content = "Oh, jangan bilang kamu adalah...",
  ui_story_5075_50751202_25_dialog_content = "(Ini pertama kalinya saya melihat Chen'ni seserius ini.)",
  ui_story_5075_50751202_26_dialog_content = "(Dapatkah dia benar-benar tidak melakukan apa-apa untuk Yoh?)",
  ui_story_5075_50751202_27_dialog_content = "Jadi maksudnya jika Chen'ni ikut campur, dia akan membanjiri seluruh Haojin?",
  ui_story_5075_50751202_28_dialog_content = "Dia menjadikan seluruh kota sebagai sandera.",
  ui_story_5075_50751202_29_dialog_content = "Jadi, kau...",
  ui_story_5075_50751202_30_dialog_content = "Mengancam saya?",
  ui_story_5075_50751202_31_dialog_content = "Hah?",
  ui_story_5075_50751202_32_dialog_content = "Ini keren! Tidak ada yang mengancam saya selama beberapa abad!",
  ui_story_5075_50751202_33_dialog_content = "Tapi setelah dipikirkan lagi, aku benar-benar tidak ada hubungannya dengan ini.",
  ui_story_5075_50751202_34_dialog_content = "Peristiwa-peristiwa ini terasa rumit, dan aku tidak begitu mengerti.",
  ui_story_5075_50751202_35_dialog_content = "Tapi kalian, manusia, telah memecahkan segel, dan permusuhan Yoh juga menjadi masalah antara manusia dan fiendling.",
  ui_story_5075_50751202_36_dialog_content = "Jadi, hal itu harus ditangani antara manusia dan fiendlings.",
  ui_story_5075_50751202_37_dialog_content = "Ya, kata-kataku sangat masuk akal!",
  ui_story_5075_50751202_38_dialog_content = "Ini jelas bukan saatnya bagi kamu untuk berpikir \"logis\"!",
  ui_story_5075_50751202_39_dialog_content = "Namun, sebagus apapun itu, saya tidak suka diancam.",
  ui_story_5075_50751202_40_dialog_content = "Jadi—",
  ui_story_5075_50751202_41_dialog_content = "(Chen'ni baru saja lepas landas dan terbang ke Yoh!)",
  ui_story_5075_50751202_42_dialog_content = "Duk, duk!",
  ui_story_5075_50751202_43_dialog_content = "<color=#e8d9bb>Chen'ni mengangkat tinjunya, mengetuk kepala Yoh dengan ringan.</color>",
  ui_story_5075_50751202_44_dialog_content = "Aku sedang bergerak. Apa yang akan kamu lakukan tentang itu?",
  ui_story_5075_50751202_45_dialog_content = "Chen'ni?",
  ui_story_5075_50751202_46_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50751202_47_dialog_content = "<color=#e8d9bb>Seolah ingin mengekspresikan kemarahan Yoh, permukaan laut meledak terbuka.</color>",
  ui_story_5075_50751202_48_dialog_content = "<color=#e8d9bb>Lapisan demi lapisan ombak besar muncul. Alih-alih mereda, mereka terus bertambah tinggi di tengah gema kegaduhan laut.</color>",
  ui_story_5075_50751202_49_dialog_content = "<color=#e8d9bb>Pantai tempat kita berdiri cepat terendam.</color>",
  ui_story_5075_50751202_50_dialog_content = "Dengan keadaan seperti ini, kita semua akan tenggelam!",
  ui_story_5075_50751202_51_dialog_content = "Jangan khawatir, saya cukup lincah di dalam air. Saya akan menyelamatkanmu jika kamu mulai tenggelam.",
  ui_story_5075_50751202_52_dialog_content = "Lebih baik tidak memulai proses itu sejak awal!",
  ui_story_5075_50751202_53_dialog_content = "Ups, hampir lupa tentang kalian berdua.",
  ui_story_5075_50751202_54_dialog_content = "(Kita terbang?)",
  ui_story_5075_50751202_55_dialog_content = "Kekuatan supranaturalku cukup berguna, bukan?",
  ui_story_5075_50751202_56_dialog_content = "Bagaimana dengan Yoh?",
  ui_story_5075_50751202_57_dialog_content = "Bukankah dia bilang sesuatu tentang <color=#FFB400>menenggelamkan kota</color>? Dia sedang dalam perjalanan ke Haojin sekarang.",
  ui_story_5075_50751202_58_dialog_content = "B-Bukankah itu perubahan kejadian yang jauh lebih buruk?",
  ui_story_5075_50751202_59_dialog_content = "Kenapa kamu harus memprovokasi dia seperti itu?",
  ui_story_5075_50751202_60_dialog_content = "Jangan menjadi begitu gugup, PlayerName.",
  ui_story_5075_50751202_61_dialog_content = "Saya telah hidup sangat lama dan juga telah mengamati makhluk-makhluk di Longzhou selama waktu yang lama.",
  ui_story_5075_50751202_62_dialog_content = "Apakah itu Yoh atau kamu.",
  ui_story_5075_50751202_63_dialog_content = "Jangan meremehkan mereka.",
  ui_story_5075_50751301_1_dialog_content = "Kehendak surga—",
  ui_story_5075_50751301_2_dialog_content = "Groar!",
  ui_story_5075_50751301_3_dialog_content = "Urgh, tumbangkan satu dan yang lainnya bangkit lagi.",
  ui_story_5075_50751301_4_dialog_content = "Kabut hitam di kota ini semakin tebal. Aku mulai merindukan waktu ketika aku tidak bisa melihatnya.",
  ui_story_5075_50751301_5_dialog_content = "Bahkan tali pun tidak cukup untuk mengikat makhluk-makhluk iblis yang gila ini. Andai saja aku punya cara untuk mengusir dendam dari tubuh mereka...",
  ui_story_5075_50751301_6_dialog_content = "Beri jalan! Aku punya obatnya!",
  ui_story_5075_50751301_7_dialog_content = "K-Kamu memberikan obat kepada setan kecil?",
  ui_story_5075_50751301_8_dialog_content = "Bukankah sudah jelas?",
  ui_story_5075_50751301_9_dialog_content = "Tapi, kehilangan kendali mereka bukan disebabkan oleh penyakit, melainkan korupsi yang lahir dari dendam—",
  ui_story_5075_50751301_10_dialog_content = "Jadi menurutmu, dokter hanya bisa mengobati penyakit?",
  ui_story_5075_50751301_11_dialog_content = "Karena energi itu harus masuk ke dalam fiendling untuk berpengaruh, itu bisa disamakan dengan toksin.",
  ui_story_5075_50751301_12_dialog_content = "Dan ada obat untuk setiap toksin.",
  ui_story_5075_50751301_13_dialog_content = "Kabut gelap telah merasuki kota. Bahkan Tinytail... saudaraku terkena dampaknya.",
  ui_story_5075_50751301_14_dialog_content = "Tapi saya mendapatkan ramuan untuk menyeimbangkan Lumina dalam diri dari guru saya untuknya. Dia menjadi jauh lebih baik setelah meminumnya.",
  ui_story_5075_50751301_15_dialog_content = "Itu sebabnya aku berlari di luar dan mencoba untuk membantu.",
  ui_story_5075_50751301_16_dialog_content = "Ha.",
  ui_story_5075_50751301_17_dialog_content = "Saudaramu... Begitu ya? Lalu itu berarti kamu juga seorang <color=#FFB400>fiendling</color>.",
  ui_story_5075_50751301_18_dialog_content = "Apa, kamu punya masalah dengan fiendlings?",
  ui_story_5075_50751301_19_dialog_content = "Sama sekali tidak! Saya hanya berpikir bahwa Anda adalah dokter yang sangat luar biasa.",
  ui_story_5075_50751301_20_dialog_content = "Kamu benar-benar berpikir begitu? Yah, setidaknya kamu mengenali bakat ketika kamu melihatnya.",
  ui_story_5075_50751301_21_dialog_content = "Tapi sebenarnya, aku tidak begitu istimewa...",
  ui_story_5075_50751301_22_dialog_content = "Aku punya obatnya, tapi para fiendlings sedang berlarian dan membuatku sulit untuk memberikannya kepada mereka.",
  ui_story_5075_50751301_23_dialog_content = "Serahkan itu padaku!",
  ui_story_5075_50751301_24_dialog_content = "Aku akan menjatuhkan setiap iblis kecil yang kulihat dan membawanya kepadamu untuk diobati!",
  ui_story_5075_50751301_25_dialog_content = "Diam, jangan terlalu keras!",
  ui_story_5075_50751301_26_dialog_content = "Kami meloloskan diri sendiri. Kita akan berada dalam masalah besar jika kita tertangkap.",
  ui_story_5075_50751301_27_dialog_content = "Oh, mengerti! Saya juga biasa melakukan hal seperti ini ketika saya masih kecil.",
  ui_story_5075_50751301_28_dialog_content = "Jangan khawatir, aku akan berjaga dan memastikan tidak ada yang melihatmu.",
  ui_story_5075_50751301_29_dialog_content = "Nama saya Luo Song, dan ini adalah teman saya, Ah Ding.",
  ui_story_5075_50751301_30_dialog_content = "Groar!",
  ui_story_5075_50751301_31_dialog_content = "Saya Liqing, dan ini Tinytail, kakak laki-laki saya.",
  ui_story_5075_50751301_32_dialog_content = "Ha.",
  ui_story_5075_50751301_33_dialog_content = "Senang bekerja dengan Anda!",
  ui_story_5075_50751301_34_dialog_content = "Ha-howl!",
  ui_story_5075_50751301_35_dialog_content = "Ciit!",
  ui_story_5075_50751301_36_dialog_content = "Tunggu saja di sini untukku, Dr. Liqing. Aku akan pergi memeriksa ke depan!",
  ui_story_5075_50751301_37_dialog_content = "Hei, tunggu!",
  ui_story_5075_50751301_38_dialog_content = "Tidak bisakah kamu bersabar?",
  ui_story_5075_50751301_39_dialog_content = "Tolong... Saya butuh bantuan!",
  ui_story_5075_50751301_40_dialog_content = "Mundur! Tongkat di tanganku ini bukan untuk dipamerkan!",
  ui_story_5075_50751301_41_dialog_content = "Ciit!",
  ui_story_5075_50751301_42_dialog_content = "Kalian monster, jangan berpikir kami mudah untuk diintimidasi! Ha-ah!",
  ui_story_5075_50751301_43_dialog_content = "Berhenti, kalian semua! Urgh—",
  ui_story_5075_50751301_44_dialog_content = "Luo Song!",
  ui_story_5075_50751301_45_dialog_content = "Apa yang sedang kamu lakukan? Siapa yang menyuruhmu menerjang ke tengah-tengah mereka?",
  ui_story_5075_50751301_46_dialog_content = "Bagus, sekarang kamu mendapatkan pukulan di bahu dan tinju di perut.",
  ui_story_5075_50751301_47_dialog_content = "Haha, ini situasi darurat, bukan?",
  ui_story_5075_50751301_48_dialog_content = "Aku baik-baik saja, jadi berikan saja obat pada makhluk kecil ini sementara aku menahannya.",
  ui_story_5075_50751301_49_dialog_content = "... Saya tidak bisa menentukan apakah kamu berhati-hati atau ceroboh.",
  ui_story_5075_50751301_50_dialog_content = "Aku, maksudku, maaf... telah memukulmu...",
  ui_story_5075_50751301_51_dialog_content = "Jangan khawatir tentang itu. Saya lah yang tiba-tiba melompat di antara kalian semua.",
  ui_story_5075_50751301_52_dialog_content = "Tapi, tapi itu seorang fiendling! Kenapa kamu membela dia?",
  ui_story_5075_50751301_53_dialog_content = "Sebenarnya, dia sedang membela kamu!",
  ui_story_5075_50751301_54_dialog_content = "Oh...",
  ui_story_5075_50751301_55_dialog_content = "Sangat normal jika seseorang melawan saat diserang oleh fiendling. Tapi perlu diketahui bahwa bukanlah niat fiendling untuk menyerang orang.",
  ui_story_5075_50751301_56_dialog_content = "Mereka semua adalah korban yang tidak bersalah, sama sepertimu.",
  ui_story_5075_50751301_57_dialog_content = "Dan karena tidak ada yang bersalah di sini, tidak seharusnya ada yang terluka.",
  ui_story_5075_50751301_58_dialog_content = "Bukankah seharusnya begitu?",
  ui_story_5075_50751301_59_dialog_content = "Baiklah, fiendling ini jauh lebih baik setelah diobati.",
  ui_story_5075_50751301_60_dialog_content = "Kita pasti sudah menjangkau sebagian besar Haojin dan menyembuhkan sebagian besar fiendlings sampai sekarang.",
  ui_story_5075_50751301_61_dialog_content = "Grr.",
  ui_story_5075_50751301_62_dialog_content = "Lihat itu? Mereka dimanipulasi untuk menyerang orang, dan mereka menjadi sangat jinak begitu kembali normal.",
  ui_story_5075_50751301_63_dialog_content = "... Jika ini milik orang lain, saya tidak akan membelinya.",
  ui_story_5075_50751301_64_dialog_content = "Tapi karena itu datang dari Anda, saya pikir itu benar.",
  ui_story_5075_50751301_65_dialog_content = "Terima kasih telah menyelamatkan hidup saya! Saya akan menyebarkan kabar ini dan memberitahu mereka untuk mencari bantuanmu jika ada iblis yang menyakiti seseorang.",
  ui_story_5075_50751301_66_dialog_content = "Benarkah? Sangat dihargai, terima kasih!",
  ui_story_5075_50751301_67_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50751301_68_dialog_content = "Apa yang terjadi? Kenapa langit tiba-tiba menjadi begitu gelap?",
  ui_story_5075_50751301_69_dialog_content = "<color=#e8d9bb>Tik-tik-tik.</color>",
  ui_story_5075_50751301_70_dialog_content = "Hujan, ya?",
  ui_story_5075_50751301_71_dialog_content = "Tunggu, ini bukan hujan.",
  ui_story_5075_50751301_72_dialog_content = "<size=45>Malam pun tidak jatuh. Sebuah ombak raksasa menutupi langit.</size>",
  ui_story_5075_50751301_73_dialog_content = "<size=45>Apakah Haojin sedang dilanda banjir?</size>",
  ui_story_5075_50751302_1_dialog_content = "<color=#e8d9bb>Jalan-jalan dipenuhi oleh orang-orang yang melarikan diri dalam kepanikan.</color>",
  ui_story_5075_50751302_2_dialog_content = "Roh jahat! Roh-roh jahat itu membawa banjir untuk menenggelamkan kita semua!",
  ui_story_5075_50751302_3_dialog_content = "LARI—",
  ui_story_5075_50751302_4_dialog_content = "Dragon Maiden, tolong lindungi kami. Dragon Maiden, tolong bantu kami...",
  ui_story_5075_50751302_5_dialog_content = "Ini bukan lagi masalah yang bisa kita selesaikan sendiri.",
  ui_story_5075_50751302_6_dialog_content = "Turunkan kami, Chen'ni! Setidaknya biarkan kami membantu orang-orang itu sampai ke tempat yang aman!",
  ui_story_5075_50751302_7_dialog_content = "Nyonya Chen'ni.",
  ui_story_5075_50751302_8_dialog_content = "Saya rasa itu tidak perlu.",
  ui_story_5075_50751302_9_dialog_content = "Tapi—",
  ui_story_5075_50751302_10_dialog_content = "Dengarkan dengan saksama, PlayerName.",
  ui_story_5075_50751302_11_dialog_content = "Aduh! Tersandung batu bata... Sakit sekali.",
  ui_story_5075_50751302_12_dialog_content = "Tempat apa ini... Dimana Ibu dan Ayah?",
  ui_story_5075_50751302_13_dialog_content = "*Menangis*",
  ui_story_5075_50751302_14_dialog_content = "Graah!",
  ui_story_5075_50751302_15_dialog_content = "Tolong! Seseorang selamatkan aku!",
  ui_story_5075_50751302_16_dialog_content = "Ciit!",
  ui_story_5075_50751302_17_dialog_content = "<color=#e8d9bb>Tepat sebelum serangan Eclipsite mendarat, si fiendling bergegas datang dan menepisnya.</color>",
  ui_story_5075_50751302_18_dialog_content = "<color=#e8d9bb>Serangan itu sedikit menyimpang dari jalur dan meleset.</color>",
  ui_story_5075_50751302_19_dialog_content = "Tunggu, kamu...",
  ui_story_5075_50751302_20_dialog_content = "Yang ini tidak cukup keras. Ambil yang lain!",
  ui_story_5075_50751302_21_dialog_content = "Petasan meledak, mengusir setan kecil, menghilangkan kesialan dengan cara yang ceria!",
  ui_story_5075_50751302_22_dialog_content = "Mencicit...",
  ui_story_5075_50751302_23_dialog_content = "Kamu dari masa lalu...",
  ui_story_5075_50751302_24_dialog_content = "Graah!",
  ui_story_5075_50751302_25_dialog_content = "Awas!",
  ui_story_5075_50751302_26_dialog_content = "<color=#e8d9bb>Bocah itu berlari ke depan, mengangkat si kecil yang nakal, dan berguling ke tanah yang dipenuhi lumpur.</color>",
  ui_story_5075_50751302_27_dialog_content = "Ah Ding! Serang sekarang!",
  ui_story_5075_50751302_28_dialog_content = "Grr...",
  ui_story_5075_50751302_29_dialog_content = "Hah? Bukankah kamu anak itu dari sebelumnya?",
  ui_story_5075_50751302_30_dialog_content = "Air... Sedang turun deras!",
  ui_story_5075_50751302_31_dialog_content = "Ciit!",
  ui_story_5075_50751302_32_dialog_content = "Tunggu, jangan tinggalkan aku!",
  ui_story_5075_50751302_33_dialog_content = "<color=#e8d9bb>Seolah-olah langit runtuh.</color>",
  ui_story_5075_50751302_34_dialog_content = "<color=#e8d9bb>Dengan suara gemuruh, gelombang besar akhirnya menerjang dari atas.</color>",
  ui_story_5075_50751302_35_dialog_content = "<color=#e8d9bb>Menghadapi kekuatan yang luar biasa, kota kecil yang dibangun oleh Aurorian di tanah ini benar-benar tak berdaya.</color>",
  ui_story_5075_50751302_36_dialog_content = "Ahhhhhhhh!",
  ui_story_5075_50751302_37_dialog_content = "...",
  ui_story_5075_50751302_38_dialog_content = "Aku, aku tidak mati? Apa yang terjadi?",
  ui_story_5075_50751302_39_dialog_content = "... Lihat ke atas sana.",
  ui_story_5075_50751302_40_dialog_content = "Ciit!",
  ui_story_5075_50751302_41_dialog_content = "<color=#e8d9bb>Fiendling kecil melayang di udara, menciptakan penghalang yang tak terlihat di atas.</color>",
  ui_story_5075_50751302_42_dialog_content = "<color=#e8d9bb>Ini menahan gelombang tepat di depan.</color>",
  ui_story_5075_50751302_43_dialog_content = "<color=#e8d9bb>Dalam tekanan, fiendling itu gemetar, tetapi masih mengangkat cakarnya yang kecil, menahan barier pelindung itu.</color>",
  ui_story_5075_50751302_44_dialog_content = "<color=#e8d9bb>Kemudian, penghalang lain muncul tidak jauh dari sana.</color>",
  ui_story_5075_50751302_45_dialog_content = "Groar!",
  ui_story_5075_50751302_46_dialog_content = "<color=#e8d9bb>Dan kemudian, satu lagi.</color>",
  ui_story_5075_50751302_47_dialog_content = "<color=#e8d9bb>Penghalang yang dibuat oleh fiendlings saling menyilang untuk menutupi wilayah yang luas.</color>",
  ui_story_5075_50751302_48_dialog_content = "<color=#e8d9bb>Gelombang, seberat seribu ton, menekan Kota Haojin, tetapi mereka tidak bisa maju sedikit pun.</color>",
  ui_story_5075_50751302_49_dialog_content = "Itu…?",
  ui_story_5075_50751302_50_dialog_content = "Tanah ini tidak pernah hanya milik Aurorian saja.",
  ui_story_5075_50751302_51_dialog_content = "Fiendlings juga harus melindungi rumah mereka.",
  ui_story_5075_50751302_52_dialog_content = "Bahkan jika si tua Lin itu tidak mencarinya, Yoh pasti akan memeriksa segel itu untuk teman-temannya.",
  ui_story_5075_50751302_53_dialog_content = "Sebagian besar Aurorian tidak ingin mengakuinya, tetapi fiendling juga memiliki hak atas tanah tersebut.",
  ui_story_5075_50751302_54_dialog_content = "Apakah Anda mendengarkan, PlayerName?",
  ui_story_5075_50751302_55_dialog_content = "Ya, aku mendengar itu.",
  ui_story_5075_50751302_56_dialog_content = "Dan aku pikir semua orang juga harus mendengar itu.",
  ui_story_5075_50751302_57_dialog_content = "Yah, saya pasti bisa membantu menyampaikan pesan.",
  ui_story_5075_50751302_58_dialog_content = "Ayo kita lakukan!",
  ui_story_5075_50751302_59_option_content = "Pemindaian Psikis!",
  ui_story_5075_50751302_60_dialog_content = "Dua kaki itu, mereka jahat, selalu menendang kita saat mereka melihat kita.",
  ui_story_5075_50751302_61_dialog_content = "Tapi yang berkaki dua juga bagus, karena mereka bisa menangkap mangsa yang lezat.",
  ui_story_5075_50751302_62_dialog_content = "Mereka kadang-kadang berbagi makanan mereka dengan kita.",
  ui_story_5075_50751302_63_dialog_content = "Eh, apa ini?",
  ui_story_5075_50751302_64_dialog_content = "Apakah ini suara... dari fiendlings?",
  ui_story_5075_50751302_65_dialog_content = "Meledak karena benda panas, menakutkan.",
  ui_story_5075_50751302_66_dialog_content = "Diusir, menakutkan.",
  ui_story_5075_50751302_67_dialog_content = "Tempat ini juga rumah kita.",
  ui_story_5075_50751302_68_dialog_content = "Tapi kami juga takut! Kalian selalu mencuri barang dan merusak makanan kami.",
  ui_story_5075_50751302_69_dialog_content = "Dan kalian bahkan menggunakan sihir yang tidak bisa kami gunakan! K-Kami tidak tahu bagaimana cara menghadapi kalian!",
  ui_story_5075_50751302_70_dialog_content = "Dua kaki itu, bodoh. Mereka meninggalkan barang di sudut, tidak bisa menemukannya, dan menyalahkan kami.",
  ui_story_5075_50751302_71_dialog_content = "Dua kaki itu, sangat bodoh. Mereka meninggalkan makanan di halaman tapi tidak meninggalkan tanda, dan akhirnya dimakan oleh yang lain.",
  ui_story_5075_50751302_72_dialog_content = "Tapi mereka yang memiliki dua kaki juga pintar. Terakhir kali ketika kakiku terluka, mereka menggunakan papan untuk menyangganya, dan itu menjadi lebih baik.",
  ui_story_5075_50751302_73_dialog_content = "Apakah kita terlalu kasar pada mereka...",
  ui_story_5075_50751302_74_dialog_content = "Ya, mereka disebut fiendlings, tetapi sebenarnya, mereka hanyalah makhluk liar yang baru-baru ini mulai mengerti hal-hal.",
  ui_story_5075_50751302_75_dialog_content = "Mereka keduanya bodoh dan pintar. Mereka jahat, namun baik hati. Mereka memukul kita dan minta maaf. Makhluk berdua kaki itu benar-benar aneh.",
  ui_story_5075_50751302_76_dialog_content = "Tapi tidak ada yang bisa kita lakukan.",
  ui_story_5075_50751302_77_dialog_content = "Tidak ada yang bisa kita lakukan.",
  ui_story_5075_50751302_78_dialog_content = "Kita berbagi rumah, bagaimanapun.",
  ui_story_5075_50751302_79_dialog_content = "Air datang, dan mereka tidak bisa melarikan diri.",
  ui_story_5075_50751302_80_dialog_content = "Air datang, dan rumah pun tidak bisa lolos juga.",
  ui_story_5075_50751302_81_dialog_content = "Air itu buruk. Pergi saja—",
  ui_story_5075_50751302_82_dialog_content = "Jauhi—",
  ui_story_5075_50751302_83_dialog_content = "<size=45>Rumah KITA!</size>",
  ui_story_5075_50751302_84_dialog_content = "<color=#e8d9bb>Pada penghalang yang melingkupi seluruh kota, tiba-tiba ada cahaya emas yang berputar, dan ombak yang tidak bisa jatuh tersebar oleh kekuatan ledakan.</color>",
  ui_story_5075_50751302_85_dialog_content = "<color=#e8d9bb>Mereka berubah menjadi hujan yang pahit, perlahan-lahan mengguyur Haojin.</color>",
  ui_story_5075_50751302_86_dialog_content = "Hujan tadi... Itu kau yang lakukan, Chen'ni?",
  ui_story_5075_50751302_87_dialog_content = "Apa?",
  ui_story_5075_50751302_88_dialog_content = "Uh... Sudahlah.",
  ui_story_5075_50751302_89_dialog_content = "Fiendling kecil itu benar-benar mengesankan.",
  ui_story_5075_50751302_90_dialog_content = "Sekarang semua yang tersisa adalah untuk menangani Yoh.",
  ui_story_5075_50751302_91_dialog_content = "...",
  ui_story_5075_50751302_92_dialog_content = "Kamu juga mendengarnya, 'kan? Hati semua orang dan makhluk jahat itu?",
  ui_story_5075_50751302_93_dialog_content = "Mereka mungkin membuat kesalahan dan bertengkar dari waktu ke waktu, atau bahkan saling menyakiti karena berbagai alasan.",
  ui_story_5075_50751302_94_dialog_content = "Tapi mereka juga bekerja sama dan saling membantu, sehingga mereka bisa hidup berdampingan di dunia ini.",
  ui_story_5075_50751302_95_dialog_content = "Semua dari mereka adalah makhluk hidup yang lahir di Longzhou. Mereka tidak memiliki alasan untuk saling membenci, baik secara alami maupun sebaliknya.",
  ui_story_5075_50751302_96_dialog_content = "Itulah sebabnya, setidaknya, tidak seharusnya salah satu dari mereka harus mati agar yang lainnya bisa hidup.",
  ui_story_5075_50751302_97_dialog_content = "Lalu…",
  ui_story_5075_50751302_98_dialog_content = "Diantara semua suara tadi, aku mendengar permintaan maaf yang ditujukan hanya untukmu.",
  ui_story_5075_50751302_99_dialog_content = "Yoh.",
  ui_story_5075_50751302_100_dialog_content = "Maaf.",
  ui_story_5075_50751401_1_dialog_content = "Minta maaf.",
  ui_story_5075_50751401_2_dialog_content = "Kenapa.",
  ui_story_5075_50751401_3_dialog_content = "Tentu saja!",
  ui_story_5075_50751401_4_dialog_content = "Tidak. Penyesalan.",
  ui_story_5075_50751401_5_dialog_content = "Tidak... Argh!",
  ui_story_5075_50751401_6_dialog_content = "Dia terbang kembali ke teluk! Kejar dia!",
  ui_story_5075_50751401_7_dialog_content = "Yoh!",
  ui_story_5075_50751401_8_dialog_content = "Terkejut hanya oleh satu atau dua kata... Sungguh pengecut!",
  ui_story_5075_50751401_9_dialog_content = "Tidak... Argh!",
  ui_story_5075_50751401_10_dialog_content = "Jika ini adalah tingkat kebencian yang bisa kamu lakukan, lebih baik kamu serahkan tubuhmu padaku!",
  ui_story_5075_50751401_11_dialog_content = "Yoh... Dia sedang melawan kendali kabut hitam!",
  ui_story_5075_50751401_12_dialog_content = "(Artinya, kita mungkin memiliki kesempatan sekarang!)",
  ui_story_5075_50751401_13_dialog_content = "Humph. Tubuhnya lumayan, tapi tekadnya terlalu lemah.",
  ui_story_5075_50751401_14_dialog_content = "Betapa memalukannya seorang fiendling bisa dengan mudah dimanipulasi oleh Aurorian.",
  ui_story_5075_50751401_15_dialog_content = "Sudah lama, Chen'ni.",
  ui_story_5075_50751401_16_dialog_content = "Tidak juga. Hanya dua kali tidur siang.",
  ui_story_5075_50751401_17_dialog_content = "Kamu masih dirimu yang dulu.",
  ui_story_5075_50751401_18_dialog_content = "Sangat sulit bagi kami untuk berubah meski kami ingin.",
  ui_story_5075_50751401_19_dialog_content = "Di sisi lain, dunia fana ini memang berubah banyak, yang pastinya kamu lewatkan saat berada di laut selama ini.",
  ui_story_5075_50751401_20_dialog_content = "Mereka memiliki burung mekanik dengan pelacak otomatis, lukisan barat yang penuh warna, dan kapal yang bisa menyeberangi samudra.",
  ui_story_5075_50751401_21_dialog_content = "Humph. Tidak peduli seberapa baik mereka mencipta, mereka tetap tidak lebih dari makhluk yang rendah.",
  ui_story_5075_50751401_22_dialog_content = "Apakah kamu menilai itu berdasarkan umur hidup?",
  ui_story_5075_50751401_23_dialog_content = "Tidakkah menurutmu itu aneh?",
  ui_story_5075_50751401_24_dialog_content = "Aurorian memiliki umur yang pendek, tetapi mereka lah yang sekarang mendominasi benua ini.",
  ui_story_5075_50751401_25_dialog_content = "Sebaliknya, bentuk kehidupan yang superior seperti kita—menurutmu—jarang sekali ditemui.",
  ui_story_5075_50751401_26_dialog_content = "Haruskah kamu merendahkan dirimu seperti ini?",
  ui_story_5075_50751401_27_dialog_content = "Kami fiendlings mulia memiliki garis keturunan yang sama dengan yang <color=#FFB400>Primordial</color>.. Aurorian rendahan tidak pantas disebut dalam kalimat yang sama dengan kami!",
  ui_story_5075_50751401_28_dialog_content = "Tapi sekarang, bahkan seorang Aurorian yang tak berdaya bisa mengejek dan bermain-main dengan fiendlings!",
  ui_story_5075_50751401_29_dialog_content = "Apakah kamu hanya akan mengabaikan betapa seriusnya situasi ini?",
  ui_story_5075_50751401_30_dialog_content = "Kekuatan dan garis keturunan Fiendlings berkuasa tertinggi atas Aurorian.",
  ui_story_5075_50751401_31_dialog_content = "Mengapa kita harus merendahkan diri dan berbagi Longzhou dengan mereka?",
  ui_story_5075_50751401_32_option_content = "Force Boost!",
  ui_story_5075_50751401_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5075_50751401_34_dialog_content = "Force Boost!",
  ui_story_5075_50751401_35_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5075_50751401_36_dialog_content = "(Tidak ada gunanya, aku hampir tidak bisa merasakan keberadaan Yoh yang sebenarnya. Tidak ada cara untuk menjangkaunya sekarang.)",
  ui_story_5075_50751401_37_dialog_content = "PlayerName, bisakah kamu mengirimkan pikiranku ke pikiran Yoh?",
  ui_story_5075_50751401_38_dialog_content = "Aku akan mencoba yang terbaik, tapi aku tidak yakin dia bisa mendengar kita dalam kondisinya.",
  ui_story_5075_50751401_39_dialog_content = "Baiklah.",
  ui_story_5075_50751401_40_dialog_content = "Sebagai penghuni kedalaman lautan yang luas, ikan ular tidak akan tenggelam begitu mudah.",
  ui_story_5075_50751401_41_dialog_content = "Baiklah kalau begitu, persiapkan dirimu.",
  ui_story_5075_50751401_42_option_content = "Force Boost!",
  ui_story_5075_50751401_43_dialog_content = "Yoh, bisa dengar aku?",
  ui_story_5075_50751401_44_dialog_content = "...",
  ui_story_5075_50751401_45_dialog_content = "Sebelum saya pergi, Guildmaster mengatakan bahwa dia belum pernah meminta maaf kepada Anda secara langsung.",
  ui_story_5075_50751401_46_dialog_content = "Dia mengatakan dengan begitu, dia akan memaksa kamu untuk menoleransi perilaku tercelanya dari kebaikan hati kamu.",
  ui_story_5075_50751401_47_dialog_content = "Karena dia melakukan itu dengan sengaja dan menerima hasil jarahan dari kejahatan tersebut, dia tidak memiliki hak untuk meminta maaf.",
  ui_story_5075_50751401_48_dialog_content = "Itu juga benar tentang keluarga Lin.",
  ui_story_5075_50751401_49_dialog_content = "Jika kamu percaya bahwa saya juga pengkhianat terhadap leluhur serpentfish saya, maka tentu saja itu juga termasuk saya.",
  ui_story_5075_50751401_50_dialog_content = "Lakukan balas dendammu sebagaimana yang kamu inginkan, dan kami akan menerimanya.",
  ui_story_5075_50751401_51_dialog_content = "Tapi itu harus dari kamu dan hanya kamu, tanpa manipulasi orang lain, secara pribadi.",
  ui_story_5075_50751401_52_dialog_content = "Ataukah dendam yang dipegang oleh ikan ular begitu tidak berarti sehingga Anda akan mempercayakannya kepada orang lain?",
  ui_story_5075_50751401_53_dialog_content = "Tidak.",
  ui_story_5075_50751401_54_dialog_content = "Aku mendapatkan tanggapan!",
  ui_story_5075_50751401_55_dialog_content = "Yoh, aku akan mencoba mengusir pikiran negatif yang mengendalikan tubuhmu.",
  ui_story_5075_50751401_56_dialog_content = "Tolong coba untuk bekerja sama denganku!",
  ui_story_5075_50751401_57_dialog_content = "PlayerName dan Yuebai benar-benar lambat.",
  ui_story_5075_50751401_58_dialog_content = "Apa katamu?",
  ui_story_5075_50751401_59_dialog_content = "Saya bilang, saya tidak ingin berbicara denganmu lagi.",
  ui_story_5075_50751401_60_dialog_content = "Kenapa kamu...",
  ui_story_5075_50751401_61_dialog_content = "Hentikan sandiwara itu. Kamu bukan kerabatku.",
  ui_story_5075_50751401_62_dialog_content = "Kamu bukan saudaraku.",
  ui_story_5075_50751401_63_dialog_content = "!",
  ui_story_5075_50751401_64_dialog_content = "Ketika saya pertama kali bangun, saya mencoba menghubungi rekan-rekan saya.",
  ui_story_5075_50751401_65_dialog_content = "Tapi semua orang masih tertidur. Dari Longzhou ke Cloud Island, sangat sedikit yang merespon.",
  ui_story_5075_50751401_66_dialog_content = "Jadi, satu-satunya alasan saya berbicara denganmu adalah karena kamu memiliki aura naga hitam.",
  ui_story_5075_50751401_67_dialog_content = "Tapi kamu sama sekali bukan naga hitam itu, hanya kumpulan emosi negatif yang mencuri beberapa kenangan dari wadahmu.",
  ui_story_5075_50751401_68_dialog_content = "Kamu hanya meninggalkan kesombongan di Black Dragon dan hanya kebencian di Yoh.",
  ui_story_5075_50751401_69_dialog_content = "Itu karena hanya dua hal itu saja yang kamu miliki.",
  ui_story_5075_50751401_70_dialog_content = "Kamu terus menekankan tentang persaudaraan sebangsa, namun tidak memiliki simpati untuk setan-setan kecil.",
  ui_story_5075_50751401_71_dialog_content = "Anda mengaku sebagai bangsawan, namun hanya berpegang teguh pada pengecutan.",
  ui_story_5075_50751401_72_dialog_content = "Kamu bahkan tidak memiliki kepribadian untuk dibicarakan dan bersembunyi di balik topeng.",
  ui_story_5075_50751401_73_dialog_content = "Apakah Anda benar-benar percaya bahwa Anda bisa mengklaim diri sebagai makhluk hidup yang lebih tinggi?",
  ui_story_5075_50751401_74_dialog_content = "Apa salahnya tidak memiliki kepribadian? Aku adalah abadi yang sejati!",
  ui_story_5075_50751401_75_dialog_content = "Bahkan para dewa yang disebut-sebut seperti kamu tidak bisa menandingi umur panjangku! Aku...",
  ui_story_5075_50751401_76_dialog_content = "Sekarang, sebelum ia mendapatkan kembali ketenangannya!",
  ui_story_5075_50751401_77_option_content = "Force Boost!",
  ui_story_5075_50751401_78_dialog_content = "Ini. Adalah. Tubuhku.",
  ui_story_5075_50751401_79_dialog_content = "Keluar. Sekarang!",
  ui_story_5075_50751401_80_dialog_content = "Argh!",
  ui_story_5075_50751401_81_dialog_content = "Apa?",
  ui_story_5075_50751401_82_dialog_content = "Berkat gangguanmu, Chen'ni, kami bisa menemukannya!",
  ui_story_5075_50751401_83_dialog_content = "Sekarang kita hanya perlu membantu Yoh mengusirnya dari dalam...",
  ui_story_5075_50751401_84_dialog_content = "Pikirkan lagi!",
  ui_story_5075_50751402_1_dialog_content = "Tsk, tsk... Hanya cangkang yang tak berguna. Apa gunanya jika saya mengembalikannya kepada kamu?",
  ui_story_5075_50751402_2_dialog_content = "Ini adalah tempat di mana tubuh asliku dimakamkan.",
  ui_story_5075_50751402_3_dialog_content = "Bahkan dalam keadaan ini, aku bukan sesuatu yang bisa kamu tangani!",
  ui_story_5075_50751402_4_dialog_content = "<color=#e8d9bb>Laut di kejauhan kembali bergolak.</color>",
  ui_story_5075_50751402_5_dialog_content = "(Tapi saya menolak untuk melihat Haojin di bawah air lagi.)",
  ui_story_5075_50751402_6_dialog_content = "Chen'ni, kamu bilang aku bisa menggunakan ini untuk meminta sebuah keinginan, benar?",
  ui_story_5075_50751402_7_dialog_content = "Oh?",
  ui_story_5075_50751402_8_dialog_content = "Apa keinginan yang ada di pikiranmu?",
  ui_story_5075_50751402_9_dialog_content = "Itu bukan Aurorian atau fiendling, bahkan bukan Eclipsite.",
  ui_story_5075_50751402_10_dialog_content = "Ini tidak lebih dari sekadar massa niat jahat yang tidak berwujud.",
  ui_story_5075_50751402_11_dialog_content = "O Maha Kuasa Naga Kebajikan, bisakah Anda tolong hapus kejahatan ini dan kembalikan kedamaian ke tempat ini sekali lagi?",
  ui_story_5075_50751402_12_dialog_content = "Dikabulkan.",
  ui_story_5075_50751402_13_dialog_content = "Tsk, tsk... Sudah delapan ratus tahun, dan Gadis Naga baik hatimu itu tidak bergerak sedikit pun saat aku membanjiri Haojin.",
  ui_story_5075_50751402_14_dialog_content = "Penyajian pasti kurang, jadi dia mengalami penurunan kekuatan—",
  ui_story_5075_50751402_15_dialog_content = "<color=#e8d9bb>Dalam sekejap, teratai emas memancarkan kilauan yang cemerlang.</color>",
  ui_story_5075_50751402_16_dialog_content = "<color=#e8d9bb>Sebuah sosok yang jernih seperti kristal, muncul di antara laut dan langit.</color>",
  ui_story_5075_50751402_17_dialog_content = "<color=#e8d9bb>Cahaya emas yang indah menyebar seperti gelombang, dan di mana pun ia mencapai, roh jahat menghilang begitu saja.</color>",
  ui_story_5075_50751402_18_dialog_content = "<color=#e8d9bb>Di dalam Kota Haojin</color>",
  ui_story_5075_50751402_19_dialog_content = "Groar...",
  ui_story_5075_50751402_20_dialog_content = "Roh-roh jahat di kota... Mereka semua telah menghilang?",
  ui_story_5075_50751402_21_dialog_content = "Lihat! Lihat ke langit!",
  ui_story_5075_50751402_22_dialog_content = "Ini Dragon Maiden! Dragon Maiden telah muncul, membantu kita menangkal kejahatan!",
  ui_story_5075_50751402_23_dialog_content = "<color=#e8d9bb>Sisa-sisa Eclipsite, yang berwujud naga hitam, berbalik dan lari tanpa ragu-ragu.</color>",
  ui_story_5075_50751402_24_dialog_content = "<color=#e8d9bb>Hanya untuk sosok etereal itu melumpuhkannya dengan sekadar menggerakkan jari.</color>",
  ui_story_5075_50751402_25_dialog_content = "Jika kamu percaya aku telah melemah, mengapa kamu takut untuk bertarung?",
  ui_story_5075_50751402_26_dialog_content = "Ck, ck, ck...",
  ui_story_5075_50751402_27_dialog_content = "Tak pernah terpikir bahwa setelah sekian lama, kau masih mempertahankan tingkat kekuatan ini.",
  ui_story_5075_50751402_28_dialog_content = "Tapi kamu belum menang!",
  ui_story_5075_50751402_29_dialog_content = "Selama kekuatan Archlord Eclipsite masih ada, saya praktis abadi!",
  ui_story_5075_50751402_30_dialog_content = "Jika kamu merusak bagian ini dariku, kekuatanku hanya akan berkumpul kembali dan menghidupkanku lagi.",
  ui_story_5075_50751402_31_dialog_content = "Anda mungkin bisa mengalahkan saya sekali atau dua kali, tapi bisakah Anda terus menyingkirkan saya ribuan atau sepuluh ribu kali?",
  ui_story_5075_50751402_32_dialog_content = "Aku—",
  ui_story_5075_50751402_33_dialog_content = "<color=#e8d9bb>Itu tidak bisa menyelesaikan kalimatnya.</color>",
  ui_story_5075_50751402_34_dialog_content = "Hal-hal tanpa pikiran dan bentuk tidak perlu ada di dunia.",
  ui_story_5075_50751402_35_dialog_content = "<color=#e8d9bb>Figur etereal itu menghancurkannya.</color>",
  ui_story_5075_50751402_36_dialog_content = "<color=#e8d9bb>Saat berikutnya, kabut hitam kembali melanda laut.</color>",
  ui_story_5075_50751402_37_dialog_content = "<color=#e8d9bb>Kesalahan dan Darkflow menyatu menjadi inti yang keruh di tengah kabut hitam, cepat mengambil bentuk.</color>",
  ui_story_5075_50751402_38_dialog_content = "Aku benci mengakuinya, tapi dia benar. Tidak ada cara kita bisa menjaga tempat ini selamanya.",
  ui_story_5075_50751402_39_dialog_content = "Tanpa solusi permanen, kita tidak bisa menjamin tidak ada yang akan terluka lain kali, dan setelah itu...",
  ui_story_5075_50751402_40_dialog_content = "Anda berada di pihak siapa, PlayerName?",
  ui_story_5075_50751402_41_dialog_content = "Namun…",
  ui_story_5075_50751402_42_dialog_content = "Selama ribuan tahun, dikatakan saya melindungi kapal-kapal yang berlayar di laut.",
  ui_story_5075_50751402_43_dialog_content = "Tapi dalam seratus tahun terakhir sebelum saya terbangun, manusia terus berlayar.",
  ui_story_5075_50751402_44_dialog_content = "Mereka mampu melindungi diri mereka sendiri tanpa campur tangan ilahi.",
  ui_story_5075_50751402_45_dialog_content = "Itulah yang ingin kudengar!",
  ui_story_5075_50751402_46_dialog_content = "Suara itu...",
  ui_story_5075_50751402_47_dialog_content = "Xuan Ji!",
  ui_story_5075_50751402_48_dialog_content = "Lama tidak bertemu, PlayerName.",
  ui_story_5075_50751402_49_dialog_content = "Saya lihat saya berhasil tepat waktu untuk penutupnya.",
  ui_story_5075_50751402_50_dialog_content = "Biarkan aku menunjukkan hal keren terbaru dari Kerajaan Ye!",
  ui_story_5075_50751402_51_dialog_content = "Operasi stabil. Target terkunci. Kekuatan maksimal.",
  ui_story_5075_50751402_52_dialog_content = "<size=45>Api!</size>",
  ui_story_5075_50751402_53_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50751402_54_dialog_content = "<color=#e8d9bb>Cahaya emas yang mempesona menembus laut, dan guntur buatan melintasi kabut hitam dari pusatnya.</color>",
  ui_story_5075_50751402_55_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50751402_56_dialog_content = "<color=#e8d9bb>Sebelum kabut hitam, yang mencoba mengental, dapat mengisi celah sebelumnya, ia kembali hancur.</color>",
  ui_story_5075_50751402_57_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50751402_58_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50751402_59_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5075_50751402_60_dialog_content = "<color=#e8d9bb>Setelah bombardir yang berat, akhirnya laut kembali tenang.</color>",
  ui_story_5075_50751402_61_dialog_content = "Tidak akan kembali?",
  ui_story_5075_50751402_62_dialog_content = "Benar. Itu benar-benar menghilang tanpa jejak sebelum sempat bereaksi.",
  ui_story_5075_50751402_63_dialog_content = "Apakah ini juga salah satu penemuan kecilmu saat aku tertidur?",
  ui_story_5075_50751402_64_dialog_content = "J-Jangan masukkan kepalamu ke dalam tong!",
  ui_story_5075_50751402_65_dialog_content = "Santai, aku sudah mematikannya.",
  ui_story_5075_50751402_66_dialog_content = "Bukankah Anda memiliki urusan penting kembali di Kerajaan Ye, Xuan Ji?",
  ui_story_5075_50751402_67_dialog_content = "Ya, tapi siapa yang tahu aku akan mendapatkan panggilan dari Putri Dantang di tengah jalan?",
  ui_story_5075_50751402_68_dialog_content = "Aku menduga Ji dalam masalah yang lebih besar, jadi aku mengambil alih <color=#FFB400>blaster misterius</color> yang paling canggih untuk penguatan.",
  ui_story_5075_50751402_69_dialog_content = "Hanya untuk Yang Mulia tidak hadir...",
  ui_story_5075_50751402_70_dialog_content = "Meski melihatmu sudah cukup baik, PlayerName!",
  ui_story_5075_50751402_71_dialog_content = "Dantang saat ini berada di kota.",
  ui_story_5075_50751402_72_dialog_content = "Karena semuanya sudah kembali normal sekarang, kenapa tidak kembali bersama kami dan merayakan Festival Musim Semi di Haojin?",
  ui_story_5075_50751402_73_dialog_content = "Oh, saya ingat betapa serunya upacara Tahun Baru untuk mengusir monster di Haojin.",
  ui_story_5075_50751402_74_dialog_content = "Sayang sekali aku harus bergegas kembali ke Ye untuk urusan yang belum selesai.",
  ui_story_5075_50751402_75_dialog_content = "Kamu juga harus kembali dan jangan sampai melewatkan perayaan. Kita akan berkumpul lagi nanti.",
  ui_story_5075_50751402_76_dialog_content = "Jangan lupa sampaikan salam saya kepada Tuan Putri Dantang.",
  ui_story_5075_50751402_77_dialog_content = "Baiklah, semoga berhasil dengan bisnis resmi Anda.",
  ui_story_5075_50751402_78_dialog_content = "Aku akan mengirim Clockwork Bird jika ada yang terjadi!",
  ui_story_5075_50751402_79_dialog_content = "Hmm, ini terasa seperti kekecewaan.",
  ui_story_5075_50751402_80_dialog_content = "Saya datang jauh-jauh dari Ye dengan blaster arcane hanya untuk penampilan singkat.",
  ui_story_5075_50751402_81_dialog_content = "Tapi meski tidak ada yang memuji saya sebagai pahlawan saat itu, sekarang saya mendapatkan cukup banyak pengikut.",
  ui_story_5075_50751402_82_dialog_content = "Lady Xuan Ji.",
  ui_story_5075_50751402_83_dialog_content = "Kamu telah mengambil senjata rahasia tingkat tinggi tanpa izin.",
  ui_story_5075_50751402_84_dialog_content = "Dan kamu bahkan menyelundupkan senjata-senjata ini ke kerajaan lain. Sekarang kamu dicurigai melakukan pengkhianatan.",
  ui_story_5075_50751402_X84_dialog_content = "Nah, masih bisa diperdebatkan apakah kalian mewakili Kerajaan Ye...",
  ui_story_5075_50751402_85_dialog_content = "Apakah raja yang mengirimmu?",
  ui_story_5075_50751402_86_dialog_content = "Memang, kami, di bawah perintah rahasia dari <color=#FFB400>Raja Ye</color>, akan menangkapmu. Apakah kamu akan membantah perintah ini?",
  ui_story_5075_50751402_87_dialog_content = "... Sama sekali tidak.",
  ui_story_5075_50751402_88_dialog_content = "Saya adalah warga Ye, belum lagi mantan penasihat negara dan tokoh terkemuka.",
  ui_story_5075_50751402_89_dialog_content = "Saya menolak untuk mengikuti siapa pun yang merugikan kepentingan Ye tetapi tidak akan pernah membantah perintah raja.",
  ui_story_5075_50751402_90_dialog_content = "Saya mengaku bersalah.",
  ui_story_5075_50751402_91_dialog_content = "...",
  ui_story_5075_50751402_92_dialog_content = "Ayo, jangan tampak begitu kecewa.",
  ui_story_5075_50751402_93_dialog_content = "Ini adalah pertama kalinya saya merayakan Tahun Baru di penjara, jadi saya menghargai jika kamu memberi tahu saya saat saya gagal mengikuti protokol.",
  ui_story_5075_50751501_1_dialog_content = "<color=#e8d9bb>Dor! Dor!</color>",
  ui_story_5075_50751501_2_dialog_content = "Wow, pertunjukan kembang api!",
  ui_story_5075_50751501_3_dialog_content = "Setelah hanya satu malam, seluruh kota menjadi ramai dengan perayaan.",
  ui_story_5075_50751501_4_dialog_content = "Arwah jahat telah dibersihkan, dan kesalahpahaman antara manusia dan setan telah diselesaikan.",
  ui_story_5075_50751501_5_dialog_content = "Semua orang harus dapat menikmati Festival Musim Semi yang bebas cemas besok.",
  ui_story_5075_50751501_6_dialog_content = "Apakah Yoh juga kembali ke laut?",
  ui_story_5075_50751501_7_dialog_content = "Ya. Dia bilang dia perlu sendirian untuk beberapa waktu untuk memutuskan apa yang harus dilakukan selanjutnya.",
  ui_story_5075_50751501_8_dialog_content = "Kamu pikir dia akan membalas dendam pada Keluarga Lin?",
  ui_story_5075_50751501_9_dialog_content = "Saya tidak yakin.",
  ui_story_5075_50751501_10_dialog_content = "Tapi setidaknya, kita berhasil menyelesaikan perbedaan masa lalu kita. Adapun untuk masa depan...",
  ui_story_5075_50751501_11_dialog_content = "Itu adalah pertanyaan untuk besok, bukan menurutmu?",
  ui_story_5075_50751501_12_dialog_content = "\"Merry Tahun Baru,\" benar?",
  ui_story_5075_50751501_13_dialog_content = "Li Tianxian ternyata tidak berbohong. Mantra kuno ini benar-benar manjur!",
  ui_story_5075_50751501_14_dialog_content = "?",
  ui_story_5075_50751501_15_dialog_content = "...Heh.",
  ui_story_5075_50751501_16_dialog_content = "K-Kenapa kamu tertawa, Yuebai? Ini bukan semacam lelucon, kan?",
  ui_story_5075_50751501_17_dialog_content = "Tidak.",
  ui_story_5075_50751501_18_dialog_content = "Ini benar-benar mantra yang kuat.",
  ui_story_5075_50751501_19_dialog_content = "Saya masih memiliki urusan untuk dihadiri dengan Keluarga Lin. Sampai jumpa lain waktu.",
  ui_story_5075_50751501_20_dialog_content = "Tentu, sampai jumpa nanti.",
  ui_story_5075_50751501_21_dialog_content = "<color=#e8d9bb>Meretih dan pop!</color>",
  ui_story_5075_50751501_22_dialog_content = "Ada apa?",
  ui_story_5075_50751501_23_dialog_content = "Upacara pengusir monster sedang menuju ke arah ini!",
  ui_story_5075_50751501_24_dialog_content = "Chen'ni? Ke mana saja kamu dari tadi?",
  ui_story_5075_50751501_25_dialog_content = "Dan kapan kamu mendapatkan semua camilan itu?",
  ui_story_5075_50751501_26_dialog_content = "Saya agak membuat putaran dengan tanduk naga saya terlihat, dan para penjual hanya memenuhi saya dengan ini!",
  ui_story_5075_50751501_27_dialog_content = "Oh, benar juga, PlayerName tidak memiliki tanduk atau ekor.",
  ui_story_5075_50751501_28_dialog_content = "Jangan merasa sedih. Aku akan membagi jarahan denganmu.",
  ui_story_5075_50751501_29_dialog_content = "Terima kasih, tapi itu tidak terlalu mengganggu saya.",
  ui_story_5075_50751501_30_dialog_content = "Lihat, Luo Song adalah salah satu penampil.",
  ui_story_5075_50751501_31_dialog_content = "Tidak bercanda! Dan lihat, ada banyak fiendlings bersamanya juga!",
  ui_story_5075_50751501_32_dialog_content = "Petasan meledak, mengusir monster pergi, menghilangkan kesialan dengan cara yang penuh kegembiraan.",
  ui_story_5075_50751501_33_dialog_content = "Berkah terbuka dengan pertanda baik. Menyambut musim semi, kebahagiaan menerangi setiap wajah!",
  ui_story_5075_50751501_34_dialog_content = "Tunggu, aku pikir mereka seharusnya mengusir monster? Kenapa fiendlings juga pengejar?",
  ui_story_5075_50751501_35_dialog_content = "Mereka mengubahnya tahun ini—bukan mengusir setan kecil, tetapi roh jahat.",
  ui_story_5075_50751501_36_dialog_content = "Tidakkah kamu melihat manifestasi Dragon Maiden semalam? Dia membasmi semua roh jahat, meninggalkan para setan kecil tak tersentuh.",
  ui_story_5075_50751501_37_dialog_content = "Itu berarti bahkan Sang Maiden Naga menganggap fiendlings tidak berbahaya, bukan?",
  ui_story_5075_50751501_38_dialog_content = "Dengarkan! Kamu perlu belajar bekerja sama jika ingin mengalahkan lawan yang kuat!",
  ui_story_5075_50751501_39_dialog_content = "Dengan menggabungkan kekuatan unikmu, kekuatanmu akan meningkat secara dramatis!",
  ui_story_5075_50751501_40_dialog_content = "Baiklah Ah Ding, minta teman barumu membantumu menunjukkan kepada semua orang apa yang saya maksud!",
  ui_story_5075_50751501_41_dialog_content = "Ha.",
  ui_story_5075_50751501_42_dialog_content = "Groar!",
  ui_story_5075_50751501_43_dialog_content = "Apakah saya melihat sesuatu?",
  ui_story_5075_50751501_44_dialog_content = "Kenapa kucing itu terlihat sangat familiar?",
  ui_story_5075_50751501_45_dialog_content = "<color=#e8d9bb>Meretih dan pop!</color>",
  ui_story_5075_50751501_46_dialog_content = "Petasan meledak, mengusir monster... Adhuh!",
  ui_story_5075_50751501_47_dialog_content = "Maaf, saya tidak memperhatikan ke mana saya pergi dan menabrakmu... Oh.",
  ui_story_5075_50751501_48_dialog_content = "Ya?",
  ui_story_5075_50751501_49_dialog_content = "Oh, itu bocah yang tadi mengganggu si kecil nakal itu.",
  ui_story_5075_50751501_50_dialog_content = "Jadi, eh... Nona, kamu juga seorang fiendling, bukan?",
  ui_story_5075_50751501_51_dialog_content = "Ini permen untukmu!",
  ui_story_5075_50751501_52_dialog_content = "Dan... jika kamu kenal setan kecil mana pun yang telah kami perlakukan dengan buruk, tolong beri tahu mereka bahwa aku minta maaf!",
  ui_story_5075_50751501_53_dialog_content = "Dia kabur...",
  ui_story_5075_50751501_54_dialog_content = "Kurasa opini orang-orang terhadap fiendlings benar-benar mulai berubah.",
  ui_story_5075_50751501_55_dialog_content = "Hmm... Wow!",
  ui_story_5075_50751501_56_dialog_content = "Ini sangat manis.",
  ui_story_5075_50751501_57_dialog_content = "Kupikir melihat ini akan membuatmu merasa senang, Chen'ni.",
  ui_story_5075_50751501_58_dialog_content = "Aku senang.",
  ui_story_5075_50751501_59_dialog_content = "Lalu, kenapa rasanya...",
  ui_story_5075_50751501_60_dialog_content = "Kebahagiaanmu tidak berbeda dengan kebahagiaan yang kamu rasakan kemarin atau bahkan hari sebelumnya.",
  ui_story_5075_50751501_61_dialog_content = "Nah, begitulah adanya di dunia ini.",
  ui_story_5075_50751501_62_dialog_content = "Orang-orang berbalik melawan fiendlings suatu hari karena mereka takut, lalu memperlakukan mereka dengan baik karena rasa bersalah di hari berikutnya.",
  ui_story_5075_50751501_63_dialog_content = "Siapa yang tahu bagaimana mereka akan melihat fiendlings besok.",
  ui_story_5075_50751501_64_dialog_content = "Kamu mungkin mendapatkan kudapan lezat kemarin, yang tidak enak hari ini, dan kemudian yang lezat lagi besok.",
  ui_story_5075_50751501_65_dialog_content = "Selalu ada baik dan buruk, tapi yang baik tidak akan selalu baik, dan yang buruk tidak akan selalu buruk.",
  ui_story_5075_50751501_66_dialog_content = "Saya rasa saya suka seperti itu.",
  ui_story_5075_50751501_67_dialog_content = "Aku... tidak bisa bilang bahwa aku benar-benar mengerti apa yang kamu rasakan, Chen'ni.",
  ui_story_5075_50751501_68_dialog_content = "Tapi setelah semua yang telah kita lalui, aku rasa semuanya sedikit lebih masuk akal sekarang.",
  ui_story_5075_50751501_69_dialog_content = "Di mata Anda, setiap makhluk hidup itu sama persis. Tidak ada bedanya bagi Anda apakah mereka manusia, makhluk jahat, atau apapun itu.",
  ui_story_5075_50751501_70_dialog_content = "Semua makhluk memiliki makna di balik keberadaan mereka.",
  ui_story_5075_50751501_71_dialog_content = "Dan karena kamu menghargai makna itu, kamu mencoba untuk tidak ikut campur dalam dunia kita.",
  ui_story_5075_50751501_72_dialog_content = "Bukan karena kamu tidak peduli pada kami, tetapi karena kamu memperlakukan semua orang dengan sama.",
  ui_story_5075_50751501_73_dialog_content = "Jika itu masalahnya, saya yakin masalah-masalah kita beberapa hari terakhir ini pasti terasa sangat sepele bagi Anda.",
  ui_story_5075_50751501_74_dialog_content = "Semoga, kami tidak terlalu mengecewakanmu.",
  ui_story_5075_50751501_75_dialog_content = "Jadi, apa yang akan kamu lakukan sekarang, Chen'ni?",
  ui_story_5075_50751501_76_dialog_content = "Aku keluar karena aku terbangun dengan kasar.",
  ui_story_5075_50751501_77_dialog_content = "Jadi, aku akan kembali tidur sebentar lagi.",
  ui_story_5075_50751501_78_dialog_content = "Begitu cepat?",
  ui_story_5075_50751501_79_dialog_content = "Utusan! Raja meminta kehadiranmu di istana.",
  ui_story_5075_50751501_80_dialog_content = "Tentu.",
  ui_story_5075_50751501_81_dialog_content = "Chen'ni, mau ikut? Chen'ni?",
  ui_story_5075_50751501_82_dialog_content = "Sudah pergi, huh?",
  ui_story_5075_50751501_83_dialog_content = "Terima kasih untuk segalanya, PlayerName.",
  ui_story_5075_50751501_84_dialog_content = "Kali ini—",
  ui_story_5075_50751501_85_dialog_content = "PlayerName! PlayerName!",
  ui_story_5075_50751501_86_dialog_content = "Saya telah mendengar segalanya dari Dantang. Dia bilang Anda mengambil alih dalam krisis, menunjukkan kebijaksanaan dan keberanian yang tak tertandingi.",
  ui_story_5075_50751501_87_dialog_content = "Bukan hanya kamu yang membongkar penjahat di pengadilan Kerajaan Ji, tetapi surutnya banjir kemarin juga diatribusikan kepada kamu!",
  ui_story_5075_50751501_88_dialog_content = "Saya percaya saya tidak berlebihan dalam melaporkan hal ini, Pangeran Mahkota.",
  ui_story_5075_50751501_89_dialog_content = "Bagaimanapun, saya tahu sekarang bahwa PlayerName adalah seorang pahlawan besar!",
  ui_story_5075_50751501_90_dialog_content = "Kamu luar biasa, pahlawan! <size=45>Aku ingin menikah dengan PlayerName!</size>",
  ui_story_5075_50751501_91_dialog_content = "<size=45>... Apa?</size>",
  ui_story_5075_50751501_92_dialog_content = "Seperti pepatah, suami dan istri adalah satu. Dengan tunangan yang luar biasa seperti kamu, saya pasti akan menjadi pahlawan juga!",
  ui_story_5075_50751501_93_dialog_content = "<size=45>Ahem!</size>",
  ui_story_5075_50751501_94_dialog_content = "Segera kawal pangeran kembali!",
  ui_story_5075_50751501_95_dialog_content = "Beritahu tutornya untuk mengajari dia makna pernikahan dan membuatnya berhenti dari semua omong kosong ini yang hampir saja saya percayai...",
  ui_story_5075_50751501_96_dialog_content = "Namun, komentar lainnya tidak salah.",
  ui_story_5075_50751501_97_dialog_content = "Krisis di Haojin adalah kesalahan perhitungan dari saya, dan berkat kamu bencana tersebut dapat dihindari.",
  ui_story_5075_50751501_98_dialog_content = "Oleh karena itu, jangan ragu untuk memberitahuku apa saja yang kamu inginkan, dan aku pasti akan mengabulkannya.",
  ui_story_5075_50751501_99_dialog_content = "Dalam hal ini, Dantang dan saya ingin berbagi rencana kami dengan Anda untuk meningkatkan hubungan antara dua tanah kita!",
  ui_story_5075_50751501_100_dialog_content = "Itu saja? Apakah kamu tidak menginginkan emas, harta karun, atau posisi berkuasa?",
  ui_story_5075_50751501_101_dialog_content = "Sejujurnya, itu tidak sepenuhnya salah. Tapi saya datang ke Longzhou sebagai utusan resmi Astra.",
  ui_story_5075_50751501_102_dialog_content = "Menyelesaikan misiku adalah prioritas utamaku.",
  ui_story_5075_50751501_103_dialog_content = "Hahaha, untuk bakat muda seperti kamu, entah kenapa saya tidak ingin membiarkanmu pergi.",
  ui_story_5075_50751501_104_dialog_content = "Tapi karena kamu tidak mau tinggal di Longzhou, bagaimana dengan ini?",
  ui_story_5075_50751501_105_dialog_content = "Dengan ini saya nyatakan Anda sebagai Warga Kehormatan Kerajaan Ji.",
  ui_story_5075_50751501_106_dialog_content = "Tidak peduli ke mana pun kamu pergi atau apa yang kamu lakukan setelah ini, Kerajaan Ji akan selalu menyambutmu.",
  ui_story_5075_50751501_107_dialog_content = "Terima kasih, Tuhan!",
  ui_story_5075_50751501_108_dialog_content = "Fiuh... Kita menghabiskan banyak waktu di istana, dan sekarang sudah mulai larut.",
  ui_story_5075_50751501_109_dialog_content = "Setelah pengurus rumah tangga ditangkap, mereka juga memecat semua pengawal dan pelayan tersebut.",
  ui_story_5075_50751501_110_dialog_content = "Sepertinya ini pertama kalinya saya di sini sendirian.",
  ui_story_5075_50751501_111_dialog_content = "... Sunyi sekali.",
  ui_story_5075_50751501_112_dialog_content = "Sekarang setelah segalanya akhirnya mereda, saya tidak yakin apa yang harus saya lakukan.",
  ui_story_5075_50751501_113_dialog_content = "Oh ya, Festival Musim Semi adalah besok.",
  ui_story_5075_50751501_114_dialog_content = "Dari yang saya dengar, setiap keluarga di Longzhou akan begadang semalaman hari ini sambil makan dan bersantai bersama.",
  ui_story_5075_50751501_115_dialog_content = "Ini cara mereka mengucapkan selamat tinggal pada tahun lalu dan menyambut tahun baru.",
  ui_story_5075_50751501_116_dialog_content = "Mungkin aku juga harus melakukan hal seperti itu... Ah, tidak ada gunanya begadang sendirian semalaman.",
  ui_story_5075_50751501_117_dialog_content = "Aku penasaran apa yang semua orang lakukan sekarang...",
  ui_story_5075_50751501_118_dialog_content = "Menunggu PlayerName untuk memperhatikan saya.",
  ui_story_5075_50751501_119_dialog_content = "Hah? K-Kapan kamu masuk ke sini?",
  ui_story_5075_50751501_120_dialog_content = "Aku sudah ada di sini sebelum kamu kembali.",
  ui_story_5075_50751501_121_dialog_content = "Hanya untuk melihatmu berkeliaran tanpa memperhatikan apa pun, jadi aku harus menampakkan diri.",
  ui_story_5075_50751501_122_dialog_content = "Jadi, kamu melihat itu, ya...",
  ui_story_5075_50751501_123_dialog_content = "Kukira kamu sudah pergi.",
  ui_story_5075_50751501_124_dialog_content = "Kamu bilang kamu akan kembali ke laut sebentar lagi, setelah semua ini.",
  ui_story_5075_50751501_125_dialog_content = "Benar. Saya tidak berencana untuk tinggal lama.",
  ui_story_5075_50751501_126_dialog_content = "Aku akan kembali dalam beberapa dekade.",
  ui_story_5075_50751501_127_dialog_content = "Tunggu, apa? Beberapa dekade hanya \"sebentar\" bagi kamu?",
  ui_story_5075_50751501_128_dialog_content = "Apakah itu terlalu cepat?",
  ui_story_5075_50751501_129_dialog_content = "Aku suka bergaul denganmu.",
  ui_story_5075_50751501_130_dialog_content = "Jadi jika Anda tidak keberatan, mungkin bagi saya untuk tetap di sini selama seratus tahun atau dua.",
  ui_story_5075_50751501_131_dialog_content = "... Maaf, aku lupa bahwa makhluk jahat utama memiliki rasa waktu yang sepenuhnya berbeda dari kita.",
  ui_story_5075_50751501_132_dialog_content = "Tapi kenapa kamu tidak memiliki apa-apa di sini, PlayerName?",
  ui_story_5075_50751501_133_dialog_content = "Saatnya untuk makanan Tahun Baru Eve.",
  ui_story_5075_50751501_134_dialog_content = "Haha, sepertinya aku lupa.",
  ui_story_5075_50751501_135_dialog_content = "Nah, ini adalah lembaran tahu yang baru saja saya dapatkan sebagai persembahan. Ambil saja.",
  ui_story_5075_50751501_136_dialog_content = "Terima kasih... Eh, lembaran tahu?",
  ui_story_5075_50751501_137_dialog_content = "PlayerName! Chen'ni!",
  ui_story_5075_50751501_138_dialog_content = "Di mana kalian berdua?",
  ui_story_5075_50751501_139_dialog_content = "Apakah itu Luo Song?",
  ui_story_5075_50751501_140_dialog_content = "Luo Song! Disini!",
  ui_story_5075_50751501_141_dialog_content = "Ah, kalian berada di sana! Senang akhirnya aku menemukan kalian berdua.",
  ui_story_5075_50751501_142_dialog_content = "Seharusnya aku bertanya di mana kamu menginap sebelum aku pergi.",
  ui_story_5075_50751501_143_dialog_content = "Tunggu, apakah kamu telah berjalan di jalanan sambil meneriakkan nama kami selama ini?",
  ui_story_5075_50751501_144_dialog_content = "Haha, saya tahu itu bukan cara paling pintar untuk mencari kamu, tapi cara itu berhasil, 'kan?",
  ui_story_5075_50751501_145_dialog_content = "Setelah semua yang telah kita lalui, kamu tidak keberatan membiarkanku merayakan tahun baru bersamamu, bukan?",
  ui_story_5075_50751501_146_dialog_content = "Tentu saja tidak!",
  ui_story_5075_50751501_147_dialog_content = "Senang mendengarnya.",
  ui_story_5075_50751501_148_dialog_content = "Pokoknya, aku membantu seorang wanita tua memindahkan beberapa barang tadi, dan dia memberiku kantong seledri ini sebagai balas jasaku.",
  ui_story_5075_50751501_149_dialog_content = "Setidaknya, kita bisa menggunakannya untuk memasak sesuatu untuk malam ini.",
  ui_story_5075_50751501_150_dialog_content = "Astaga, tempat ini bahkan lebih sepi daripada stan ramalan nasibku.",
  ui_story_5075_50751501_151_dialog_content = "Li Tianxian, kau juga ada di sini?",
  ui_story_5075_50751501_152_dialog_content = "Untuk mengemis... maksud saya, untuk memeriksa keadaanmu, mengingat kamu berada di negeri asing dan semuanya.",
  ui_story_5075_50751501_153_dialog_content = "Tidak bisa percaya kamu bahkan tidak menyiapkan makanan. Aku rasa kamu beruntung aku ada di sini.",
  ui_story_5075_50751501_154_dialog_content = "Ini, hadiah Tahun Baru dariku.",
  ui_story_5075_50751501_155_dialog_content = "Saya menghargai niat baiknya dan semuanya, tapi kenapa memberi saya banyak sayuran liar?",
  ui_story_5075_50751501_156_dialog_content = "Ini bukan sayuran biasa. Ini adalah tas gembala dan sulit ditemukan di musim dingin.",
  ui_story_5075_50751501_157_dialog_content = "Aku harus mendapatkan batch dari rumah kaca, dan itu menghabiskan semua keuntungan yang aku dapat dari figur gula.",
  ui_story_5075_50751501_158_dialog_content = "Ini melambangkan keberuntungan dan rezeki, jadi dompet Anda akan penuh sepanjang tahun!",
  ui_story_5075_50751501_159_dialog_content = "Dan kamu juga punya lembaran tahu. Itu adalah pertanda baik dan membawa kemakmuran untuk generasi yang akan datang.",
  ui_story_5075_50751501_160_dialog_content = "Seledri juga tidak buruk. Itu berarti uang melalui kerja keras.",
  ui_story_5075_50751501_161_dialog_content = "Ayo bantu aku, PlayerName—",
  ui_story_5075_50751501_162_dialog_content = "Seorang anggota guild mengirimkan kita sekeranjang penuh umbi lotus segar. Saya pikir kamu tidak menyiapkan bahan apa pun malam ini, jadi saya membawakan beberapa untukmu.",
  ui_story_5075_50751501_163_dialog_content = "Seluruh muatan kereta?",
  ui_story_5075_50751501_164_dialog_content = "Ambil saja. Semua barang berkualitas, kamu tahu.",
  ui_story_5075_50751501_165_dialog_content = "Saya melihat tanda-tanda yang menunjukkan keberuntungan baik untukmu di mana-mana.",
  ui_story_5075_50751501_166_dialog_content = "Kamu pikir semuanya menguntungkan, bukan?",
  ui_story_5075_50751501_167_dialog_content = "Ini Tahun Baru, tentu saja segalanya adalah tanda baik.",
  ui_story_5075_50751501_168_dialog_content = "Saya bisa mendengar Li melakukan penipuan dari jarak satu mil.",
  ui_story_5075_50751501_169_dialog_content = "Meski menyenangkan untuk berbicara dengan baik di Tahun Baru Eve.",
  ui_story_5075_50751501_170_dialog_content = "Sudah lama, PlayerName.",
  ui_story_5075_50751501_171_dialog_content = "Dantang? Jiu? Bukankah seharusnya kau merayakan tahun baru di istana?",
  ui_story_5075_50751501_172_dialog_content = "Kita seharusnya.",
  ui_story_5075_50751501_173_dialog_content = "Tapi karena jasa Anda selama beberapa hari terakhir, PlayerName, raja menugaskan saya untuk tugas khusus.",
  ui_story_5075_50751501_174_dialog_content = "Saya akan memastikan Anda menikmati Tahun Baru.",
  ui_story_5075_50751501_175_dialog_content = "Ada gerobak makanan di luar istana. Aku akan memasak sendiri dan membuat hidangan yang sesuai untuk hari libur.",
  ui_story_5075_50751501_176_dialog_content = "Oh, saya juga ingin memberikan berkat saya.",
  ui_story_5075_50751501_177_dialog_content = "Dengan piring ini penuh dengan bunga daylilies kuning emas, PlayerName...",
  ui_story_5075_50751501_178_dialog_content = "Aku berharap masa depanmu cerah.",
  ui_story_5075_50751501_179_dialog_content = "Kurasa aku akan menawarkanmu polong kacang. Mereka melambangkan panen yang melimpah di Longzhou.",
  ui_story_5075_50751501_180_dialog_content = "Wow, saya melihat begitu banyak orang!",
  ui_story_5075_50751501_181_dialog_content = "Dan aku khawatir PlayerName akan menghabiskan Tahun Baru Eve sendirian.",
  ui_story_5075_50751501_182_dialog_content = "Bagus bagi teman muda kita untuk menjadi sepopuler ini.",
  ui_story_5075_50751501_183_dialog_content = "Zhong Xu! Liqing! Kamu guys juga di sini!",
  ui_story_5075_50751501_184_dialog_content = "Dari mana semua makanan ini di meja berasal? Oh, aku tahu!",
  ui_story_5075_50751501_185_dialog_content = "Kamu sedang membuat Ten Scenic, bukan?",
  ui_story_5075_50751501_186_dialog_content = "Apa itu?",
  ui_story_5075_50751501_187_dialog_content = "Ini adalah hidangan tradisional Ji yang terkenal dengan puluhan sayuran tipis yang digoreng.",
  ui_story_5075_50751501_188_dialog_content = "Itu menggabungkan semua pertanda baik di satu piring.",
  ui_story_5075_50751501_189_dialog_content = "Ini adalah kebutuhan Festival Musim Semi di Ji.",
  ui_story_5075_50751501_190_dialog_content = "Tapi, aku melihat masih ada sesuatu yang kurang di sini.",
  ui_story_5075_50751501_191_dialog_content = "Izinkan saya untuk berkontribusi sawi ke dalam tujuan ini dan berharap semua orang memiliki karir yang hebat.",
  ui_story_5075_50751501_192_dialog_content = "Aku akan menambahkan sedikit hogweed sebagai ukuran baik.",
  ui_story_5075_50751501_193_dialog_content = "Ini bukan hanya sayuran, tapi juga rempah anti-toksin.",
  ui_story_5075_50751501_194_dialog_content = "Kamu benar-benar menguji kemampuan kulinerku dengan bahan-bahan eksotis seperti ini.",
  ui_story_5075_50751501_195_dialog_content = "Oh, ini sama sekali tidak akan menjadi tantangan bagi Anda, Yang Mulia.",
  ui_story_5075_50751501_196_dialog_content = "Yakin, Jiu? Kenapa tidak kamu bantu saya di dapur saja?",
  ui_story_5075_50751501_197_dialog_content = "Sini, aku juga mau membantu.",
  ui_story_5075_50751501_198_dialog_content = "Serahkan mencicipinya padaku.",
  ui_story_5075_50751501_199_dialog_content = "Aku bisa mencicipinya!",
  ui_story_5075_50751501_200_dialog_content = "Baiklah, aku tidak bisa melawanmu untuk itu, jadi silakan, ambillah.",
  ui_story_5075_50751501_201_dialog_content = "Aku akan keluar dan mengurutkan bahan-bahannya. Cukup beri tahu aku apa yang kamu butuhkan dan aku akan membawanya masuk.",
  ui_story_5075_50751501_202_dialog_content = "Aku juga membawa beberapa hiasan untuk ditempatkan di seluruh ruangan.",
  ui_story_5075_50751501_203_dialog_content = "Itu luar biasa. Saya baru saja berpikir tempat ini bisa lebih meriah!",
  ui_story_5075_50751501_204_dialog_content = "Berikut adalah Sepuluh Pemandangan yang semua orang telah berpartisipasi di dalamnya.",
  ui_story_5075_50751501_205_dialog_content = "Sebelum lonceng Kuil Gadis Naga berdentang dalam beberapa menit untuk resmi menyambut Tahun Baru...",
  ui_story_5075_50751501_206_dialog_content = "Rasa terima kasih saya untuk semua yang telah Anda lakukan untuk saya di tahun lalu, PlayerName.",
  ui_story_5075_50751501_207_dialog_content = "Saya tidak pandai berbicara, jadi saya hanya akan bilang \"Terima kasih!\"",
  ui_story_5075_50751501_208_dialog_content = "Saya menghargai bisnis Anda tahun lalu dan menantikan patronase Anda tahun depan.",
  ui_story_5075_50751501_209_dialog_content = "Saya berterima kasih atas bantuan Anda dalam perjalanan kita sebelumnya, teman muda. Saya berharap Anda memiliki tahun baru yang indah.",
  ui_story_5075_50751501_210_dialog_content = "Saya berterima kasih untuk segalanya. Tetap sehat agar Anda tidak perlu datang ke saya untuk pengobatan!",
  ui_story_5075_50751501_211_dialog_content = "Kita mungkin baru saja bertemu, tapi saya sudah menganggap kamu sebagai teman baik.",
  ui_story_5075_50751501_212_dialog_content = "Bersulang untuk tahun baru! Semoga kamu memiliki kekuatan yang dibutuhkan untuk mengalahkan setiap roh jahat yang menghadangmu!",
  ui_story_5075_50751501_213_dialog_content = "Tos, dan Selamat Tahun Baru!",
  ui_story_5075_50751501_214_dialog_content = "*glek*",
